-- 0283 miradores_pdf (inventario_miradores_pdf) — borra placeholder + entidades + puntuaciones reales
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18049','mirador','Mirador del Peñón de la Mata','8.4/10 Espectacular hito calizo con vistas del somontano norte de Sierra Nevada, bosques de encina y la Hoya de Guadix. Cómo llegar: Pista forestal transitable que asciende desde el casco urbano hacia las estribaciones serranas. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90432','mirador','Mirador del Peñón de la Cruz','8.6/10 Vista vertical del desfiladero del río Bermejo, olivares escarpados y las escarpadas cumbres kársticas del Parque Natural Sierra de Huétor. Cómo llegar: Mirador urbano con barandilla perimetral en la zona más elevada del barrio del Castillo. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18051','mirador','Mirador del Castillo de Colomera','8.8/10 Imponente atalaya sobre el espolón rocoso que domina el mar de olivos, el puente romano y la gran lámina del embalse. Cómo llegar: Corona de las ruinas de la fortaleza árabe, accesible por sendero peatonal empedrado desde la iglesia. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18053','mirador','Mirador de los Badlands de las Cuevas','8.2/10 Singular perspectiva de cárcavas desérticas ocres que contrastan con los sotos verdes del río Castril y las viviendas excavadas. Cómo llegar: Loma arcillosa acondicionada junto al barrio periférico de casas-cueva tradicionales. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18054','mirador','Mirador de Graena','8.5/10 Vista panorámica del valle del río Alhama, huertas tradicionales andalusíes y un laberinto de chimeneas de hadas arcillosas. Cómo llegar: Calle del Mirador, barandilla de madera sobre el escarpe natural de la pedanía de los Baños. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18912','mirador','Mirador del Embalse del Negratín (El Negratín)','8.7/10 Impresionante mar interior turquesa encajonado entre desiertos de arcilla roja, con el cerro Jabalcón recortando el fondo. Cómo llegar: Prolongación de la pista recreativa del club náutico, balcón vallado sobre los acantilados arcillosos. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18056','mirador','Mirador del Templo de los Orcos','8.1/10 Vista horizontal del altiplano y la rambla de Cúllar desde un entorno arqueológico de gran valor paleontológico. Cómo llegar: Cerro de la torre nazarí exenta, sendero señalizado desde la carretera nacional. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18057','mirador','Mirador de los Secaderos de Tabaco','7.1/10 Paisaje agrícola plano y etnográfico de la Vega baja con campos de maíz y secaderos tradicionales de ladrillo. Cómo llegar: Paseo peatonal que discurre paralelo a la acequia del Jacín, límite del casco urbano. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18063','mirador','Mirador de Sierra Arana (Puerto de la Mora)','8.3/10 Vista de pájaro del gran paso de montaña de la autovía A-92, rodeado de encinares y pinares de repoblación altos. Cómo llegar: Área de servicio y mirador acondicionado en el kilómetro 242 de la autovía escénica. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18064','mirador','Mirador del Barranco del Infierno (Badlands)','8.9/10 Abrumador cañón desértico con colosales crestas arcillosas rojas y amarillas de aspecto marciano, integrado en el Geoparque. Cómo llegar: Final de la pista forestal transitable desde el río Fardes, borde del precipicio calizo excavado. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18065','mirador','Mirador del llano olivarero','7.4/10 Vista de las lomas ordenadas de olivar del norte provincial de la comarca de Los Montes Orientales. Cómo llegar: Pista agrícola elevada contigua a los depósitos reguladores de agua de la localidad. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18066','mirador','Mirador del Nacimiento del Agua (El Nacimiento)','8.0/10 Entorno de olivos y pinares que arropa el espectacular brote de agua del río Cubillas formando canales tradicionales. Cómo llegar: Paraje natural acondicionado de El Nacimiento, senderos peatonales y compuertas de riego. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18067','mirador','Mirador del Castillo de Diezma','8.8/10 Espectacular postal de Sierra Nevada desde su vertiente norte, con el pueblo blanco y las peñas calizas de fondo. Cómo llegar: Arcén habilitado con murete de piedra en la carretera de montaña de circunvalación. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18068','mirador','Mirador de la Ermita de la Vieja','9.2/10 Majestuoso anfiteatro alpino del Parque Nacional sobre el río Dílar con pinares, robledales y el Trevenque dominando. Cómo llegar: Explanada de piedra del santuario, pista forestal que sube desde el área recreativa. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18069','mirador','Mirador del Marquesado - Cerro del Castillo','8.3/10 Transición limpia entre la llanura esteparia del Zenete y los primeros pliegues de encinas que suben al puerto de la Ragua. Cómo llegar: Corona del cerro calizo donde se levantan los restos de la torre defensiva medieval alta. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18070','mirador','Mirador del Canal de los Franceses','7.8/10 Vista encajada del curso medio del río Darro con espectculares restos de la antigua obra hidráulica del siglo XIX. Cómo llegar: Sendero de montaña señalizado que parte de las afueras residenciales del municipio. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18071','mirador','Mirador del Puente de Lata','8.9/10 Impresionante e histórica estructura de hierro de la escuela de Eiffel salvando un profundo tajo sobre el río Dúrcal. Cómo llegar: Plataforma peatonal del antiguo puente de herradura de la carretera nacional vieja. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18072','mirador','Mirador del Parque Tecnológico Citai','7.1/10 Vista horizontal del llano del Temple combinado con naves logísticas modernas y campos de trigo de secano. Cómo llegar: Zona elevada de la rotonda principal del parque industrial contigua a los campos. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18074','mirador','Mirador del Puerto de la Ragua','8.5/10 Espectacular paso alpino a 2.000 metros rodeado de pinares negros con vistas que alcanzan la Alpujarra y el mar. Cómo llegar: Estación recreativa del puerto de montaña de la carretera A-337, sendero de las cumbres. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18076','mirador','Mirador de la Estación Paleontológica Valle del Fardes','8.6/10 Paisaje árido arcilloso del Geoparque con un inmenso yacimiento de fósiles de grandes mamíferos del Pleistoceno. Cómo llegar: Pasarela sobreelevada de observación del centro de interpretación paleontológico. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18079','mirador','Mirador del río Genil (Paseo Lorquiano)','7.5/10 Paisaje fluvial poético vinculado a la infancia de Federico García Lorca con densas choperas e hileras de cultivos. Cómo llegar: Sendero de la mota lateral del río junto al puente de acceso de la localidad. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18905','mirador','Mirador del Torreón de Gabia','7.6/10 Torreón defensivo nazarí del siglo XIV con vistas limpias de la Vega granadina y la cara norte de Sierra Nevada. Cómo llegar: Terraza superior accesible de la fortificación medieval de la plaza mayor. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18082','mirador','Mirador de la de la de de la del del Cerro del Real (Castellón Alto)','9.0/10 Impresionante valor histórico sobre un poblado argárico de la Edad del Bronce dispuesto en terrazas sobre badlands áridos. Cómo llegar: Pasarelas del parque arqueológico en el espolón fluvial del río Orce. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18083','mirador','Mirador del Cerrillo de la Horca','7.3/10 Paisaje ondulado tradicional de olivares y cultivos cerealistas rotulado sobre laderas margosas suaves dels Montes. Cómo llegar: Pista agrícola de tierra compactada en las inmediaciones de los depósitos reguladores. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18084','mirador','Mirador de la Collación de Gójar','7.6/10 Vista de la campiña residencial y los huertos frutales del piedemonte serrano que miran a la capital. Cómo llegar: Calle del mirador, barandilla protectora urbana en el límite del escarpe del municipio. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18085','mirador','Mirador del Embalse de Francisco Abellán (Peñas de los Gitanos)','8.8/10 Espectacular relieve calizo con dólmenes prehistóricos que domina la presa y los frondosos encinares del río Gor. Cómo llegar: Parque arqueológico de las Peñas de los Gitanos, sendero forestal señalizado desde el pueblo. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18086','mirador','Mirador del Desierto de Gorafe (Los Coloraos)','9.7/10 Incomparable y abrumador desierto de cañones, fallas y chimeneas arcillosas rojas con más de 200 dólmenes prehistóricos. Cómo llegar: Pista de tierra del desierto de Gorafe, balcón natural vallado junto al centro de interpretación. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','mirador','Mirador de San Nicolás (Albaicín)','10.0/10 La panorámica más universal del mundo: la Alhambra y el Generalife con el imponente manto nevado de Sierra Nevada detrás. Cómo llegar: Plaza del mirador de San Nicolás en el corazón del barrio medieval mudéjar del Albaicín. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18088','mirador','Mirador del Puente de Lata de Guadahortuna','7.9/10 Monumental puente ferroviario de hierro del siglo XIX que destaca en mitad de los llanos cerealistas y olivares de Los Montes. Cómo llegar: Loma de tierra batida contigua a la antigua estación de tren abandonada. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18089','mirador','Mirador de la Magdalena (Barrio de las Cuevas)','9.6/10 Espectacular e icónica estampa de miles de chimeneas blancas brotando de cerros arcillosos con la catedral gótico-barroca al fondo. Cómo llegar: Cerro de la Magdalena, plataforma acondicionada con accesos peatonales desde la plaza de las ermitas. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18906','mirador','Mirador del Castillejo de Guájar Faragüit','8.6/10 Fortificación fortificada árabe colgada sobre un peñón rodeado por bancales de aguacates, cítricos y palmeras tropicales. Cómo llegar: Sendero medieval empedrado que parte del río de los Guájares hacia las ruinas. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90038','mirador','Mirador del Faro de Castell de Ferro','8.9/10 Impresionante acantilado calizo marino presidido por la torre almenara islámica y el faro sobre la Costa Tropical. Cómo llegar: Paseo de los acantilados de la torre de la Estancia, acceso directo desde la playa. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18094','mirador','Mirador del Tranvía de la Sierra (Canales)','9.6/10 Vista aérea del embalse de Canales encajonado en el desfiladero con las altas cumbres alpinas y castañares del Genil. Cómo llegar: Trazado recuperado de la antigua vía del tren de montaña, senderos peatonales con túneles de roca. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18095','mirador','Mirador de las Canteras de Güevéjar','7.4/10 Vista de las lomas calcáreas que miran a la Vega baja y los restos históricos del terremoto de 1884. Cómo llegar: Zona ajardinada alta cercana a los depósitos de agua municipales de la localidad. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18096','mirador','Mirador del llano estepario de Huélago','7.6/10 Paisaje árido y liso del norte provincial roto únicamente por pequeñas balsas de agua ganaderas y olivares jóvenes. Cómo llegar: Vértice geodésico sobre la muela margosa que se eleva al este del término. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18097','mirador','Mirador de los Molinos de Agua','8.4/10 Vista del barranco de la cuenca del Marquesado con los ingenios hidráulicos tradicionales de herencia morisca. Cómo llegar: Senda botánica de los molinos de agua, acceso desde el parque fluvial del municipio. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18098','mirador','Mirador de las Secuoyas de la Losa (La Losa)','9.2/10 Monumental e insólito bosque de secuoyas gigantes centenarias plantadas en el siglo XIX a las faldas de la Sierra de la Sagra. Cómo llegar: Finca señorial de La Losa, senderos peatonales habilitados bajo los colosales árboles. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18099','mirador','Mirador de la Cueva del Gato (Sierra de Arana)','8.9/10 Inmenso pinar y encinar alpino del Parque Natural protegiendo el nacimiento del río Darro bajo riscos calizos grises. Cómo llegar: Centro de visitantes de Puerto Lobo, sendero forestal señalizado hacia los búnkeres de la Guerra Civil. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18100','mirador','Mirador de la Vega del Espárrago','7.8/10 Amplio llano visual de la rica vega baja del Genil dedicada al cultivo tradicional del espárrago triguero D.O.P. Cómo llegar: Paseo fluvial elevado sobre la defensa del río, accesible desde el casco urbano. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18101','mirador','Mirador del Carmen','7.5/10 Vista metropolitana de la capital y la Vega con los olivares residenciales del cinturón sur. Cómo llegar: Calle del Carmen, balcón urbano acondicionado con valla metálica. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18102','mirador','Mirador del Castillo de Íllora (Ojo de la Vega)','90/10 Impresionante peñón coronado por la fortaleza nazarí que domina toda la Vega occidental cantada por Washington Irving. Cómo llegar: Paseo de ronda fortificado de la Alcazaba medieval, acceso empedrado desde la iglesia góticorenacentista. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18103','mirador','Mirador de la Leonera','8.2/10 Vista del valle de frutales tropicales de la Costa Tropical abrigado por los escarpados linderos de Sierra Almijara. Cómo llegar: Pista agrícola forestal consolidada que sube hacia los depósitos de riego altos. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18105','mirador','Mirador de la Cueva del Agua','8.8/10 Vista de los imponentes paredones calizos del norte provincial que albergan el gran complejo kárstico subterráneo local. Cómo llegar: Paraje natural de la Sierra de Arana, entorno inmediato al portalón de la cavidad. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18106','mirador','Mirador del Nacimiento del río Játar','8.4/10 Paisaje montañoso con un espectacular brote de agua rodeado de pinares piñoneros y chopos bajo Sierra Almijara. Cómo llegar: Senda del Nacimiento, área recreativa acondicionada al sur del núcleo urbano. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18107','mirador','Mirador del río Grande','8.3/10 Vista del encajonamiento fluvial del río Grande, los puentes de piedra rústicos y los pinares del parque natural. Cómo llegar: Pista forestal transitable que comunica el pueblo con el paraje del Vacarí. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18108','mirador','Mirador de las Minas de Santa Constanza','9.1/10 Paisaje minero histórico de cobre con laderas cubiertas de encinas bajo las cimas del Mulhacén septentrional. Cómo llegar: Sendero local balizado de la ruta minera que parte de las afueras residenciales. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18109','mirador','Mirador del Valle de la Bodega','8.1/10 Vista abancalada tradicional de chirimoyos y aguacates esculpida sobre laderas calizas de la Costa Tropical interior. Cómo llegar: Camino agrícola de tierra compactada en el sector alto de la cuenca fluvial. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18111','mirador','Mirador de la loma de Jun','7.2/10 Vista de los llanos del norte del área metropolitana y las canteras tradicionales de arcilla de alfarería local. Cómo llegar: Calle de la Ermita, extremo urbano con barandilla protectora sobre el desnivel. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18112','mirador','Mirador del Fuerte de Juviles','8.9/10 Inmensa fortaleza califal medieval que domina de forma absoluta los campos de almendros y castaños de la Alpujarra alta. Cómo llegar: Cima del cerro fortificado del Fuerte, sendero medieval desde las eras del pueblo. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18115','mirador','Mirador del Castillo de Láchar','7.4/10 Vista del palacio neomudéjar señorial del siglo XIX integrado perfectamente en las choperas de la Vega baja. Cómo llegar: Plaza mayor del pueblo frente a la fachada fortificada del monumento visitable. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18116','mirador','Mirador de la Cañada de los de los de la del Castillo','9.3/10 Espectacular e histórica ruina medieval colgada sobre un acantilado que custodia la puerta de entrada a la Alpujarra. Cómo llegar: Sendero peatonal adaptado con pasarelas desde el parque del Salado hacia el peñón fortificado. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18117','mirador','Mirador del Barranco del Barrio','8.6/10 Vista del curso fluvial alto del Marquesado con castañares centenarios bajo las laderas calcinadas de Sierra Nevada. Cómo llegar: Camino rural de montaña elevado que comunica la población con las antiguas minas locales. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18119','mirador','Mirador del Castillo de Lojuela (Murchas)','8.8/10 Vista del Valle de Lecrín con plantaciones de cítricos, olivares tradicionales y el embalse de Béznar de fondo. Cómo llegar: Risco de la fortaleza nazarí de Lojuela, accesible por sendero desde el núcleo de Murchas. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18120','mirador','Mirador del Guardajamas','8.5/10 Espectacular relieve de calizas grises y pinares con vistas limpias de los profundos barrancos del río Verde bajo. Cómo llegar: Senda de montaña balizada que sube desde el casco urbano hacia las crestas occidentales. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18121','mirador','Mirador de Tímar','8.4/10 Pintoresco rincón alpujarreño con minas históricas de mercurio arropadas por olivares tradicionales y chumberas de ladera. Cómo llegar: Entrada de la pedanía de Tímar, balcón natural junto a las eras de piedra tradicionales. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18122','mirador','Mirador de los Infiernos de Loja','9.4/10 Espectacular monumento natural donde el río Genil se encaja formando saltos gigantes y cascadas bajo las calizas de la Alcazaba. Cómo llegar: Paseo de los Infiernos, pasarelas de madera en la base del cañón fluvial urbano. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18123','mirador','Mirador del Dehesa del Camarate (Bosque Encantado)','92/10 Espectacular e incomparable bosque mixto de árboles caducifolios (arces, robles, cerezos) con colores otoñales mágicos bajo las cumbres. Cómo llegar: Pista forestal regulada de la Dehesa del Camarate, sendero señalizado del Parque Nacional. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18124','mirador','Mirador de la Sierra de Lújar','8.7/10 Vista combinada de un alcornocal centenario recuperado y el mar Mediterráneo abierto desde las alturas mineras locales. Cómo llegar: Cima de la sierra accesible por pista de mantenimiento de los repetidores de telecomunicaciones. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18126','mirador','Mirador de las Salinas de la Malahá','7.4/10 Vista de las históricas eras de evaporación de sal de origen romano integradas en los llanos áridos del Temple. Cómo llegar: Loma contigua al complejo termal de las piscinas salinas de la localidad. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18127','mirador','Mirador del Camino de Albolote','7.0/10 Vista urbana y llana del cinturón norte industrial de la capital con el relieve de Sierra Elvira de fondo. Cómo llegar: Paseo peatonal perimetral junto a las vías del tranvía metropolitano de la población. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18128','mirador','Mirador de las Cárcavas del Marchal','8.9/10 Espectacular monumento natural de formaciones arcillosas de aspecto fantástico acunando las viviendas tradicionales de cueva. Cómo llegar: Plataforma con paneles interpretativos junto a la Ermita de la Virgen de la Cabeza. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18132','mirador','Mirador del Castillo de Moclín','9.2/10 Impresionante bastión fronterizo nazarí con vistas que dominan los tajos del río Velillos, Sierra Nevada y los olivares jiennenses. Cómo llegar: Torre del homenaje del recinto fortificado, en la cota más alta de la peña medieval. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18133','mirador','Mirador del Alto de Minatoya','8.4/10 Estampa costera y de montaña donde los viñedos tradicionales de solana se funden con los invernaderos de la Costa Tropical. Cómo llegar: Apartadero acondicionado de la carretera local que asciende hacia la Sierra de Los Guájares. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18134','mirador','Mirador de los Cahorros / Mirador del Veleta','9.8/10 Vertiginosa visual del cañón calcáreo calizo de los Cahorros, sus puentes colgantes, y acceso alpino a la Estación de Esquí de Sierra Nevada. Cómo llegar: Carretera de subida al Veleta TF-354 o sendero superior de los desfiladeros de los Cahorros. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18135','mirador','Mirador de National Geographic','9.7/10 Una de las postales artísticas e históricas más famosas del mundo, con la iglesia del castillo sobre la peña y la villa circular. Cómo llegar: Carretera de Tocón, explanada empedrada y acondicionada con un marco monumental fotográfico. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18136','mirador','Mirador del Castillo de Montejícar','7.8/10 Atalaya defensiva que corona el cerro del castillo, divisando el mar de olivos que conecta Granada con Jaén. Cómo llegar: Explanada de tierra apisonada en la cumbre del cerro donde se asientan las ruinas árabes. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18137','mirador','Mirador de la Ermita del Rosario','7.5/10 Paisaje ondulado de olivar jalonado por campos de cereal de secano y lomas que marcan el confín norte provincial. Cómo llegar: Pequeña colina adaptada con murete de piedra caliza junto a la ermita periférica. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18138','mirador','Mirador de los Badlands del Genil','7.7/10 Impresionante relieve erosivo de cárcavas arcillosas grises a orillas del Genil, salpicado de olivares y cultivos llanos. Cómo llegar: Camino rural consolidado que asciende hacia el hito geodésico del cerro de la Cruz. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18909','mirador','Mirador del Cerro de los Moros (Moreda)','7.6/10 Perspectiva del nudo ferroviario histórico, las lomas de cultivo tradicionales y las siluetas lejanas del Parque de Huétor. Cómo llegar: Cresta del montículo de margas que domina la estación de tren de Moreda. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18140','mirador','Mirador del Santuario de la Virgen de la Cabeza','9.2/10 Soberbia postal marítima y urbana de la capital de la Costa Tropical, las vegas de caña de azúcar viejas y el puerto. Cómo llegar: Explanada de piedra del santuario barroco edificado sobre el cerro del antiguo alcázar nazarí. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18141','mirador','Mirador del Cerrajón de Murtas','8.8/10 Techo de la Alpujarra baja a 1.507 metros, con vistas de infarto de la costa mediterránea, la Contraviesa y Sierra Nevada. Cómo llegar: Pista forestal transitable que corona el hito geodésico del Cerrajón, panel astronómico Starlight. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18143','mirador','Mirador de la Falla de Nigüelas','91/10 Monumento natural de incalculable valor geográfico, con la imponente rampa de fricción tectónica de piedra caliza dominando el Valle de Lecrín. Cómo llegar: Plataforma metálica con barandillas al inicio de la pista forestal que sube a Sierra Nevada. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18144','mirador','Mirador de la Peña de la Cruz','8.4/10 Espectacular y elevada visual de la Vega de Granada y la Sierra de Huétor desde un promontorio kárstico rocoso. Cómo llegar: Senda de montaña señalizada desde el área recreativa de Fuente de la Higuera. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18145','mirador','Mirador del Lomo de San Antón','7.1/10 Vista llana suburbana de los cultivos hortícolas de la Vega alta arropados por el perfil montañoso de Sierra Nevada. Cómo llegar: Calle del mirador, barandilla de hierro urbana sobre el talud natural del municipio. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18147','mirador','Mirador del valle del Guadalfeo','9.0/10 Majestuoso cruce de caminos alpujarreño con un inmenso mar de olivos, palmeras y el río Guadalfeo abriéndose paso. Cómo llegar: Carretera A-348 dirección Lanjarón, apartadero acondicionado con murete de piedra rústica. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18148','mirador','Mirador de la Carretera de la Cabra','9.3/10 Salvaje e imponente perspectiva del Parque Natural de las Sierras de Tejeda, Almijara y Alhama y el cañón del río Verde. Cómo llegar: Kilómetro 35 de la carretera paisajística A-4050, balcón natural colgado sobre el abismo. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18150','mirador','Mirador del Humedal del Padul','8.7/10 Observatorio de la mayor turbera de Andalucía con lagunas someras, densos carrizales y avifauna migratoria bajo el gélido Almijara. Cómo llegar: Estructura de madera de la Ruta del Mamut, mirador ornitológico elevado sobre pilotes. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18151','mirador','Mirador del Paseo de García Lorca','9.6/10 Postal idílica de la arquitectura terrazo alpujarreña de chimeneas con sombrero y terraos colgados en el Poqueira salvaje. Cómo llegar: Entrada norte del pueblo, pasarela de piedra integrada en el entramado urbano empedrado. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18152','mirador','Mirador del Cerro de Mencal','7.8/10 Vista del altiplano del norte provincial con el imponente cerro testigo calizo emergiendo solitario entre llanuras de trigo. Cómo llegar: Pista agrícola transitable que bordea la base norte de la montaña del Mencal. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18153','mirador','Mirador de las Tres Cruces','7.0/10 Panorámica urbana y periurbe de la zona norte metropolitana con la red de autovías integrada en el secano. Cómo llegar: Parque de las Tres Cruces, zona ajardinada alta con barandilla protectora. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18167','mirador','Mirador de las Cuevas de Purullena','8.7/10 Espectacular e impactante laberinto de chimeneas blancas brotando de arcillas rojas erosionadas en la Hoya de Guadix. Cómo llegar: Cerro de la iglesia vieja, acceso acondicionado por rampas peatonales desde el museo troglodita. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18168','mirador','Mirador del Embalse de Quéntar','8.6/10 Vista directa de la imponente pared de la presa encajada entre los desfiladeros calizos del río Aguas Blancas y pinos. Cómo llegar: Corona de la presa y miradores superiores de la carretera de montaña GR-3201. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18170','mirador','Mirador de la Loma del Aljibe','8.5/10 Vista de las laderas de almendros y viñedos altos de la Contraviesa que descienden en tobogán hacia el mar de Castell de Ferro. Cómo llegar: Pista forestal batida transitable cercana a las antiguas eras comunales. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18171','mirador','Mirador de la Villa Romana de Salar','8.1/10 Vista histórica y rural de la vega olivarera del río Salar, vinculada al importante centro de interpretación de mosaicos. Cómo llegar: Pasarela sobreelevada del complejo arqueológico protegido de la localidad. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18173','mirador','Mirador del Paseo de las Flores (Castillo)','9.6/10 Insuperable, mística y bella postal de la fortaleza nazarí sobre el peñón, el pueblo blanco, las plataneras y el mar. Cómo llegar: Paseo perimetral del castillo medieval, balconada colgada sobre el acantilado urbano histórico. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18174','mirador','Mirador del río Alhama','7.4/10 Perspectiva de la vega fluvial baja con plantaciones hortícolas tradicionales bajo las lomas olivareras del poniente. Cómo llegar: Camino rural sobreelevado que comunica el pueblo con la pedanía de Valenzuela. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18175','mirador','Mirador de las Cuatro Puertas (Campamento Real)','8.3/10 Valor histórico único sobre el entramado rectangular de la ciudad campamento de los Reyes Católicos y la rica Vega. Cómo llegar: Azotea transitable de la iglesia de la Encarnación o paseos junto a las históricas puertas-capilla urbanas. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18176','mirador','Mirador del Embrujo / Ojo de la Bruja','9.3/10 Divertido y fotogénico paisaje alpujarreño tematizado de brujería, con vistas espectaculares de la solana y el mar de fondo. Cómo llegar: Plaza de abastos y mirador de la cueva del Ojo de la Bruja, acceso urbano señalizado. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18177','mirador','Mirador de Melicena','8.4/10 Acantilado litoral de pizarras con una antigua torre de vigía nazarí dominando las playas vírgenes de la costa este. Cómo llegar: Torre de Melicena, sendero costero peatonal desde el paseo marítimo de la pedanía. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18178','mirador','Mirador del Vergé de Cardela','7.6/10 Vistas del altiplano cerealista del norte roto únicamente por encinares dispersos y la silueta de los parques eólicos. Cómo llegar: Hito de la antigua torre de guaita que da nombre al municipio, camino agrícola. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18179','mirador','Mirador de la Ermita de la Salud','8.5/10 Vista del encajonamiento fluvial del río Guadalfeo rodeado de almendros centenarios tradicionales e higueras rústicas alpujarreñas. Cómo llegar: Explanada de la ermita, accesible por pista de tierra compactada al norte del casco urbano. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18180','mirador','Mirador del Barrio Alto','9.6/10 Espectacular e idílica estampa alpina del municipio más alto de la península, secaderos de jamón y el río Mulhacén salvaje. Cómo llegar: Plaza alta del Barrio Alto, inicio de los senderos que ascienden hacia las Siete Lagunas. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18181','mirador','Mirador de la Sierra de la Contraviesa','8.2/10 Árido y descarnado paisaje de la Alpujarra profunda oriental que mira hacia las muelas calcáreas áridas de Almería. Cómo llegar: Carretera de montaña local, apartadero con paneles informativos ganaderos. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18182','mirador','Mirador del Santuario de la Virgen del Martirio','8.6/10 Amplia visual del llano intermontano alpujarreño con huertas de frutales y la silueta de la colegiata mudéjar local. Cómo llegar: Explanada arbolada de la ermita de la Virgen, accesible por paseo pavimentado urbano. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18914','mirador','Mirador de la Casa de Bernarda Alba','7.6/10 Valor literario y geográfico sobre los campos de tabaco tradicionales y choperas cantados por Federico García Lorca. Cómo llegar: Ventanales e hito exterior de la casa museo de Frasquita Alba en el casco viejo. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18907','mirador','Mirador de Charches','8.6/10 Excepcional altitud sobre el Marquesado, prados altos agrícolas tradicionales y transición directa hacia los pinos de la Sierra de Baza. Cómo llegar: Entorno de las eras de piedra de la pedanía de Charches, cota de montaña. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18183','mirador','Mirador de Aben Humeya','9.1/10 Paisaje alpujarreño histórico vinculado a la rebelión de los moriscos, con barrancos verdes de castaños y casas de pizarra. Cómo llegar: Puente de la Tableta, sendero local balizado que circunvala la villa de Válor. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18911','mirador','Mirador de los Secaderos de Tabaco (Purchil)','7.1/10 Paisaje plano puramente agrícola de la Vega con las monumentales naves de ladrillo visto de los secaderos de tabaco tradicionales. Cómo llegar: Margen de la acequia de Purchil, sendero peatonal cicloturístico de la vega baja. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18184','mirador','Mirador del Torreón de Vélez','8.8/10 Vista aérea del azud del río Guadalfeo, el Jardín Nazarí histórico y el desfiladero que conduce a la costa mediterránea. Cómo llegar: Almenas superiores del torreón militar islámico restaurado que domina el núcleo urbano de piedra. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18185','mirador','Mirador de la Dehesa de Huelma','7.3/10 Horizonte de encinares dispersos y olivares de secano característicos del Temple bajo, con valles arcillosos suaves. Cómo llegar: Pista de servicio agraria junto a las balsas de almacenamiento de agua locales. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18149','mirador','Mirador del Suspiro del Moro','8.4/10 Histórica y legendaria atalaya donde Boabdil lloró al despedirse de Granada, con amplias vistas de la vega y la capital. Cómo llegar: Puerto del Suspiro del Moro, autovía A-44, zona de servicio y monumento interpretativo. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18187','mirador','Mirador de los Coloraos (Baños de Alicún)','8.9/10 Impresionante e inhóspito cañón desértico de arcillas de color rojo intenso que compite visualmente con el Gran Cañón del Colorado. Cómo llegar: Complejo termal de Alicún de las Torres, sendero geológico balizado hacia los riscos superiores. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18189','mirador','Mirador del Barranco de Víznar (Alfacar)','8.6/10 Enorme valor emocional e histórico vinculado a la memoria de García Lorca en un entorno de pinos de la Sierra de Alfaguara. Cómo llegar: Parque de la Memoria de Víznar, senderos peatonales sombreados e hitos monumentales. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18192','mirador','Mirador del Polje de Zafarraya (El Ventorrillo)','8.8/10 Espectacular y plano llano kárstico cerrado (el poljé más grande de España) rodeado por imponentes murallas calizas verticales. Cómo llegar: Puerto de los Alazores, carretera autonómica A-402, balcón vallado sobre el mar de hortalizas. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18913','mirador','Mirador del Castillo de Zagra','8.3/10 Atalaya sobre el río Pesquera y el embalse de Iznájar con lomas infinitas de olivos del Poniente granadino. Cómo llegar: Recinto amurallado de la antigua fortaleza andalusí que corona el promontorio de la villa. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18193','mirador','Mirador de Cumbres Verdes','8.7/10 Puerta natural de entrada de alta montaña al Parque Nacional de Sierra Nevada, con vistas completas de la capital granadina. Cómo llegar: Pista forestal asfaltada que sube hacia la fuente del Hervidero, aparcamientos forestales. 📍 Provincia: Granada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18194','mirador','Mirador del Cerro Jabalcón','91/10 Inmensa e insuperable atalaya caliza exenta a 1.492 metros sobre el embalse del Negratín, los badlands del norte y la Hoya de Baza. Cómo llegar: Ermita de la Virgen de la Cabeza, cima del cerro Jabalcón accesible por pista pavimentada helicoidal. ¡Hito épico completado! Con el municipio de Zújar registrado y cerrado de forma rigurosa, la provincia de Granada queda finalizada al 100%. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24001','mirador','Mirador del Castillo de Albanchez','8.9/10 Espectacular e imponente visual del pico Mágina y los mares de olivos encajados entre colosales farallones calizos de montaña. Cómo llegar: Base de la torre del homenaje, encaramada de forma inverosímil sobre una aguja rocosa. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24002','mirador','Mirador de la Fortaleza de la Mota','9.6/10 Majestuosa e histórica panorámica de la ciudad medieval amurallada, su alcázar nazarí y las lomas olivareras de la frontera granadina. Cómo llegar: Almenas superiores de la Torre del Homenaje del recinto monumental. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24003','mirador','Mirador del Castillo Calatravo','9.1/10 Dominio absoluto sobre el valle del río Víboras, las sierras Subbéticas y un tapiz infinito de olivar tradicional jiennense. Cómo llegar: Paseo de ronda fortificado de la orden militar, accesible por rampa empedrada urbana. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24004','mirador','Mirador de la Cimbarra','9.4/10 Espectacular y vertical desfiladero de cuarcita por el que se desploma una colosal cascada de agua limpia de 40 metros. Cómo llegar: Pista de acceso desde el pueblo, pasarela de madera con barandilla volada frente al salto. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','mirador','Mirador del Santuario de la Virgen de la Cabeza','9.2/10 Mística e inmensa perspectiva de Sierra Morena, cerros de encinar denso y hábitat protegido del lince ibérico. Cómo llegar: Explanada exterior del templo en el cerro del Cabezo, carretera paisajística A-6177. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24006','mirador','Mirador del Aljibe almohade','8.2/10 Atalaya sobre la campiña del Guadalquivir, cuna del rey Muhammad I de Granada, rodeada de fértiles tierras de cultivo. Cómo llegar: Cima del cerro del Alcázar, junto a la cripta del templo de Santa María. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24007','mirador','Mirador del Castillo de Macías el Enamorado','7.2/10 Visual llana de la campiña olivarera central baja enlazada con la leyenda trovadoresca medieval de la fortificación. Cómo llegar: Torreón circular consolidado dentro del pequeño casco urbano del municipio. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24008','mirador','Mirador del Olivar del Condado','7.5/10 Suave oleaje de olivos ordenados geométricamente que se estiran hacia las aguas lejanas del embalse de Guadalén. Cómo llegar: Camino rural elevado cercano al cementerio de la pedanía de El Porrosillo. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','mirador','Mirador del Paseo de las Murallas','9.5/10 Legendaria postal cantada por Antonio Machado, contemplando el valle del Guadalquivir y los cerros de Úbeda de forma limpia. Cómo llegar: Paseo de Antonio Machado, balaustrada urbana de piedra sobre el gran mar de olivos meridional. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24011','mirador','Mirador de la Batalla de Bailén','7.8/10 Enorme valor histórico sobre el escenario estratégico de 1808, dominando el llano de arcillas y olivos. Cómo llegar: Parque de la Juventud, monumento conmemorativo e hitos informativos tácticos. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24012','mirador','Mirador del Castillo de Burgalimar','9.6/10 Impresionante e intacta fortaleza califal de catorce torreones que domina las aguas azules del embalse del Rumblar. Cómo llegar: Muralla exterior del castillo omeya, accesible por callejuelas empedradas del casco histórico. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24013','mirador','Mirador del Puerto de la Cumbre','8.7/10 Transición perfecta entre las huertas tradicionales de ribera del río Beas y los pinares de la Sierra de Segura. Cómo llegar: Kilómetro 15 de la carretera escénica de montaña A-6301, apartadero habilitado. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24015','mirador','Mirador de la Torre del Palacio Episcopal','7.3/10 Vista baja de la vega del Guadalquivir, haciendas olivareras tradicionales y vías de comunicación de La Loma. Cómo llegar: Entorno público de la plaza de la Constitución frente a la torre gótica restaurada. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24018','mirador','Mirador del Castillo de Bélmez','8.4/10 Vista escarpada de los nacimientos de agua del río de la tarde y crestas calizas de Mágina meridional. Cómo llegar: Cerro del Castillo, sendero local empinado que sale de las inmediaciones de las caras de Bélmez. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24016','mirador','Mirador de la Peña de Peñolite','8.9/10 Formación geológica caliza vertical con vistas aéreas de los profundos barrancos forestales de la Sierra de Cazorla alta. Cómo llegar: Senda forestal que asciende hacia los antiguos restos arqueológicos de la atalaya islámica. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23017','mirador','Mirador del Cerro de San Juan','8.4/10 Espectacular vista del desierto del Guadiana Menor, el viaducto ferroviario de Larva y las cumbres de Sierra Mágina. Cómo llegar: Cerro de San Juan, accesible por pista de tierra batida acondicionada al norte del casco urbano. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23018','mirador','Mirador del Castillo de Alhabar','8.8/10 Espectacular peñón calizo coronado por restos medievales, encajonando el pueblo entre olivares y los picos de Mágina. Cómo llegar: Escalinata de piedra integrada en la roca caliza desde la plaza del ayuntamiento. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23019','mirador','Mirador del Desfiladero de Puerta de Arenas','83/10 Impresionante tajo calizo que sirve de puerta natural de entrada a Jaén, con vegetación de ribera y túneles históricos. Cómo llegar: Área recreativa de Puerta de Arenas, junto al antiguo trazado de la carretera nacional N-323. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23020','mirador','Mirador del Castillo de Canena','8.0/10 Hermosa vista de la fortaleza renacentista de Francisco de los Cobos dominando el mar de olivos de la comarca de La Loma. Cómo llegar: Entorno ajardinado perimetral del castillo, en la zona más elevada de la población. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23901','mirador','Mirador de Carchelejo (Barranco de la Cueva)','7.9/10 Perspectiva de las lomas olivareras de Sierra Mágina occidental rotas por pequeños barrancos y encinares degradados. Cómo llegar: Senda peatonal rústica que parte del barrio alto de Carchelejo hacia los riscos. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23024','mirador','Mirador de las Nuevas Poblaciones','8.6/10 Vista del trazado ortogonal ilustrado de la capital de Carlos III, lindando con las estribaciones de Sierra Morena. Cómo llegar: Torre de la antigua iglesia de la Inmaculada Concepción o paseo elevado de las Torres. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23025','mirador','Mirador de la Cueva de la Lobera','8.1/10 Santuario ibérico prehistórico colgado de un farallón rocoso con vistas panorámicas de la comarca de El Condado. Cómo llegar: Pasarelas del complejo arqueológico e interpretativo de la Lobera, acceso señalizado. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23026','mirador','Mirador del Nacimiento del Río San Juan','8.5/10 Idílico paisaje de pozas de agua turquesa cristalina rodeadas de frondosas alamedas, huertas de cerezos y montañas calizas. Cómo llegar: Sendero recreativo del Nacimiento, pasarelas de madera integradas en el entorno fluvial. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','mirador','Mirador de la Virgen de la Cabeza','9.8/10 Abrumadora y vertical postal del Castillo de la Yedra, la iglesia de Santa María y los paredones de la sierra. Cómo llegar: Carretera de montaña JF-7092 que asciende hacia la ermita de la Virgen de la Cabeza. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23029','mirador','Mirador del Paseo de la Roca','9.1/10 Impresionante e histórica atalaya construida sobre un peñón de arenisca roja con vistas kilométricas de los ríos Guadalimar y Guadalmena. Cómo llegar: Paseo fortificado que circunvala el borde exterior del pueblo colgado. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23030','mirador','Mirador de las Villas (Almendrares)','8.2/10 Vista de transición entre las ricas huertas de regadío del río Vega y los densos olivares de montaña de Cazorla. Cómo llegar: Camino rural elevado de la Dehesa de Almendrares, sector este del término. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23031','mirador','Mirador de las Eras del Secano','7.0/10 Visual llana de la campiña baja jiennense dedicada íntegramente al monocultivo geométrico del olivar tradicional. Cómo llegar: Pista agrícola de tierra compactada perimetral al este de las naves agrarias locales. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24035','mirador','Mirador del Castillo de Espelúy','7.4/10 Vista baja del curso del río Guadalquivir y su soto de ribera desde los restos de la fortaleza defensiva medieval. Cómo llegar: Corona de la colina caliza donde se yergue la torre del homenaje consolidada. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23033','mirador','Mirador de la Tiendilla / Puente Colgante','8.6/10 Espectacular paisaje de montaña caliza que alberga el puente colgante urbano y la tirolina más larga de la provincia. Cómo llegar: Complejo de turismo activo de la Tiendilla, pasarelas ancladas a las rocas sobre el barranco. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23034','mirador','Mirador de la Desembocadura del río Vadillo','8.2/10 Paisaje escarpado de olivos de ladera de la comarca de Martos bajo la silueta caliza de la Peña de la Virgen. Cómo llegar: Camino forestal del calvario alto, accesible a pie desde la fuente de la Negra. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23035','mirador','Mirador del llano de Fuerte del Rey','6.9/10 Horizonte plano amurallado por hileras infinitas de olivos de campiña rotos por pequeñas edificaciones de cortijos rústicos. Cómo llegar: Pequeño talud de tierra junto al depósito de agua municipal, al oeste del casco urbano. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23037','mirador','Mirador de las Torres de Guaita (La Laguna)','8.5/10 Vista forestal de la Sierra de Segura septentrional con olivares ecológicos protegidos e hitos defensivos medievales de frontera. Cómo llegar: Pista rural batida que conduce a los restos fortificados de la torre de la Laguna. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23038','mirador','Mirador del Castillo de La Guardia','8.9/10 Impresionante e histórica panorámica del valle del río Guadalbullón, el cerro de San Cristóbal y el acceso sur a Jaén. Cómo llegar: Balcón exterior de la alcazaba islámica y castillo calatravo restaurado en el cerro alto. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23041','mirador','Mirador del Tossal de Calatrava','7.1/10 Perspectiva de las suaves ondulaciones cerealistas y olivareras que marcan la frontera administrativa con la campiña cordobesa. Cómo llegar: Camino de servicio agrario junto al antiguo silo de almacenamiento de grano local. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23042','mirador','Mirador del Valle del Turrilla','8.4/10 Contraste absoluto entre el cauce verde del río Turrilla y los escarpados badlands arcillosos del extremo sur provincial. Cómo llegar: Carretera local JA-8201, apartadero rústico con barandilla de madera sobre el barranco. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23043','mirador','Mirador del Castillo de Hornos / El Aguilón','9.5/10 Espectacular e inmensa panorámica aérea del embalse del Tranco de Beas encajado entre los pinares alpinos de Segura. Cómo llegar: Cosmolarium y centro de interpretación astronómica del castillo medieval colgado de la villa. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23044','mirador','Mirador del Castillo de los Alburquerque','8.7/10 Vista del casco urbano señorial escalonado y los campos agrícolas del Marquesado bajo el imponente pico Mágina. Cómo llegar: Muralla exterior de la fortaleza del siglo XV, accesible por rampa empedrada desde la iglesia. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23045','mirador','Mirador del río Guadiana Menor','8.5/10 Impresionante paisaje de cárcavas desérticas y escarpes calizos que guían las aguas del río hacia el Negratín. Cómo llegar: Pista agrícola transitable de la pedanía de Ceal, cota elevada del terreno. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23046','mirador','Mirador de la Muralla Ciclópea','7.3/10 Vista histórica urbana vinculada al monumental muro prehistórico de origen íbero construido con piedras gigantes sin argamasa. Cómo llegar: Plaza del monumento arqueológico protegido en pleno casco urbano central. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23048','mirador','Mirador del Paseo del rastro','9.3/10 Espectacular e idílica atalaya a 1.000 metros sobre la comarca de Las Villas, El Condado y el mar de olivos. Cómo llegar: Paseo exterior fortificado del casco medieval amurallado repleto de macetas y calles empedradas. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23049','mirador','Mirador del Valle del Guadalimar','7.6/10 Vista de las ricas terrazas aluviales citrícolas del río Guadalimar y las lomas bajas olivareras que anuncian Linares. Cómo llegar: Calle del mirador, extremo urbano fortificado con barandilla metálica de protección. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','mirador','Mirador de la Cruz del Castillo de Santa Catalina','9.6/10 Insuperable y majestuosa panorámica de la imponente catedral renacentista, el casco histórico colgado, el Guadalquivir y Mágina. Cómo llegar: Cruz monumental de hormigón en la cresta rocosa caliza exterior de la fortaleza, sendero adaptado. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23051','mirador','Mirador del Calvario de Jamilena','7.8/10 Vista de las plantaciones olivareras tradicionales y los campos de ajo bajo el abrigo de la Sierra de la Grana. Cómo llegar: Hito monumental del Calvario, accesible por sendero peatonal escalonado desde el norte. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23052','mirador','Mirador del Pinar de Cánava','8.5/10 Monumento natural compuesto por un denso pinar carrasco centenario relicto con fuentes de agua cristalina bajo Mágina. Cómo llegar: Senda botánica del entorno del Santuario de la Virgen de los Remedios de Cánava. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23053','mirador','Mirador del Castillo de Jódar','8.6/10 Fortaleza medieval que alberga el centro de interpretación del Parque de Mágina y domina los campos del río Jandulilla. Cómo llegar: Torre del homenaje restaurada del complejo fortificado que corona el cerro urbano. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23040','mirador','Mirador de la Torre del Reloj','7.1/10 Suave paisaje ondulado de campiña olivarera central con las antiguas naves agrícolas integradas en la llanura. Cómo llegar: Calle de la Torre, pequeña plaza pública junto a las estructuras defensivas de piedra sillar. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23054','mirador','Mirador de las Eras de Larva','7.7/10 Perspectiva desértica del piedemonte de la comarca que mira hacia las áridas cuencas arcillosas del Guadiana Menor. Cómo llegar: Conjunto etnográfico de antiguas eras de piedra situadas al norte del casco urbano de piedra. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23055','mirador','Mirador del Paisaje Minero de El Centenillo / Cástulo','8.8/10 Impresionante patrimonio arqueológico e industrial con las cabrías y naves mineras de ladrillo visto rompiendo el mar de olivos. Cómo llegar: Yacimiento arqueológico de la ciudad íbero-romana de Cástulo, pasarela superior de observación de los mosaicos. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23056','mirador','Mirador del Castillo de Lopera','8.1/10 Fortaleza de la orden de Calatrava de torres cilíndricas dominando los ricos viñedos tradicionales y olivares de la campiña. Cómo llegar: Adosado a la muralla exterior del palacio fortificado de la plaza de la Constitución. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23057','mirador','Mirador de la Torre de Lupión','7.3/10 Vista baja de la comarca olivarera de La Loma norteña vinculada a las ruinas del antiguo alcázar medieval. Cómo llegar: Pequeña plaza elevada junto al torreón cilíndrico consolidado del casco urbano. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23058','mirador','Mirador del Puerto de las Palomas (Mágina)','8.7/10 Impresionante e imponente zigzag de la carretera forestal que escala la sierra caliza entre densos olivares de montaña. Cómo llegar: Alto del puerto de la carretera escénica de montaña, plataforma con barandilla volada sobre el abismo. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23059','mirador','Mirador del Balneario de Marmolejo','8.2/10 Vista del frondoso parque forestal y los jardines del histórico complejo termal medicinal junto al cauce del Guadalquivir. Cómo llegar: Paseo peatonal de la Alameda alta, barandilla porticada sobre el complejo del agua. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','mirador','Mirador de la Peña de Martos','9.4/10 Colosal e imponente mole caliza calificada de monumento natural con vistas aéreas brutales de la mayor productora mundial de aceite. Cómo llegar: Castillo de la Peña, senderos escarpados y escaleras metálicas con cadenas para coronar el pico del cristo. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23061','mirador','Mirador de la Torre de Mengíbar','7.8/10 Atalaya del nudo fluvial e histórico de Iliturgi, dominando la confluencia del Guadalbullón y el gran Guadalquivir. Cómo llegar: Terraza superior accesible de la imponente torre del homenaje mudéjar de la plaza mayor. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23062','mirador','Mirador del Embalse de Dañador','7.9/10 Vista limpia de la lámina de agua artificial rodeada de dehesas de encinas y pinos piñoneros de Sierra Morena oriental. Cómo llegar: Corona de la presa y senderos del área recreativa forestal de la pedanía de Venta de los Santos. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23063','mirador','Mirador del Castillo de Santisteban','7.8/10 Perspectiva de las suaves lomas calizas erosionadas que jalonan los olivares rústicos tradicionales del Condado alto. Cómo llegar: Pista agrícola de tierra compactada contigua a los depósitos reguladores municipales. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23064','mirador','Mirador del Puerto de Carretero','8.4/10 Paso montañoso de la autovía a 1.000 metros de altitud, con amplias vistas de la llanura olivarera fronteriza con Granada. Cómo llegar: Puerto de montaña de la autovía A-44, zona de servicio y mirador acondicionado rústico. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23065','mirador','Mirador de Amurjo / Torres de Santa Catalina','9.2/10 Espectacular e idílica postal con la colosal piscina natural forestal de Amurjo y las tres torres defensivas islámicas. Cómo llegar: Entorno arqueológico de las torres de Santa Catalina, sendero balizado del Parque Natural de Segura. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23066','mirador','Mirador de las Tumbas Príncipes de Toya','8.5/10 Enorme valor geográfico e histórico sobre la colina caliza que acuna la cámara funeraria monumental ibérica del siglo IV a.C. Cómo llegar: Complejo arqueológico vallado de la pedanía de Toya, loma fluvial del río Guadalquivir. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23067','mirador','Mirador de la Charca de Pegalajar','8.9/10 Espectacular e histórica balsa de agua tradicional de origen islámico que preside la huerta de paratas protegida del municipio. Cómo llegar: Paseo de la Charca, barandilla de hierro urbana sobre el vergel agrícola andalusí. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23069','mirador','Mirador de la Torre de Boabdil','8.7/10 Impresionante torre medieval de sillería de la Orden de Calatrava con vistas completas de la rica campiña olivarera baja. Cómo llegar: Última planta accesible de la torre gótica fortificada, visitas programadas del casco histórico. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23070','mirador','Mirador del Barranco de la Bolera','9.3/10 Vertiginosa e imponente pasarela metálica colgada sobre el cañón del río Guadalentín y las aguas del embalse de la Bolera. Cómo llegar: Carretera A-326, sendero acondicionado del desfiladero con paneles interpretativos geológicos. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23071','mirador','Mirador del Puente Romano sobre el Guadalimar','8.0/10 Vista baja de la histórica calzada romana y el soto fluvial arbolado integrado en los campos olivareros tradicionales. Cómo llegar: Plataforma peatonal del puente de piedra, tramo de herradura del camino viejo de Segura. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23072','mirador','Mirador del Paseo del río Guadalimar','8.4/10 Vista de la entrada natural al parque natural con el dinámico curso del río cruzando los barrios de piedra tradicionales. Cómo llegar: Paseo de ronda fluvial alto del núcleo urbano, barandillas sobre el cauce. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23073','mirador','Mirador del Nacimiento del Río Guadalquivir','9.6/10 Místico e idílico rincón montañoso bajo densos pinares negros donde brota el río más importante del sur español. Cómo llegar: Paraje de la Cañada de las Fuentes, pista forestal de montaña de alta cota en el Parque Natural. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23074','mirador','Mirador del Oratorio Visigodo de Valdecanales','7.8/10 Fachada rupestre hipogea única tallada en roca caliza viva en mitad de un frondoso barranco olivarero mediterráneo. Cómo llegar: Complejo arqueológico monumental protegido, sendero rústico señalizado desde el norte. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23075','mirador','Mirador del Castillo de Sabiote','91/10 Majestuoso palacio fortificado renacentista diseñado por Vandelvira dominando los escarpes del valle del Guadalimar. Cómo llegar: Adosado al baluarte de las murallas medievales medievales de la villa plateresca. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23076','mirador','Mirador de Despeñaperros (Los Órganos)','9.5/10 Imponentes e icónicas formaciones geológicas de columnas de cuarcita verticales que cierran el mítico paso de Despeñaperros. Cómo llegar: Autovía A-4, apartadero escénico acondicionado con monumento e hitos interpretativos naturales. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23077','mirador','Mirador del Llano de Calatrava','7.1/10 Horizonte agrícola plano de olivar de campiña baja que limita con los campos cerealistas del sur cordobés. Cómo llegar: Calle del mirador, barandilla de hierro sobre el pequeño talud del depósito municipal. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23904','mirador','Mirador del Nacimiento del Río Segura','9.7/10 Impresionante e idílica poza kárstica profunda esculpida en la roca de la que brota un colosal caudal de agua cristalina pura. Cómo llegar: Pedanía de Fuente Segura, accesos peatonales de piedra y pasarelas del Parque Natural. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23079','mirador','Mirador del Monumento Natural Huellas de Dinosaurio','8.6/10 Excepcional yacimiento paleontológico de icnitas del Triásico integradas en dehesas de encinas de El Condado alto. Cómo llegar: Pasarela sobreelevada techada del complejo musealizado de las huellas prehistóricas. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23080','mirador','Mirador de la Torre de Santo Tomé','8.3/10 Vista baja de la vega agrícola del Guadalquivir, las islas de gravas y los linderos del Parque de Cazorla alto. Cómo llegar: Plaza elevada porticada de la iglesia que engloba la antigua torre del homenaje militar bajomedieval. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23081','mirador','Mirador del Castillo de Segura','9.7/10 Insuperable y abrumadora atalaya a 1.200 metros de altitud con vistas de 360 grados de todo el parque natural y los mares de olivos. Cómo llegar: Almenas superiores de la fortaleza medieval de la Orden de Santiago que corona el místico peñón alpino. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23082','mirador','Mirador de la Peña de Siles','9.2/10 Imponente mole rocosa caliza exenta que vigila el valle del río Tus, rodeada de densos pinares negrales subalpinos. Cómo llegar: Senda forestal que asciende de forma empinada hacia el hito geodésico y puesto de vigilancia de la peña. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23084','mirador','Mirador del río Guadalimar (La Alquería)','7.8/10 Panorámica rural de las terrazas fluviales y los huertos tradicionales rodeados por los olivares de Las Villas. Cómo llegar: Antigua pista de herradura elevada sobre la margen izquierda del cauce fluvial. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23085','mirador','Mirador del Guadalquivir (Campillo)','7.4/10 Paisaje llano de regadío y colonización agrícola con acequias e hileras de frutales e importantes olivares bajos. Cómo llegar: Zona elevada de los depósitos de riego situados al este del casco de la pedanía de Campillo del Río. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23086','mirador','Mirador del Cerro de San Miguel','8.3/10 Vista de las lomas olivareras tradicionales y los restos de fortificaciones medievales de la red defensiva jiennense. Cómo llegar: Ermita de San Miguel, claro acondicionado en lo alto de la colina que vigila la autovía A-316. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23087','mirador','Mirador del Castillo de Torredonjimeno','8.2/10 Fortaleza de la Orden de Calatrava vinculada al histórico tesoro visigodo local, con vistas de la campiña aceitera. Cómo llegar: Balcón exterior de la torre del homenaje restaurada, acceso por el patio de armas urbano. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23088','mirador','Mirador de las Torres Oscuras','7.9/10 Vista señorial del llano de la comarca de La Loma con pequeños torreones que jalonan los interminables olivares. Cómo llegar: Recinto fortificado del siglo XIII, espacio de memoria histórica acondicionado con paseos peatonales. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24086','mirador','Mirador de la Hondacabra (Mágina)','9.1/10 Espectacular e icónica imagen del valle alpino cubierto de olivares de solana y cerezos bajo el gélido pico Mágina. Cómo llegar: Pista de montaña asfaltada que sube hacia los prados de alta cota desde el norte del pueblo. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23091','mirador','Mirador del Castillo de la Yedra','8.5/10 Atalaya sobre el barranco forestal de la Sierra de Segura central con olivares tradicionales escalonados. Cómo llegar: Ruinas de la torre defensiva sobre el crestón calizo que domina el casco urbano. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','mirador','Mirador de San Lorenzo','9.6/10 Inmensa, lírica y fotogénica panorámica del valle del Guadalquivir, Sierra Mágina y el infinito mar de millones de olivos andaluces. Cómo llegar: Adosado a la muralla medieval junto a la rehabilitada Iglesia de San Lorenzo, en el casco histórico. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23093','mirador','Mirador de Las Chorreras','8.8/10 Espectacular paraje de agua limpia, cascadas y pozas esculpidas en la roca caliza entre frondosos chopos de la Sierra Sur. Cómo llegar: Sendero local señalizado que discurre en paralelo al curso del río Susana. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23094','mirador','Mirador del Cerro de la Virgen','8.6/10 Impresionante atalaya sobre los campos de La Loma que divisa de forma limpia los embalses de Giribaile, Guadalén y La Fernandina. Cómo llegar: Santuario de la Virgen del Castillo, en el punto más elevado del peñón urbano. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23095','mirador','Mirador de San Vicente','8.4/10 Vista elevada sobre las terrazas del río Guadalquivir y la densa alfombra verde de olivares de la comarca de Las Villas. Cómo llegar: Plataforma con balaustrada en la zona perimetral del casco urbano alto. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23096','mirador','Mirador de la Vega del Guadalquivir','7.5/10 Perspectiva baja de las huertas tradicionales y sotos de ribera asociados al gran eje fluvial andaluz. Cómo llegar: Paseo de la Ribera, sendero peatonal acondicionado junto al cauce del río. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23097','mirador','Mirador del Santuario de la Fuensanta','8.9/10 Entorno místico rodeado de pinos y olivares que domina la entrada natural al cañón alto del Guadalquivir. Cómo llegar: Explanada del santuario, accesible por la carretera escénica transversal de las sierras. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23098','mirador','Mirador del Castillo de Villardompardo','7.4/10 Suave oleaje de olivos ordenados geométricamente característicos de la campiña baja jiennense occidental. Cómo llegar: Torre del homenaje restaurada de la fortaleza del siglo XV, en el centro de la villa. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23099','mirador','Mirador del Puerto de la Hoya de Charilla','8.6/10 Impresionante paso de montaña a gran altitud con vistas limpias de la Sierra Sur, picos de caliza gris y encinares rústicos. Cómo llegar: Arcén habilitado en la carretera de montaña JA-3300 que conecta con Alcalá la Real. 📍 Provincia: Jaén.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23101','mirador','Mirador de la Torre de Guaita','8.2/10 Confín noreste provincial sobre los llanos agrícolas manchegos tradicionales y las primeras lomas que anuncian la Sierra de Alcaraz. Cómo llegar: Antigua torre de telegrafía y defensa medieval accesible por caminos agrícolas consolidados. ¡Logro cartográfico alcanzado! Con Villarrodrigo completado, la provincia de Jaén queda oficialmente cerrada al 100%. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90740','mirador','Mirador del Peñón del Águila','8.4/10 Extensa panorámica de las dehesas de Sierra Morena, monte bajo mediterráneo y olivares de montaña que mueren en el Guadalquivir. Cómo llegar: Pista forestal señalizada desde el sendero del agua, en el sector septentrional elevado. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17001','mirador','Mirador de la Laguna de Zóñar','8.8/10 Observatorio privilegiado de la mayor laguna de la campiña cordobesa, refugio de aves acuáticas, rodeada de suaves viñedos. Cómo llegar: Centro de Visitantes de la Laguna de Zóñar, sendero elevado adaptado con miradores de madera. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90741','mirador','Mirador del Salto del Caballo','8.6/10 Vista aérea del profundo cañón fluvial del río Caicena, huertas tradicionales dispuestas en terrazas y el yacimiento ibérico del cerro de la Cruz. Cómo llegar: Senda peatonal acondicionada sobre el escarpe calizo, junto a la villa romana de El Ruedo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17002','mirador','Mirador de las Almenas del Castillo de Almodóvar','9.8/10 Legendaria e imponente postal de la majestuosa fortaleza medieval recortando la vega del Guadalquivir y la campiña central. Cómo llegar: Torre del homenaje del castillo señorial del siglo XIV, accesible por rampa empedrada desde el pueblo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90445','mirador','Mirador de los Pozuelos de la Dehesa','7.6/10 Paisaje rural de Los Pedroches caracterizado por un inmenso mar de encinas centenarias y cercados de granito tradicionales. Cómo llegar: Camino rural de tierra compactada integrado en el Parque de la Dehesa de la Vera. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17003','mirador','Mirador del Almedina (Castillo de Baena)','9.0/10 Inmensa visual sobre la campiña este, olivares compactos y los restos arqueológicos recuperados de la antigua alcazaba. Cómo llegar: Plaza alta de la Almedina, paseo de ronda rehabilitado en la zona culminante. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17004','mirador','Mirador del Castillo de los Sotomayor y Zúñiga','9.4/10 Impresionante vista de la torre del homenaje gótica más alta de España, alzándose sobre las dehesas del norte provincial. Cómo llegar: Explanada de la barbacana exterior, accesible por pista rural desde el casco urbano. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90446','mirador','Mirador de la Peña de Belmez','9.1/10 Vertiginosa e histórica panorámica de 360 grados sobre el Valle del Guadiato y las antiguas cuencas mineras desde un peñón gigante. Cómo llegar: Torre del homenaje del castillo medieval, escaleras de piedra caliza integradas en la roca viva de la peña. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90447','mirador','Mirador de la Grieta del río Genil','8.4/10 Espectacular y vertical tajo geológico excavado por el río Genil con olivares que cuelgan al borde del abismo. Cómo llegar: Paseo de la Grieta, barandilla de protección urbana en el límite del parque público de la localidad. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90742','mirador','Mirador de la Loma de las Cabañas','7.1/10 Suave horizonte de cultivos cerealistas de secano y encinares dispersos que marcan la penillanura del Guadiato occidental. Cómo llegar: Camino vecinal elevado junto a los depósitos reguladores de agua agrarios. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17005','mirador','Mirador de la Torre del Alcázar (Torre Malmuerta)','8.2/10 Atalaya defensiva andalusí que domina el infinito mar de olivos de la campiña alta y el casco histórico barroco mudéjar. Cómo llegar: Plataforma superior de las murallas del castillo de Bujalance, acceso en la plaza de Santa Ana. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17006','mirador','Mirador de la Ermita de la Virgen de la Sierra (Balcón de Andalucía)','9.6/10 Majestuosa e insuperable atalaya a 1.217 metros sobre el Parque Natural de las Sierras Subbéticas, divisando hasta cinco provincias andaluzas. Cómo llegar: Explanada del santuario en la cima del Picacho de Cabra, carretera Ma-4355 de alta montaña. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90448','mirador','Mirador del Castillo de Cañete','7.4/10 Vista rural de campos de trigo y olivares de secano tradicionales hilvanados por el curso del arroyo Cañete. Cómo llegar: Torre del homenaje restaurada del complejo fortificado del siglo XIV, centro del pueblo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90449','mirador','Mirador del Castillo de Carcabuey','9.2/10 Impresionante fortaleza caliza sobre un espolón que domina el laberinto montañoso de las Subbéticas y valles de olivos centenarios. Cómo llegar: Ermita del Castillo, sendero empedrado fortificado que asciende de forma empinada desde el casco viejo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14017','mirador','Mirador del Paseo Ilustrado','7.3/10 Trazado ortogonal perfecto barroco de las Nuevas Poblaciones rodeado de llanuras de cereal y olivares de la campiña baja. Cómo llegar: Plaza central del Ayuntamiento alto, balcón urbano condicionado sobre la travesía de la N-IV. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14018','mirador','Mirador de la Torre de Garci Méndez','8.3/10 Atalaya mudéjar del siglo XIV con vistas de 360 grados sobre los meandros del Guadalquivir, las acequias y la campiña central. Cómo llegar: Azotea superior accesible de la gran torre defensiva prismática de ladrillo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14019','mirador','Mirador del Barrio de la Villa','8.1/10 Panorámica fluvial de la cuenca del río Guadajoz rodeada de murallas almohades, calles encaladas y olivares artesanales. Cómo llegar: Paseo perimetral de la muralla histórica alta junto a la iglesia parroquial de la Asunción. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14020','mirador','Mirador de la Dehesa de la Estación','7.6/10 Praderas idílicas de encinas viejas de Los Pedroches cruzadas por las ruinas de piedra de la línea ferroviaria minera. Cómo llegar: Entorno rural junto al antiguo puente de hierro del ferrocarril de vía estrecha. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14022','mirador','Mirador del Castillo de Doña Mencía','8.9/10 Hermosa estampa de la Sierra de la subbética cordobesa con el antiguo torreón exento defendiendo el mar de olivos. Cómo llegar: Almenas restauradas del recinto amurallado bajo el abrigo del pico de la Serrezuela. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14023','mirador','Mirador de la Ermita de San Sebastián','8.0/10 Vista aérea del singular conjunto histórico granítico de las antiguas villas unidas de Torremilano y Torrefranca. Cómo llegar: Atrio empedrado del santuario gótico mudéjar situado en lo alto de la colina norte. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14024','mirador','Mirador del Calvario de Encinas Reales','7.5/10 Suaves pendientes de tierra arcillosa roja con un mosaico ininterrumpido de olivares que miran hacia la cuenca del Genil. Cómo llegar: Explanada de la Ermita de Jesús Nazareno, en el punto culminante urbano meridional. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14025','mirador','Mirador del Castillo de Espejo','9.2/10 Imponente e icónica silueta de la fortaleza ducal del siglo XIV dominando una gran loma blanca cercada de olivos. Cómo llegar: Mirador de la calle Castillo, barandilla de hierro bajo los muros de la torre del homenaje. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14026','mirador','Mirador de la Cresta de Espiel (El Alcaide)','90/10 Espectacular meca de la escalada con colosales murallas calcáreas verticales que vigilan la cuenca alta del río Guadiato. Cómo llegar: Sendero local escarpado que sube hacia los abrigos rocosos de la sierra del Castillo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17010','mirador','Mirador del Palacio Ducal','7.9/10 Vista de la campiña cordobesa occidental y las terrazas agrícolas desde los jardines fortificados del palacio neoclásico. Cómo llegar: Balconada de las murallas de las Caballerizas Reales en el recinto monumental. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14029','mirador','Mirador del Palacio de la Candelaria','8.4/10 Vista del entramado urbano histórico inmortalizado por Lope de Vega, dehesas del Guadiato y encinares infinitos de Sierra Morena. Cómo llegar: Terraza exterior del palacete modernista situado en el espolón occidental del casco antiguo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14030','mirador','Mirador de la Colonia del Genil','7.2/10 Horizonte agrícola plano característico del asentamiento carolino de las Nuevas Poblaciones con cultivos extensivos modernos. Cómo llegar: Pista de circunvalación agrícola asfaltada en paralelo a la red de canales de riego. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14031','mirador','Mirador del Yacimiento de Los Castillejos','8.1/10 Entorno de olivos de montaña que esconde el asentamiento fortificado ibero-romano en la frontera de Priego. Cómo llegar: Colina del cerro de los Castillejos, sendero local arqueológico señalizado. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14033','mirador','Mirador de la Vía Verde de la Campiña','7.2/10 Perspectiva horizontal de dehesas bajas y llanuras cerealistas infinitas sobre el trazado del antiguo ferrocarril de Marchena. Cómo llegar: Descansillo acondicionado con bancos en el kilómetro 18 de la Vía Verde. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14034','mirador','Mirador del Yacimiento de Majadaiglesia','7.8/10 Amplio llano místico del Valle de los Pedroches con encinas y pastizales que arropan la ermita de la Virgen de las Cruces. Cómo llegar: Entorno arqueológico de la antigua ciudad romana de Solia, loma suave al norte. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14035','mirador','Mirador de la Catedral de la Sierra','8.5/10 Majestuosa silueta de la gran torre plateresca de la Iglesia de San Juan Bautista emergiendo sobre la penillanura granítica. Cómo llegar: Plaza alta de la Catedral de la Sierra, balaustrada urbana con paneles históricos. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14036','mirador','Mirador del Tajo de Hornachuelos','9.4/10 Vertiginosa e imponente visual del pueblo colgado sobre el barranco del río Bembézar y los densos bosques mediterráneos. Cómo llegar: Paseo de ronda de las murallas medievales, balconada protegida en el casco antiguo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14037','mirador','Mirador de las Tres Cruces / Castillo','9.6/10 Impresionante e icónica estampa de la villa fortificada cercada por el inmenso embalse de Iznájar y lomas de olivar. Cómo llegar: Patio de armas del castillo hispanomusulmán o balcón del barrio alto de las Tres Cruces. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14038','mirador','Mirador del Santuario de la Virgen de Araceli','9.3/10 Soberbia atalaya de la Sierra de Aras a 860 metros, considerado el centro geométrico de Andalucía con visuales a cinco provincias. Cómo llegar: Explanada perimetral fortificada del santuario barroco, carretera local pavimentada A-318. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14039','mirador','Mirador del Castillo de Hisn Lukk','9.2/10 Espectacular peñón calcáreo coronado por la fortaleza islámica, dominando el desfiladero de las Subbéticas y la Laguna del Salobral. Cómo llegar: Pasarela empedrada junto a la Ermita del Rosario en la base rocosa del castillo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14040','mirador','Mirador de la Ermita del Calvario','7.4/10 Paisaje ondulado de la campiña sur cordobesa cubierto por olivares, viñedos de uva Pedro Ximénez y campos de ajo blanco. Cómo llegar: Explanada del santuario, punto geográfico más alto de la loma urbana. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14041','mirador','Mirador del Castillo de Montemayor','8.6/10 Vista de pájaro absoluta desde el cerro de la torre sobre la campiña alta, sus extensos olivares y grandes cortijos históricos. Cómo llegar: Entorno amurallado exterior del castillo señorial de los duques de Frías. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14042','mirador','Mirador del Cerro de la Alhorí','8.7/10 Hermosa alfombra de viñedos de la D.O. Montilla-Moriles combinada con olivares tradicionales y lagunas estacionales bajas. Cómo llegar: Cima de la colina del Castillo de Montilla, accesible por rampa empedrada desde el centro. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14043','mirador','Mirador de las Tres Cruces / Río Ter','9.5/10 Legendario meandro encajonado del río Guadalquivir rodeando de forma geométrica el casco urbano blanco esculpido en piedra molinaza roja. Cómo llegar: Calle de las Tres Cruces, barandilla de hierro sobre el meandro Monumento Natural. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14044','mirador','Mirador de los Paseillos (Cisternas Romanas)','8.1/10 Vista aérea de la campiña sur cordobesa ligada al imponente valor histórico de las mayores cisternas romanas de España. Cómo llegar: Paseo del mirador sobre el escarpe del cementerio de San Rafael, junto a la torre del castillo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14045','mirador','Mirador de los Pagos de Moriles Altos','7.6/10 Colinas calcáreas de tierras blancas (albarizas) tapizadas de cepas viejas que producen caldos generosos tradicionales. Cómo llegar: Ruta del vino de Moriles, mirador rústico acondicionado junto al Lagar de El Monte. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14046','mirador','Mirador del Cerro de la Plaza','7.9/10 Suave oleaje montañoso compuesto por un mar compacto de olivos centenarios que asciende hacia las faldas de las Subbéticas. Cómo llegar: Pista agrícola transitable que corona el cerro de la Plaza, al sur de la localidad. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14047','mirador','Mirador del Castillo de Obejo','8.4/10 Vista salvaje e interior de los valles del Guadiato y las dehesas montañosas encajonadas de Sierra Morena central. Cómo llegar: Ruinas de la torre y murallas árabes situadas en la cresta que abriga el pueblo. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14048','mirador','Mirador del Valle del Genil','7.3/10 Suave transición de olivares que vierten sus laderas hacia la cuenca baja y meandros arcillosos del río Genil. Cómo llegar: Calle San Isidro, barandilla de protección urbana en el extremo sur de la localidad. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14049','mirador','Mirador de la Mesa de San Pedro (Murallas)','8.4/10 Histórica panorámica sobre la vega de naranjos donde convergen de forma imponente los cauces caudalosos del Genil y el Guadalquivir. Cómo llegar: Paseo de ronda fortificado de la muralla almohade, en el casco histórico central. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14050','mirador','Mirador de la Presa de El Carpio','7.6/10 Vista baja del remanso fluvial del río Guadalquivir flanqueado por densos bosques de ribera e infraestructuras hidráulicas históricas. Cómo llegar: Camino rural del azud, acceso directo desde el paraje de la Ermita del Santísimo Cristo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14051','mirador','Mirador de la Torre de El Salvador','8.9/10 Impresionante e histórica atalaya de 56 metros de altura sobre el inmenso mar de dehesas graníticas de Los Pedroches. Cómo llegar: Cuerpo de campanas transitable de la majestuosa torre renacentista de la iglesia parroquial. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14052','mirador','Mirador del Almacén Central (Cerro del Peñón)','8.3/10 Fotogénico e industrial paisaje de chimeneas de ladrillo y castilletes mineros integrados en las dehesas secas del Guadiato. Cómo llegar: Plataforma elevada acondicionada en los cerros calizos de escoria colindantes al pozo Santa Rosa. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14053','mirador','Mirador de la Cantera de la Sierrezuela','8.2/10 Vista geológica de un antiguo frente de extracción de piedra caliza, hoy parque periurbano arbolado de pinos y dehesa baja. Cómo llegar: Senda botánica adaptada del Parque de la Sierrezuela, pasarela de madera con paneles. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14054','mirador','Mirador del Campo de Golf (Cabeza del Buey)','8.5/10 Panorámica rural de la dehesa boyal compacta de encinas centenarias de la capital económica de la comarca norteña. Cómo llegar: Club de campo elevado, accesible por la carretera provincial de circunvalación agraria. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14055','mirador','Mirador del Adarve','9.7/10 Insuperable, mística y bella balconada natural sobre un tajo de 50 metros flanqueado por fuentes barrocas y huertas de olivos. Cómo llegar: Paseo del Adarve, barandilla de hierro histórica que rodea el emblemático Barrio de la Villa. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14056','mirador','Mirador de la Villa Romana de Fuente Álamo','8.5/10 Vista histórica de la vega del arroyo Fuente Álamo vinculada al importante centro de interpretación arqueológico de mosaicos nilóticos. Cómo llegar: Pasarela sobreelevada del complejo arqueológico protegido, a las afueras de la localidad. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14057','mirador','Mirador del Torreón del Castillo','7.6/10 Vista aérea sobre la campiña alfarera de arcillas rojas y campos de trigo tradicionales de secano. Cómo llegar: Terraza superior del torreón defensivo del siglo XIV, en pleno núcleo urbano central. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14058','mirador','Mirador de Rute el Viejo (Sierra de Rute)','9.2/10 Impresionante e imponente perspectiva de las murallas del pueblo medieval abandonado y el inmenso mar del embalse de Iznájar. Cómo llegar: Senda de montaña escarpada que asciende hacia los abrigos rocosos de la sierra caliza. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14059','mirador','Mirador del Llano de los Ballesteros','7.1/10 Perspectiva horizontal cerealista de la campiña baja, herencia colonial de las Nuevas Poblaciones ilustradas carolinas. Cómo llegar: Camino rural sobreelevado contiguo a las antiguas haciendas de grano jesuitas. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14061','mirador','Mirador del Castillo de Miramontes','9.0/10 Confín septentrional absoluto de Córdoba sobre un risco calizo vertical divisando los llanos de la estepa de Ciudad Real. Cómo llegar: Ruinas de la fortaleza calatrava medieval en lo alto de la sierra que domina la villablanca. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14060','mirador','Mirador de la Catedral de la Campiña','8.0/10 Vista desde la muralla de la Iglesia de la Asunción dominando las ricas lomas agrarias de la comarca baja. Cómo llegar: Balcón fortificado urbano de la calle Adarve, acondicionado con bancos y rejería. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14063','mirador','Mirador del Cerro de la Muela','7.4/10 Vista de las lomas olivareras del extremo oriental cordobés que enlazan directamente con la campiña jiennense. Cómo llegar: Hito de tierra batida en la meseta agrícola exenta del término, camino agrario. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14064','mirador','Mirador de la Estación de Valsequillo','7.3/10 Paisaje plano e histórico del Guadiato con encinas dispersas asociadas al antiguo paso ferroviario de mineral. Cómo llegar: Margen de la pista rural consolidada cercana a los antiguos hangares de piedra. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14066','mirador','Mirador del Puente Romano','7.7/10 Vista del cauce medio del río Guadalquivir cruzado por el imponente puente de piedra de la antigua Vía Augusta. Cómo llegar: Parque fluvial de la riera del Salado, accesos peatonales de tierra compactada. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14067','mirador','Mirador de las Estribaciones de Sierra Morena','8.2/10 Gran contraste entre la vega baja regada del Guadalquivir y los primeros relieves forestales densos del norte. Cómo llegar: Mirador de la urbanización alta de la Casita Blanca, barandilla sobre el talud. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14068','mirador','Mirador de los Pozos de Agua Agria','8.3/10 Entorno de dehesas de montaña arboladas de encinas que cobija los históricos balnearios de aguas medicinales de hierro. Cómo llegar: Ruta peatonal ecoturística de los quioscos de agua, lomas al norte del pueblo. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14069','mirador','Mirador de la Dehesa de la Estación AVE','8.6/10 Paisaje ganadero tradicional ibérico de encinas encajonado de forma singular por las modernas vías del tren de alta velocidad. Cómo llegar: Zona de descanso y mirador rústico de la carretera de acceso a la terminal ferroviaria norteña. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14070','mirador','Mirador del Cerro de la Viñuela','8.2/10 Antiguas dehesas mineras reconvertidas con pinos piñoneros con vistas lejanas a la cuenca minera de El Soldado. Cómo llegar: Senda del calvario alto, pista forestal que corona la colina del municipio. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14071','mirador','Mirador de la Dehesa de la nava','8.4/10 Espectacular llano intermontano de Sierra Morena occidental rodeado por densos bosques mediterráneos y dehesas de caza. Cómo llegar: Pista forestal restringida transitable desde la piscina municipal alta hacia las cumbres. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14072','mirador','Mirador de los Molinos del Guadafancil','7.5/10 Paisaje plano granítico de Los Pedroches con las ruinas de piedra de los antiguos molinos hidráulicos harineros. Cómo llegar: Sendero fluvial señalizado accesible desde el puente de la carretera local. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14073','mirador','Mirador del Embalse de Puente Nuevo','9.1/10 Inmensa lámina de agua de la presa encajada entre los pinares y encinares vírgenes de Sierra Morena central. Cómo llegar: Puerto de montaña de la carretera autonómica A-3075, apartadero con paneles informativos. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14074','mirador','Mirador del Embalse de La Colada','8.5/10 Vista directa de las aguas del río Guadamatilla integradas en el extenso y plano encinar ganadero del norte. Cómo llegar: Área recreativa de la playa de interior de La Colada, paseo adaptado sobre pilotes. 📍 Provincia: Córdoba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14075','mirador','Mirador del Cañón del río Bailón / Castillo','9.8/10 Abrumadora, salvaje e icónica visual de un cañón calizo kárstico vertical profundo con el pueblo blanco colgado del abismo. Cómo llegar: Paseo de la Cueva de los Murciélagos o patio de armas de la fortaleza empotrada en el risco. ¡Misión culminada con rotundo éxito! Con el municipio de Zuheros finalizado de forma rigurosa, la provincia de Córdoba queda cerrada al 100% de su geografía municipal. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90745','mirador','Mirador de la Laguna de la Ratosa','7.8/10 Reserva natural con una laguna salina estacional somera, rodeada de olivares, donde es frecuente el avistamiento de flamencos. Cómo llegar: Sendero perimetral de la laguna, accesible por pistas rurales desde la carretera MA-6415. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90433','mirador','Mirador del Boquete de Zafarraya','9.4/10 Espectacular e imponente tajo calcáreo natural en la sierra, paso histórico con vistas colosales de la Axarquía y el mar. Cómo llegar: Alto del puerto en la carretera A-402, límite provincial directo con Granada. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90434','mirador','Mirador de Santo Cristo','8.9/10 Vista panorámica del idílico valle intermontano conocido como los "Pirineos de la Axarquía", cercado por tajos calizos grises. Cómo llegar: Cerro del Santo Cristo, paseo escalonado acondicionado desde la zona alta del pueblo. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90435','mirador','Mirador de los Tajos de Alfarnatejo','9.1/10 Impresionante primer plano de los colosales bloques de piedra de los Tajos de Gómer, Doña Ana y Fraile. Cómo llegar: Senda forestal que une el núcleo urbano con la base de las moles calizas de herencia andalusí. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90436','mirador','Mirador de la Torre Derecha (Algarrobo Costa)','8.5/10 Atalaya costera fortificada del siglo XVI con vistas diáfanas de las playas, el puerto de la Caleta y el Mediterráneo. Cómo llegar: Paseo marítimo, junto a la estructura de la antigua torre vigía de planta de pezuña. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90437','mirador','Mirador de la Ermita del Calvario','8.8/10 Espectacular vista aérea del Valle del Genal, castañares tupidos que cambian de color y el pueblo blanco escalonado. Cómo llegar: Cima del cerro del Calvario, sendero empedrado que parte del casco histórico. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90438','mirador','Mirador de la Hoya de Málaga (Jardín Oriental)','8.2/10 Vista abierta del área metropolitana de Málaga, la desembocadura del Guadalhorce y los contrafuertes de la Sierra de Mijas. Cómo llegar: Terraza superior del estanque en el Parque del Jardín Oriental Zen. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90439','mirador','Mirador de la Ermita del Cristo de la Agonía','8.6/10 Panorámica limpia del Valle del Guadalhorce, ricas huertas de cítricos tradicionales y huertas suburbanas que tapizan la planicie. Cómo llegar: Atrio porticado del santuario situado en las faldas arboladas de pinos de la sierra. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90440','mirador','Mirador de los Paseros','8.5/10 singular relieve ondulado de lomas cubiertas de viñedos de uva moscatel y las estructuras tradicionales de los paseros. Cómo llegar: Paseo de la Axarquía, barandilla de hierro urbana en el extremo norte de la población. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90441','mirador','Mirador de la Estación Arqueológica','7.6/10 Vista del paisaje llano cerealista que conecta la Serranía de Ronda con la llanura sevillana alta. Cómo llegar: Loma suave junto al centro de interpretación arqueológico del ídolo de Almargen. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90442','mirador','Mirador de la Torre de la Vela','8.4/10 Vistas del sinuoso curso del río Campanillas, montes de almendros y los restos consolidados del castillo islámico. Cómo llegar: Restos de la fortaleza medieval que corona el peñón urbano de calles encaladas. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32025','mirador','Mirador del Castillo de las Torres','9.5/10 Inmensa y monumental atalaya sobre el Valle del Guadalhorce, huertas, y la puerta natural al Desfiladero de los Gaitanes. Cómo llegar: Almenas superiores del recinto fortificado medieval, accesible por cuestas empedradas desde la plaza. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32001','mirador','Mirador de las Torres del Castillo / Parque Mirador','8.9/10 Hermosa estampa de la Sierra de las Nieves con los torreones reconstruidos defendiendo los campos de olivo aloreño. Cómo llegar: Recinto ajardinado del antiguo castillo, balconada con espectaculares vistas hacia el valle. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90443','mirador','Mirador de Fray Leopoldo','8.7/10 Vista de la Serranía de Ronda meridional vinculada al monumento del beato, rodeada de riscos calizos y encinas. Cómo llegar: Carretera de montaña MA-7307, explanada con una estatua monumental de bronce del fraile. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','mirador','Mirador de las Almenas de la Alcazaba / El Torcal','9.8/10 Insuperable visual de la Peña de los Enamorados, el casco histórico barroco mudéjar y el laberinto kárstico de El Torcal. Cómo llegar: Torre del homenaje del recinto amurallado o mirador de las Ventanillas en el Parque Natural de El Torcal. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32003','mirador','Mirador del Santuario de la Virgen de Gracia','9.3/10 Soberbia panorámica de la Peña de los Enamorados, los olivares del norte y la singular Plaza Ochavada barroca desde una antigua alcazaba islámica. Cómo llegar: Explanada de la ermita fortificada, en lo alto de la Sierra de Gracia. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32004','mirador','Mirador de los Tres Embalses','9.6/10 Impresionante confluencia visual de las presas del Guadalhorce, Guadalteba y Conde de Guadalhorce entre pinares y cortados calizos vertiginosos. Cómo llegar: Alto de la colina junto al sillón del Rey, acceso por carretera de los embalses. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90444','mirador','Mirador de la Garganta del Arroyo de la Ventilla','8.3/10 Vista encajada de un frondoso bosque de ribera y cañón kárstico salvaje oculto en mitad de la llanura rondeña. Cómo llegar: Sendero local balizado en el extremo norte del casco urbano de piedra. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29021','mirador','Mirador de la Cruz de Atajate','8.6/10 Vista limpia de la Serranía de Ronda occidental y el Valle del Genal, rodeado de un escarpado paisaje kárstico. Cómo llegar: Carretera de montaña A-369, ensanche habilitado a la entrada del municipio más pequeño de la provincia. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29022','mirador','Mirador del Castillo de Benadalid','8.8/10 Singular fortaleza de origen romano y árabe convertida en cementerio municipal, dominando las laderas de castaños y alcornoques. Cómo llegar: Muros exteriores del recinto fortificado exento, accesible desde la travesía urbana de la A-369. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29023','mirador','Mirador del Castillo de Montemayor','9.2/10 Atalaya defensiva andalusí con una brutal panorámica de 360 grados de la Costa del Sol, el mar Mediterráneo y el norte de África. Cómo llegar: Cima del monte Montemayor, sendero empinado forestal desde las afueras residenciales. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29024','mirador','Mirador de las Tres Cruces / El Colmenar','8.9/10 Hermosa estampa de los tejados de pizarra del pueblo blanco encajado en un mar verde de olivares de montaña y pinsapos. Cómo llegar: Explanada de las Tres Cruces, en el sector más elevado del entramado urbano empedrado. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29025','mirador','Mirador del Monte Calamorro','9.4/10 Magnífica visual costera que abarca el puerto deportivo, el perfil litoral mediterráneo de Fuengirola y Málaga y la costa africana. Cómo llegar: Cima de la sierra de Mijas a 771 metros, accesible mediante el teleférico de Benalmádena. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29026','mirador','Mirador del Valle de los Frutales Tropicales','8.0/10 Vistas del vergel regado por el río Benamargosa con plantaciones de aguacates, mangos, limoneros y campos de cítricos. Cómo llegar: Pista agrícola consolidada sobreelevada que comunica el núcleo con la pedanía de El Borge. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29027','mirador','Mirador de la Ermita de San Isidro','7.6/10 Suave perspectiva ondulada de olivares, almendros y vides tradicionales moscatel orientadas hacia la vega baja de Vélez. Cómo llegar: Explanada perimetral del santuario, en el cerro exento que corona el municipio. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29028','mirador','Mirador de la Cueva del Gato','9.2/10 Espectacular e idílica surgencia kárstica donde el río Guadiaro brota de una colosal grieta rocosa formando una poza turquesa cruda. Cómo llegar: Sendero peatonal acondicionado del Parque Natural Sierra de Grazalema, pasarela frente al lago natural. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29029','mirador','Mirador del Monte Porón','8.7/10 Inmersión boscosa en los frondosos alcornocales de los Reales de Estepona con vistas limpias de los valles del Genal. Cómo llegar: Hito de la pista forestal alta, accesible por el sendero local de las pasarelas del río. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29030','mirador','Mirador de la Villa de la Pasa','8.3/10 Cuna del bandolerismo andaluz rodeada de empinadas laderas de viñedos moscatel, paseros tradicionales blancos y olivares rústicos. Cómo llegar: Arco de entrada al municipio, balconada habilitada con murete en el sector oriental. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29031','mirador','Mirador del Puerto de los Viento / Mirador del Turón','91/10 Impresionante e indómito cañón del río Turón flanqueado por los pinares y pinsapares salvajes del Parque Nacional Sierra de las Nieves. Cómo llegar: Carretera de montaña A-366 que conecta con Ronda, apartadero acondicionado con paneles de avistamiento de cabra montés. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29032','mirador','Mirador de la Reserva Natural de las Lagunas de Campillos','8.2/10 Complejo endorreico de lagunas salinas estacionales someras (Dulce y Salada) rodeadas de campos de trigo y olivares de secano. Cómo llegar: Observatorio ornitológico de madera accesible por senderos llanos desde la carretera A-357. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29033','mirador','Mirador del Saltillo (Puente Colgante)','9.5/10 Espectacular y vertiginoso puente colgante a 50 metros sobre el cañón del río Almanchares, bajo la imponente cumbre de la Maroma. Cómo llegar: Tramo aéreo de la Senda Gran Senda de Málaga (GR-249), anclado a las paredes del desfiladero calizo. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29034','mirador','Mirador de la Ermita de Santa Ana','8.9/10 Atalaya de la Axarquía alta colgada en una solana caliza, divisando las laderas forestales de Tejeda y el mar mediterráneo. Cómo llegar: Explanada de piedra de la ermita, en el extremo superior del entramado urbano encalado. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29035','mirador','Mirador del Castillo de Hins Canit','8.9/10 Fortaleza medieval defensiva que corona un espolón kárstico, divisando las laderas cerealistas y las colonias de buitre leonado. Cómo llegar: Paseo de ronda amurallado de la torre del homenaje rehabilitada, centro de interpretación. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29036','mirador','Mirador de la Plaza de Toros / Baños','85/10 Vista urbana y de montaña del histórico enclave termal decimonónico, encajonado en el desfiladero de la Sierra de Alcaparaín. Cómo llegar: Balcón exterior de la singular plaza de toros excavada en la roca caliza del cerro alto. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29038','mirador','Mirador de la Ermita de Nuestra Señora de los Remedios','8.4/10 Vista de pájaro absoluta sobre el Valle del Guadalhorce, las ricas huertas citrícolas tradicionales y los restos del castillo hispanomusulmán. Cómo llegar: Explanada del santuario barroco en la cumbre del cerro de la Virgen, sendero empedrado de subida. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29039','mirador','Mirador de la Torre Zambra','8.6/10 Atalaya militar del siglo XIII que domina de forma impecable los Montes de Málaga, el corredor de Antequera y Sierra Nevada al fondo. Cómo llegar: Cima de la colina de la torre óptica, accesible por pista forestal transitable desde el núcleo urbano. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29040','mirador','Mirador de la Plaza de Buenavista (Castillo)','9.0/10 Hermoso y laberíntico balcón andalusí sobre el valle del Guadalhorce, flanqueado por las murallas calcáreas altas de la Sierra de Alcaparaín. Cómo llegar: Plaza-mirador habilitada sobre los cimientos del antiguo alcázar islámico en la zona alta. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29041','mirador','Mirador del Castillo de Casares','9.6/10 Legendaria e insuperable postal de la villa blanca colgada de forma vertical en el peñón, con vistas al estrecho de Gibraltar y África. Cómo llegar: Recinto amurallado de la antigua fortaleza medieval que corona el crestón calizo de la población. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29042','mirador','Mirador de la Albuqueria','8.3/10 Panorámica rural de los pinares piñoneros de Sierra de Mijas fusionados con el mosaico hortícola de la vega del río Pereilas. Cómo llegar: Pista forestal vecinal acondicionada de la zona alta de la Albuqueria. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29043','mirador','Mirador de la Ermita de la Candelaria','8.4/10 Ventana de media montaña al Parque Natural Montes de Málaga con olivares, encinas rústicas y campos tradicionales. Cómo llegar: Atrio empedrado del santuario del siglo XVII, situado en el punto geográfico culminante de la villa. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29044','mirador','Mirador de la Plaza de la Constitución (Balcón de la Axarquía)','9.7/10 Insuperable, mística y abrumadora vista aérea de 360 grados colgada a 700 metros sobre lomas de viñedos y el mar. Cómo llegar: Meseta caliza fortificada del casco antiguo, paseo perimetral junto a los restos de la torre de la Tahona. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29045','mirador','Mirador de Gaudí / Entrada del Pueblo','9.3/10 Colorida balconada de estilo modernista con azulejos gaudianos, dominando los viñedos viejos y el Parque Natural de Almijara. Cómo llegar: Entrada sur del municipio, mirador acondicionado sobre la carretera principal de acceso. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29046','mirador','Mirador del Cañón de las Buitreras','9.3/10 Salvaje y monumental tajo kárstico calizo vertical excavado por el río Guadiaro, hogar de la mayor colonia de buitres de la serranía. Cómo llegar: Sendero de gran recorrido GR-141, tramo sobre el puente de los Alemanes colgado del abismo. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29047','mirador','Mirador del río Genil (La Huertana)','7.6/10 Perspectiva de la vega fluvial baja con cultivos tradicionales de zanahoria morá e ingenios hidráulicos de norias de caña. Cómo llegar: Senda fluvial de la noria de la Agustín, área recreativa acondicionada junto al cauce. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29049','mirador','Mirador de la Falla del Camorro','8.8/10 Espectacular e imponente monumento natural calizo que cobija la Cueva de Belda y vigila el inmenso cauce embalsado de Iznájar. Cómo llegar: Pista forestal que asciende hacia los pies del macizo del Camorro, paneles Starlight de la sierra. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29048','mirador','Mirador del Nacimiento de El Carrizal','8.1/10 Entorno de olivos y chopos que rodea la imponente cueva de la que brotan las aguas limpias subterráneas del término municipal. Cómo llegar: Complejo natural de las Fuentes de Cuevas, senderos peatonales de tierra batida. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29050','mirador','Mirador de la Peña de Hierro','8.2/10 Paisaje tradicional morisco de lomas escarpadas con viñedos de pasas y olivos dispersos bajo el cielo limpio de la Axarquía interior. Cómo llegar: Camino rural sobreelevado que comunica el núcleo central con el barrio alto de la Zubia. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29051','mirador','Mirador de los Reales de Sierra Bermeja','9.5/10 Majestuoso mirador a 1.450 metros sobre un ecosistema singular de rocas peridotitas rojas, pinsapos, el estrecho y Marruecos de fondo. Cómo llegar: Cima del pico de los Reales, carretera escénica de montaña MA-557, refugio forestal adaptado. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29052','mirador','Mirador de las Chorreras de Balastar','8.8/10 Idílico salto de agua doble de 20 metros esculpido sobre terrazas agrícolas y huertas de herencia morisca andalusí. Cómo llegar: Sendero local peatonal señalizado que desciende desde las afueras residenciales bajas del pueblo. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29053','mirador','Mirador del Castillo / Lízar','9.6/10 Insuperable y fotogénica panorámica del casco mudéjar galardonado, los desfiladeros boscosos de Almijara y el mar Mediterráneo de Nerja. Cómo llegar: Ruinas de la antigua fortaleza islámica de Lízar, cima de la colina accesible por el sendero alto del pueblo. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29054','mirador','Mirador del Castillo de Sohail','8.7/10 Vista costera histórica que domina la desembocadura del río Fuengirola, el puente peatonal colgante y el frente marítimo urbano. Cómo llegar: Almenas transitables de la fortaleza hispanomusulmán del siglo X alzada sobre la colina de la playa. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29056','mirador','Mirador del Castillo del Águila','9.6/10 Balcón estratégico de infarto a 680 metros de altitud, con el peñón de Gibraltar y los barcos cruzando el Estrecho de forma brutal. Cómo llegar: Muros defensivos del recinto fortificado medieval, sendero empedrado fortificado desde la plaza alta. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29057','mirador','Mirador de la Plaza de la Constitución / Pueblo Museo','9.2/10 Combinación perfecta de esculturas artísticas contemporáneas integradas en el entramado urbano blanco y vistas del denso pinsapar forestal. Cómo llegar: Balconada de la plaza de la iglesia, con paneles informativos del Valle del Genal. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29058','mirador','Mirador del Valle del almendro','8.3/10 Suave relieve de almendrales tradicionales que cambian el paisaje en época de floración, a las puertas de la Sierra de las Nieves. Cómo llegar: Calle del mirador, plataforma de hormigón con paneles interpretativos agrícolas en el barrio alto. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29059','mirador','Mirador del Humilladero / Sierrecilla','7.8/10 Vista del llano agrícola central de la comarca baja ante una pequeña colina exenta cubierta de espeso pinar carrasco. Cómo llegar: Paraje natural adaptado de la Sierrecilla, sendero botánico hacia el hito geodésico superior. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29060','mirador','Mirador del Nacimiento del Río Genal','9.0/10 Espectacular e idílica cueva natural urbana de la que brotan las aguas del Genil entre densos bosques de castaños gigantes. Cómo llegar: Área recreativa acondicionada al inicio de la travesía de la carretera de montaña MA-7300. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29061','mirador','Mirador del Embalse de la Concepción','9.1/10 Vista directa de las aguas limpias de la presa encajadas entre los pinares y murallas del parque natural de las Nieves. Cómo llegar: Kilómetro 12 de la carretera local de Istán, apartadero acondicionado con rejería de protección. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29062','mirador','Mirador de la Loma de Barco','8.1/10 Suave paisaje de viñedos moscatel y cultivos hortícolas tradicionales andaluces que miran hacia la mar de Vélez. Cómo llegar: Camino rural sobreelevado contiguo a las balsas de riego del término municipal. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29063','mirador','Mirador de la Estación / Valle del Guadiaro','8.9/10 Panorámica fluvial de la cuenca media del Guadiaro rodeada de encinares, olivares artesanales y la línea de ferrocarril histórica. Cómo llegar: Paseo de la barriada de la Estación, sendero peatonal acondicionado junto al cauce. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29064','mirador','Mirador del Peñón Colorado','9.0/10 Salvaje e imponente perspectiva geológica del curso del Genal encajonado en densos bosques de pinos bermejos y castaños. Cómo llegar: Kilómetro 22 de la carretera de montaña MA-8305, mirador rústico con barandilla. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29065','mirador','Mirador de Torrecilla / Pueblo Azul','8.8/10 Pintoresco y llamativo contraste de las casas pintadas de azul pitufo integradas en el verde del castañar y relieves de piedra. Cómo llegar: Carretera de acceso MA-7303, apartadero acondicionado con figuras temáticas monumentales. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29066','mirador','Mirador de la Iglesia de San Jacinto','8.2/10 Suave relieve de la Axarquía cubierto de olivares e historia ligada a la familia Gálvez y la fábrica de naipes colonial. Cómo llegar: Plaza elevada del templo barroco clasicista, en el centro urbano de calles empedradas. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','mirador','Mirador de Gibralfaro','9.7/10 Icónica e incomparable panorámica del puerto de cruceros, el parque urbano tropical, la catedral de la Manquita y la bahía. Cómo llegar: Paseo de ronda fortificado del Castillo de Gibralfaro o plataforma exterior vallada del camino forestal. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29068','mirador','Mirador del Castillo de la Duquesa','8.5/10 Vista de la costa suroccidental malagueña, el puerto deportivo de la Duquesa y viñedos litorales de uva moscatel tradicionales. Cómo llegar: Muros de la fortaleza fortificada del siglo XVIII costera, acceso peatonal desde el paseo marítimo. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29069','mirador','Mirador de Juanar (Sierra Blanca)','9.6/10 Impresionante e inmenso abismo vertical calizo con una panorámica completa de Marbella, Puerto Banús y el mar Mediterráneo abierto. Cómo llegar: Final del sendero botánico de los llanos de Juanar, plataforma con la Cruz de Juanar o mirador del Corzo. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29070','mirador','Mirador del Compás (Murallas de Mijas)','9.4/10 Espectacular e histórico paseo colgado en el acantilado calizo con vistas del litoral costero arropado por pinos y jardines urbanos. Cómo llegar: Jardines de la Muralla del casco antiguo blanco, balcón vallado de piedra sillar tradicional. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29071','mirador','Mirador del Enoturismo (Paseo de la Axarquía)','8.1/10 Paisaje abancalado tradicional de viñedos y olivos que produce vinos moscatel bajo el abrigo de la loma urbana. Cómo llegar: Entrada sur del pueblo, ensanche de la calzada acondicionado con barandilla protectora. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29072','mirador','Mirador de la Sierra de la Camorra','7.8/10 Atalaya caliza exenta sobre los inmensos viñedos y olivares llanos del norte provincial que alberga importantes cuevas kársticas. Cómo llegar: Pista forestal batida transitable que asciende hacia el área recreativa del Santillán. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29073','mirador','Mirador del Castillo de Monda','8.6/10 Fortaleza señorial andalusí reconvertida en hotel que vigila el valle olivarero del Guadalhorce y las laderas de Sierra Blanca. Cómo llegar: Balcón exterior fortificado del castillo, accesible por rampa empedrada urbana. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29074','mirador','Mirador de El Castillo / Karst de Líbar','9.2/10 Impresionante e imponente peñón rocoso con vistas de infarto sobre el llanor kárstico calcáreo cerrado y la Serranía profunda. Cómo llegar: Cima del cerro del Castillo urbano, escaleras integradas con barandilla desde la plaza de la iglesia. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29075','mirador','Balcón de Europa','9.7/10 Mítico, colosal y emblemático paseo circular colgado sobre un acantilado marino redondo que penetra aguas turquesas cristalinas. Cómo llegar: Plaza central del Balcón de Europa, paseo peatonal fortificado con cañones históricos coloniales. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29079','mirador','Mirador de la Plaza de la Lomilleja','9.1/10 Espectacular e inmensa panorámica sobre el embalse de la Viñuela encajado entre lomas de olivares de la variedad verdial. Cómo llegar: Plaza porticada en el extremo sur del núcleo urbano, barandilla de hierro sobre el desnivel. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29081','mirador','Mirador de la Cruz de la Frontera','8.9/10 Inmersión total en el castañar más denso y salvaje de la Serranía de Ronda, espectacular durante el otoño del Bosque de Cobre. Cómo llegar: Pista forestal que asciende hacia el límite del término municipal con Igualeja. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29082','mirador','Mirador del Cantal (Torre de Benagalbón)','8.8/10 Acantilados calcáreos marinos con pasarelas peatonales que dividen las playas y conectan con la antigua torre vigía nazarí. Cómo llegar: Paseo de los acantilados de El Cantal, pasarelas e hitos informativos costeros. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29083','mirador','Mirador del Tajo de Gomer','8.4/10 Vista de las formaciones calizas de la alta Axarquía con olivares tradicionales y restos de molinos de aceite históricos. Cómo llegar: Calle del mirador, barandilla de hierro urbana en el límite del escarpe del pueblo. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','mirador','Mirador del Puente Nuevo / Tajo de Ronda','99/10 Insuperable, legendaria e internacional obra monumental sobre una imponente grieta caliza de 100 metros cruzada por el puente de piedra. Cómo llegar: Mirador de Aldehuela o balcones colgados del paseo de Blas Infante en pleno casco histórico monumental. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29085','mirador','Mirador del Puente Romano / Alminar','8.6/10 Vista encajada del curso del río Salares con el puente medieval de arco único y el espectacular alminar mudéjar de azulejos. Cómo llegar: Sendero local fluvial del Parque Natural de Tejeda y Almijara en la base del núcleo antiguo. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29086','mirador','Mirador del Cementerio Redondo','8.4/10 Vista singular del único cementerio octogonal de España, mimetizado entre colinas cubiertas de almendros y viñedos de la Axarquía. Cómo llegar: Perímetro superior fortificado del recinto arquitectónico, al norte del casco urbano. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29087','mirador','Mirador de la Casa Torreón / Almijara','8.9/10 Vista del entramado morisco empedrado bajo la mole caliza del pico de la Maroma y los bosques del Parque Natural. Cómo llegar: Azotea transitable de la torre mudéjar o mirador urbano de las eras altas. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29055','mirador','Mirador de la Laguna de Fuente de Piedra (Cerro del Palo)','9.2/10 Espectacular observatorio sobre la laguna salina más grande de Andalucía, hogar del mayor mar estacional de flamencos de España. Cómo llegar: Centro de interpretación José Antonio Valverde, pasarelas de madera y casetas ornitológicas elevadas. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29076','mirador','Mirador de las Cuevas de Ojén','9.1/10 Espectacular frente kárstico de cuevas naturales iluminadas integradas en los jardines botánicos colgantes urbanos del pueblo blanco. Cómo llegar: Pasarelas del complejo municipal de las Cuevas de Ojén, accesos urbanos señalizados. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29077','mirador','Mirador del Bosque de Cobre / Pinsapar','93/10 Abrumador tapiz vegetal de castaños y pinares de montaña del alto Genal lindando con el pinsapar protegido de las Nieves. Cómo llegar: Borde del sendero circular del Bosque Encantado de Parauta, en las afueras residenciales altas. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29080','mirador','Mirador del Santo de Pizarra','8.5/10 Impresionante monumento del Sagrado Corazón alzado sobre gigantescas lajas de arenisca erosionadas con vistas del Guadalhorce. Cómo llegar: Cima de la Sierra de Gibralmora, sendero de montaña empinado desde el área recreativa del Rajar. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29088','mirador','Mirador de la Sierra de los Caballos','7.2/10 Suave paisaje de olivares y cultivos de secano de la campiña alta que se confunde con el llano sevillano. Cómo llegar: Hito geodésico de la loma exenta, accesible por caminos rurales consolidados. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29089','mirador','Mirador del Castillo de la Estrella','9.2/10 Impresionante e histórica fortaleza andalusí que domina los desfiladeros del río Guadalteba y las llanuras cerealistas del norte. Cómo llegar: Torre del homenaje del complejo amurallado, accesible por pista empedrada desde el municipio. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29090','mirador','Mirador de las Tres Cruces (Sierra de las Nieves)','9.4/10 Abrumadora panorámica de la alta montaña malagueña, con laderas cubiertas de pinsapos relictos y profundos barrancos calizos. Cómo llegar: Pista forestal transitable que asciende desde el balneario de Fuente Amargosa hacia las cumbres. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29901','mirador','Mirador de la Torre de Pimentel (Torre de los Molinos)','8.5/10 Atalaya defensiva de ladrillo que vigila de forma icónica la playa del Bajondillo, el frente marítimo y el mar Mediterráneo. Cómo llegar: Final de la calle San Miguel, escarpe peatonal acondicionado sobre el barrio marinero bajo. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29091','mirador','Mirador del Faro de Torrox / Balcón de la Costa','8.8/10 Vista costera monumental sobre las ruinas de la villa romana, las playas del faro y el horizonte marino infinito. Cómo llegar: Pasarela marítima acristalada construida junto al recinto de señales del faro costero. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29092','mirador','Mirador de la Torre Salazar','7.8/10 Vista del angosto valle del arroyo Totalán salpicado de olivares y almendros con el mar de Rincón de la Victoria al fondo. Cómo llegar: Torre de guaita medieval exenta en la cresta de la colina que corona el puebloblanco. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29093','mirador','Mirador de la Ermita del Cristo de la Sierra','9.1/10 Espectacular e imponente pared caliza vertical (cuna del vuelo libre) dominando todo el valle, los olivares y las vías del AVE. Cómo llegar: Explanada perimetral del santuario colgado en la roca, pista de subida desde el casco urbano. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29095','mirador','Mirador de las Ermitas Rupestres de Mozárabes','7.6/10 Vista arqueológica e interior de cuevas eremíticas del siglo IX excavadas en un entorno de denso olivar tradicional. Cómo llegar: Complejo arqueológico del Peñón de la Virgen, sendero local balizado desde las afueras. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29902','mirador','Mirador de la Ventanilla (El Torcal)','9.0/10 Alucinante y fotogénica perspectiva de las caprichosas formaciones de piedra caliza esculpidas por el agua del Parque Natural del Torcal. Cómo llegar: Sendero señalizado de la Ruta Verde, balcón natural protegido en el límite sur del Torcal. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29098','mirador','Mirador del Trifinio (El Entricho)','7.4/10 Hito geográfico e histórico donde se unen las provincias de Málaga, Granada y Córdoba entre lomas infinitas de olivar. Cómo llegar: Pista agrícola transitable de tierra batida del paraje de El Entricho. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29096','mirador','Mirador de la Hondonada / Dehesa','8.6/10 Paisaje kárstico de montaña con praderas altas rústicas cercadas por el imponente murallón de la Sierra de Camarolos. Cómo llegar: Pista forestal compactada que arranca de las inmediaciones de la fuente de El Elbro. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29097','mirador','Mirador de los Cien Caños','8.9/10 Espectacular e idílica postal caliza con decenas de chorros de agua brotando de las paredes rocosas, origen del río Guadalhorce. Cómo llegar: Área recreativa de la Fuente de los Cien Caños, sendero peatonal junto al cauce fluvial. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29099','mirador','Mirador del Embalse de La Viñuela','8.8/10 Inmensa lámina de agua de color turquesa rodeada de viñedos moscatel y olivares con la silueta imponente del Boquete de Zafarraya de fondo. Cómo llegar: Carretera autonómica A-356, apartaderos acondicionados y equipados con paneles interpretativos del paisaje. 📍 Provincia: Málaga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29100','mirador','Mirador de Luis Ceballos','9.5/10 Majestuoso e incomparable balcón forestal rodeado por el mayor bosque protegido de pinsapos del mundo en la Sierra de las Nieves. Cómo llegar: Pista forestal acondicionada accesible en coche desde la Torre de vigilancia de Yunquera. ¡Misión culminada! Con el municipio de Yunquera cerrado con total rigor, la provincia de Málaga queda completada al 100% de punta a punta. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90747','mirador','Mirador del Cerro de la Ermita','7.1/10 Vista limpia de las llanuras agrícolas de la campiña sevillana, con mosaicos de olivar y cultivos de cereal. Cómo llegar: Explanada de la Ermita de San José, en la elevación natural al norte del núcleo urbano. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40001','mirador','Mirador del Castillo de Alanís','8.8/10 Histórica panorámica de dehesas de encinas y alcornoques integradas en el Parque Natural de la Sierra Norte de Sevilla. Cómo llegar: Adosado a los muros de la fortaleza medieval que corona la colina del municipio. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90450','mirador','Mirador de la Torre de Don Fadrique','7.8/10 Atalaya mudéjar con vistas privilegiadas del corredor del Guadiamar, olivares tradicionales y la llanura aljarafeña. Cómo llegar: Plataforma superior de la torre de los "Mocha", accesible desde el casco urbano. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40002','mirador','Mirador del Castillo y los Molinos del Guadaíra','8.9/10 Espectacular e histórica vista del río Guadaíra, sus molinos harineros árabes y el recinto amurallado fortificado de la villa. Cómo llegar: Paseo de ronda de la Alcazaba musulmana, en el cerro del Castillo. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90451','mirador','Mirador de la Presa de Alcalá','7.6/10 Vista baja y despejada del río Guadalquivir regulado por el gran azud, rodeado de huertas de naranjos. Cómo llegar: Paseo fluvial de la bajada del embarcadero, junto al puente de la presa. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90452','mirador','Mirador de las Ruinas de Arva','7.4/10 Perspectiva arqueológica y fluvial del río Guadalquivir y las ricas terrazas aluviales sembradas de frutales y olivos. Cómo llegar: Cerro testigo del yacimiento romano, accesible por pistas rurales desde la carretera SE-4103. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90748','mirador','Mirador de la Torre de los Guzmanes','7.5/10 Imponente atalaya mudéjar civil del siglo XV dominando la vega del Guadalquivir y las plantaciones citrícolas perimetrales. Cómo llegar: Azotea superior accesible de la gran torre defensiva prismática de ladrillo. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90453','mirador','Mirador del Cerro del Calvario','8.7/10 Vista aérea del pueblo blanco y el paisaje quebrado de Sierra Morena, rodeado de dehesas ganaderas compactas. Cómo llegar: Cima de la colina del Calvario, sendero empedrado balizado desde el casco viejo. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90454','mirador','Mirador de la Hacienda de San Antonio','7.0/10 Suave relieve del Aljarafe meridional cubierto de olivares tradicionales que miran hacia las marismas lejanas del Guadalquivir. Cómo llegar: Camino rural de tierra compactada contiguo a los antiguos campos de la hacienda. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90455','mirador','Mirador del Campillo','7.5/10 Inmenso mar horizontal de olivares dedicados a la aceituna de mesa (manzanilla y gordal) característico de la campiña. Cómo llegar: Elevación natural del terreno junto al camino vecinal que conecta con Morón de la Frontera. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41012','mirador','Mirador de los Pinares de Aznalcázar','8.6/10 Espectacular boscaje mediterráneo de pinos piñoneros piñoneros gigantes, encinas y matorral que sirve de antesala a Doñana. Cómo llegar: Área recreativa del sendero botánico de las Minas, mirador de madera acondicionado. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41013','mirador','Mirador del Embalse del Agrio','8.3/10 Vista directa de la lámina de agua encajada entre colinas mineras y las estribaciones desérticas occidentales de Sierra Morena. Cómo llegar: Corona de la presa del Agrio, accesible por carretera local bien señalizada. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41014','mirador','Mirador del Meandro del río Genil','8.4/10 Impresionante encajonamiento fluvial del río Genil con olivares tradicionales que cuelgan del talud, cerca de Malpasillo. Cómo llegar: Pista agrícola de tierra compactada en el paraje de las Huertas de la Isla. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41015','mirador','Mirador de la Cárcava del Guadiamar','7.8/10 Escarpe natural del Aljarafe occidental con vistas al Paisaje Protegido del Corredor Verde del río Guadiamar. Cómo llegar: Entorno rural inmediato a la Ermita de Nuestra Señora de Gines, borde del talud. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41016','mirador','Mirador de la Ermita de Cuatrovitas','7.7/10 Mística postal de un santuario levantado sobre un alminar almohade del siglo XII rodeado de encinares y olivares. Cómo llegar: Explanada empedrada exterior de la ermita mudéjar, carretera local señalizada. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41017','mirador','Mirador de la Hacienda de Regla','7.1/10 Panorámica suburbana sobre las suaves lomas del Aljarafe, antiguos olivares de verdeo y el perfil metropolitano de Sevilla. Cómo llegar: Espacio público elevado contiguo al complejo histórico y aceitero de la antigua hacienda. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41018','mirador','Mirador de las Riberas del Guadalquivir','7.3/10 Vista baja y despejada del gran eje fluvial andaluz, sus sotos de sauces y el tapiz de cultivos frutales de regadío. Cómo llegar: Mota fluvial reforzada en el extremo meridional del término municipal. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41019','mirador','Mirador de la Ermita de la Madroña','7.8/10 Vista limpia de la transición entre la Vega del Guadalquivir y las primeras dehesas graníticas de Sierra Morena. Cómo llegar: Explanada del santuario de la Virgen del Rosario, paraje natural de La Madroña. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41020','mirador','Mirador de la Iglesia de San Juan Bautista','8.2/10 Atalaya histórica excepcional sobre las marismas bajas del Guadalquivir, las canteras de calizas de la loma y los campos cerealistas. Cómo llegar: Plaza alta porticada del templo barroco, punto más elevado de la localidad. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41021','mirador','Mirador del Cerro del Carambolo','8.4/10 Histórica y legendaria atalaya vinculada al tesoro tartésico, dominando de forma cenital el cauce del Guadalquivir y Sevilla. Cómo llegar: Risco exterior de las ruinas arqueológicas, accesible desde el barrio alto de la barriada. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41022','mirador','Mirador del Pozo Santo','7.4/10 Amplio horizonte agrario de la campiña sevillana oriental, caracterizado por el cultivo de trigo, girasol y olivos. Cómo llegar: Loma de tierra batida acondicionada junto al antiguo pozo de abastecimiento rural. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41023','mirador','Mirador del Palacio de los Condes (Torre del Reloj)','8.1/10 Vista aérea del casco antiguo de callejuelas encaladas, la desembocadura del río Viar y las huertas de naranjos. Cómo llegar: Entorno de la antigua torre de guaita y recinto señorial fortificado del municipio. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41024','mirador','Mirador del Alcázar del Rey Don Pedro (El Picacho)','9.7/10 Insuperable, majestuosa e inmensa panorámica sobre la infinita Vega de Carmona desde los escarpes de un gigantesco alcázar. Cómo llegar: Parador Nacional de Turismo, balconada de piedra sillar colgada en el borde del acantilado histórico. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41025','mirador','Mirador del Alcarayón','7.2/10 Perspectiva baja de las riberas del arroyo Alcarayón flanqueadas por cultivos de secano y viñedos tradicionales del Condado. Cómo llegar: Puente rural de mampostería y caminos agrícolas que bordean el cauce estacional. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41026','mirador','Mirador del Yacimiento de Ventippo','7.9/10 Vista histórica y rural de la cuenca del río Yeguas, ligada a las ruinas de la ciudad romana de los mosaicos. Cómo llegar: Cerro de la Mesa, plataforma arqueológica con barandilla rústica a las afueras de la localidad. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41027','mirador','Mirador del Alto de la Bellota','8.4/10 Paso de montaña en pleno Camino de Santiago de la Plata, rodeado de frondosas dehesas de encinas y monte bajo. Cómo llegar: Kilómetro 12 de la carretera A-433, apartadero señalizado con paneles del parque forestal. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41028','mirador','Mirador del Balcón de la Cornisa','8.1/10 Espectacular caída visual desde el borde del Aljarafe norte hacia el valle aluvial, los jardines históricos y Sevilla. Cómo llegar: Paseo de la Cornisa, mirador urbano acondicionado frente al palacio de los condes de Castilleja. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41029','mirador','Mirador de la Plaza de Santiago','7.8/10 Vista del casco histórico mudéjar y del palacio barroco de Hernán Cortés integrado en el talud metropolitano. Cómo llegar: Balaustrada de la plaza monumental, en el borde oriental elevado del núcleo urbano. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41030','mirador','Mirador del Campo de Tejada','7.1/10 Suave horizonte de cultivos cerealistas tradicionales que marcan la llanura de transición fronteriza con Huelva. Cómo llegar: Camino rural sobreelevado contiguo a las antiguas cooperativas agrarias del pueblo. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41031','mirador','Mirador del Torreón del Castillo','8.6/10 Vista salvaje y serrana de dehesas ganaderas quebradas y los cercados rústicos de piedra caliza de la cuenca minera. Cómo llegar: Cima del peñón rocoso donde se asientan las ruinas de la antigua fortaleza islámica. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41032','mirador','Mirador del Puerto del Boquerón','9.2/10 Majestuoso mar de dehesas de alcornoques y encinas del Parque Natural Sierra Norte, con valles quebrados y viñedos históricos. Cómo llegar: Carretera A-432, km 46, punto elevado acondicionado con zona de estacionamiento. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41033','mirador','Mirador del Castillo de Constantina','9.1/10 Vista aérea espectacular del entramado urbano blanco del Barrio de la Morería bajo la imponente torre del homenaje almorávide. Cómo llegar: Explanada de la fortaleza medieval que corona el cerro del Castillo, acceso pavimentado. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41034','mirador','Mirador del Cerro de San Juan','83/10 Histórica panorámica del curso bajo del río Guadalquivir, las primeras marismas y el paso de los barcos mercantes. Cómo llegar: Ermita de San Juan Bautista, espolón natural acondicionado sobre el cauce fluvial. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41037','mirador','Mirador de la Sierra de la Cruz','7.6/10 Suaves pendientes olivareras de transición que conectan la campiña sur sevillana con las sierras subbéticas malagueñas. Cómo llegar: Hito geodésico y mirador rústico accesible por pistas agrícolas desde el sur del núcleo. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41903','mirador','Mirador de la Laguna de los Tollos','7.9/10 Observatorio de un importante humedal estacional recuperado, zona de paso de aves migratorias entre campiñas y alfombras de cereal. Cómo llegar: Aula de la Naturaleza de la Laguna de los Tollos, senderos perimetrales adaptados. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41038','mirador','Mirador del Gran Hipódromo de Andalucía','7.4/10 Visual llana del área metropolitana meridional, plantaciones de olivar de verdeo e infraestructuras del sur sevillano. Cómo llegar: Terrazas superiores del complejo deportivo en el sector residencial de Entrenúcleos. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41039','mirador','Mirador de las Torres de Écija (Plaza de España)','8.9/10 Impresionante silueta barroca de las once famosas torres y campanarios de azulejos recortando el cielo de la campiña del Genil. Cómo llegar: Azotea transitable del Palacio de Benamejí o terrazas altas de la plaza del Salón. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41040','mirador','Mirador del Santuario de Loreto','7.2/10 Entorno místico rodeado de olivos tradicionales y haciendas barrocas en el corazón del Aljarafe residencial. Cómo llegar: Atrio exterior y jardines del monasterio franciscano del siglo XVIII. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41041','mirador','Mirador del Balcón de Andalucía (Cerro de San Cristóbal)','9.4/10 Inmensa e insuperable atalaya sobre la campiña este desde un peñón fortificado, divisando llanuras olivareras infinitas. Cómo llegar: Recinto de la torre del homenaje y el convento de Santa Clara, en la cima del cerro. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41042','mirador','Mirador del Castillo de la Monclova','7.8/10 Vista señorial de la campiña baja, campos de trigo y girasol que arropan la fortificación medieval remodelada. Cómo llegar: Pista de acceso perimetral de la finca histórica de la Monclova, carretera SE-9011. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41043','mirador','Mirador de la Sierra de la Grana','8.1/10 Vista de dehesas ganaderas y encinares densos en la transición de la provincia hacia el territorio montañoso de Huelva. Cómo llegar: Camino forestal de tierra batida que arranca desde el linde norte del casco urbano. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41044','mirador','Mirador del Parque del Pandero','8.4/10 Vista cenital de la cornisa del Aljarafe sobre la vega del Guadalquivir, el puerto deportivo y el sur metropolitano. Cómo llegar: Pasarelas del parque público del Pandero, barandillas sobre el escarpe natural. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41045','mirador','Mirador de las Canteras de Granito','8.0/10 Singular paisaje minero de grandes bloques tallados en roca granítica gris, antesala del relieve de Sierra Morena. Cómo llegar: Parque de las Canteras, mirador acondicionado con paneles en el sector norte de la villa. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41046','mirador','Mirador del Ojo de Gilena','8.2/10 Entorno de monte bajo mediterráneo y pinares calizos que vigila las lomas olivareras de la comarca de Estepa. Cómo llegar: Senda del nacimiento del agua, área recreativa acondicionada con miradores rústicos de madera. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41047','mirador','Mirador del Paseo Juan de Dios','7.0/10 Perspectiva urbana residencial baja integrada en las lomas centrales del Aljarafe de la corona metropolitana. Cómo llegar: Calle Juan de Dios Soto, plataforma ajardinada pública de la localidad. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41048','mirador','Mirador de La Capitana','9.1/10 Techo de la Sierra Norte a 960 metros con vistas colosales de las dehesas andaluzas y las llanuras extremas de Badajoz. Cómo llegar: Pista militar transitable que corona el antiguo observatorio y radar en la cumbre de la sierra. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41049','mirador','Mirador del Contraembalse de El Gergal','8.1/10 Vista limpia de la lámina de agua encajada entre las primeras lomas de Sierra Morena, rodeada de encinares y pinos. Cómo llegar: Ruta del Agua, apartadero acondicionado con paneles interpretativos en la pista de tierra batida. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41050','mirador','Mirador de la Termas Romanas','7.6/10 Perspectiva arqueológica e histórica sobre las ruinas de las termas de las Vegas, rodeadas de mosaicos de olivar compacto. Cómo llegar: Pasarela sobreelevada del conjunto arqueológico e interpretativo protegido de la localidad. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41051','mirador','Mirador del río Guadiamar','7.1/10 Suave horizonte de cultivos de secano de la campiña aljarafeña occidental que miran hacia los sotos del corredor verde. Cómo llegar: Camino rural sobreelevado contiguo a los antiguos depósitos de agua municipales. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41902','mirador','Mirador de la Isla de los Pájaros','8.9/10 Espectacular e infinita retícula horizontal de los arrozales de las marismas del Guadalquivir, repletos de flamencos y avifauna. Cómo llegar: Canal de la Muga, pasarela de madera ecológica en pleno linde del Parque Natural de Doñana. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41052','mirador','Observatorio de la Laguna del Gobierno','8.2/10 Complejo endorreico de la campiña que ofrece un mirador ornitológico excepcional sobre carrizales y ánades reales. Cómo llegar: Caseta de madera sobre pilotes integrada en el itinerario natural restaurado de la laguna. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41053','mirador','Mirador de la Giraldilla (Castillo)','8.5/10 Vista aérea perfecta del casco urbano histórico, los campos de viñedos del Condado y las inmensas marismas bajas. Cómo llegar: Restos consolidados de la fortaleza medieval que corona el peñón urbano de calles encaladas. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41054','mirador','Mirador de la Sierra de Lora','7.8/10 Vista de las colinas olivareras del centro de la comarca este, encajonadas por afloramientos de piedra caliza gris. Cómo llegar: Senda del calvario alto, pista forestal que corona la colina periférica del municipio. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41055','mirador','Mirador de la Ermita de Setefilla','8.4/10 Impresionante e histórica atalaya rocosa sobre la vega del Guadalquivir, plantaciones citrícolas y dehesas norteñas. Cómo llegar: Explanada de piedra sillar del santuario medieval edificado en el espolón de la sierra de Setefilla. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41056','mirador','Mirador de los Baños Romanos de la Monclova','7.4/10 Paisaje llano agrícola característico del asentamiento colonial ilustrado de Carlos III con cultivos extensivos modernos. Cómo llegar: Entorno arqueológico de los baños de agua medicinal, accesos peatonales de tierra compactada. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41057','mirador','Mirador del Berrocal','8.3/10 Vista salvaje y serrana de dehesas de alcornoques y jarales que se tiñen de rojo por la cercanía de la cuenca minera. Cómo llegar: Carretera autonómica A-476, apartadero señalizado con muros de piedra rústica. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41058','mirador','Mirador del Castillo de Luna','8.2/10 Panorámica sobre la comarca de Los Alcores, las ricas tierras de la campiña baja y los fosos de la fortaleza gótica. Cómo llegar: Balcón exterior del recinto amurallado rehabilitado por el arqueólogo Jorge Bonsor. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41059','mirador','Mirador del Parque Central','7.3/10 Vista de la cornisa aljarafeña sobre el cinturón periurbano metropolitano y el skyline de la ciudad de Sevilla. Cómo llegar: Pasarelas superiores del parque público de la localidad, barandillas sobre el desnivel. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41061','mirador','Mirador de los Humosos','7.2/10 Perspectiva horizontal agrícola de las huertas colectivas de regadío intensivo asociadas al valle bajo del Genil. Cómo llegar: Camino rural de servicio contiguo a las balsas de almacenamiento de agua locales. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41060','mirador','Mirador del Arco de la Rosa','8.5/10 Bella e histórica estampa de la campiña sevillana desde las murallas del palacio ducal y sus olivares de verdeo. Cómo llegar: Plaza alta de la Iglesia de Santa María de la Mota, paseo perimetral fortificado. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41063','mirador','Mirador de la Torre del Homenaje','7.6/10 Perspectiva sobre la campiña meridional baja, dehesas matorrales y campos de girasol que arropan la fortificación medieval restaurada. Cómo llegar: Almenas superiores del castillo, accesible por escalera de caracol de la fortaleza. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41064','mirador','Mirador de la Pancorbo (Sierra de San Pablo)','9.1/10 Espectacular e imponente cresta caliza con un denso pinar carrasco que domina la campiña y las ruinas de las fortalezas de Cote. Cómo llegar: Pista de montaña de la Sierra de San Pablo, apartadero con paneles informativos. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41065','mirador','Mirador del Castillo de Morón','8.8/10 Vista aérea perfecta del entramado blanco de la villa de la cal, olivares compactos y los murallones calizos de Sierra de Esparteros. Cómo llegar: Torre del homenaje del complejo fortificado islámico alto, paseo de ronda. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41066','mirador','Mirador de la Ermita de la Virgen de la Belén','8.7/10 Hermosa estampa de dehesas ganaderas de encinas centenarias y olivares serranos en el corazón de Sierra Morena oriental. Cómo llegar: Explanada exterior del santuario, pista forestal que arranca del linde norte urbano. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41067','mirador','Mirador del Palacio del CondeDuque','8.0/10 Vista aérea sobre la campiña del Aljarafe septentrional, los campos de trigo y el histórico trazado barroco de la colegiata. Cómo llegar: Balcón superior de la plaza monumental del Ayuntamiento de Olivares. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41068','mirador','Mirador de la Colegiata','9.4/10 Inmensa, monumental y fotogénica panorámica de la villa ducal y la llanura cerealista desde el cerro de la insigne Colegiata. Cómo llegar: Explanada de piedra sillar del conjunto monumental, junto al monasterio de la Encarnación. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41070','mirador','Mirador de los Baños Árabes','7.1/10 Vista baja periférica sobre el curso fluvial del río Guadalquivir flanqueado por dehesas bajas y huertas del Aljarafe. Cómo llegar: Recinto ajardinado arqueológico municipal, rústicos senderos peatonales de tierra. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41071','mirador','Mirador de la Iglesia de San Eutropio','7.5/10 Suave oleaje de tierras arcillosas con un mosaico de olivos tradicionales y girasoles de la campiña de Marchena. Cómo llegar: Campanario de ladrillo visto y azulejos transitables del templo barroco local. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41072','mirador','Mirador de las Canteras de Pedrera','8.0/10 Paisaje geológico singular de frentes de extracción de piedra caliza blanca rodeado de matorral y campos de olivar. Cómo llegar: Parque de la cantera vieja, sendero local balizado desde el sur de la localidad. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41073','mirador','Mirador de la Azuaga (Sierra Morena)','8.6/10 Vista de dehesas ganaderas compactas de encinas y grandes bolos graníticos característicos del paisaje norteño. Cómo llegar: Carretera autonómica A-432, km 15, apartadero acondicionado con murete de piedra rústica. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41074','mirador','Mirador del Castillo de Almenara','8.2/10 Atalaya sobre el río Guadalquivir y las ruinas de Celti, límite fronterizo con los olivares tradicionales cordobeses. Cómo llegar: Cresta del cerro testigo de la antigua fortificación medieval, pista agraria. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41076','mirador','Mirador del Castillo de Hierro','93/10 Imponente peñón calizo exento coronado por la fortaleza medieval de frontera que vigila el punto más alto provincial. Cómo llegar: Torre del homenaje restaurada a 650 metros, escaleras con cadenas integradas en la roca viva. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41077','mirador','Mirador del Embalse de la Puebla','7.8/10 Vista directa de las aguas del río Corbones integradas en el relieve ondulado olivarero de la campiña este. Cómo llegar: Corona de la presa de derivación, acceso señalizado por carretera local rústica. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41078','mirador','Mirador del Embalse de José Torán','8.7/10 Inmensa lámina de agua encajada entre pinares y encinares vírgenes de Sierra Morena, con huertas bajas de naranjos. Cómo llegar: Mirador de las Palomas, pista forestal de montaña asfaltada que bordea la presa. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41079','mirador','Mirador del Caño Guadiamar (Dehesa de Abajo)','9.4/10 Espectacular e infinita retícula horizontal de acequias, marismas y arrozales colmados de cigüeñas y colonias de flamencos de Doñana. Cómo llegar: Centro de visitantes de la Dehesa de Abajo, pasarela de madera sobre pilotes. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41080','mirador','Mirador del Castillo del Real','8.5/10 Fortaleza gótica de piedra que vigila de forma impecable el valle de la riera de Cala y dehesas extremeñas. Cómo llegar: Paseo de ronda amurallado del castillo medieval, accesible por rampa empedrada de la loma. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41081','mirador','Mirador de las Riberas del Majuelo','7.2/10 Paisaje plano puramente agrícola de la vega del Guadalquivir con cultivos hortícolas, choperas e industrias periurbanas. Cómo llegar: Parque de las Riberas del Majuelo, paseo peatonal acondicionado junto al cauce. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41083','mirador','Mirador del Embalse de la Minilla','8.6/10 Hermosa perspectiva de la lámina de agua rodeada de pinos piñoneros y dehesas quebradas en la antigua Ruta de la Plata. Cómo llegar: Área recreativa de la Minilla, valla rústica con paneles interpretativos forestales. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41084','mirador','Mirador del río Blanco','7.3/10 Suave horizonte cerealista de la campiña de Osuna cruzado por los sotos tradicionales y huertas del río Blanco. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41085','mirador','Mirador del Chorrillo','7.6/10 Escarpe natural del Aljarafe norte con vistas hacia el arroyo de canillas, olivares tradicionales y llanuras cerealistas. Cómo llegar: Paseo del Chorrillo, barandilla de hierro urbana sobre el talud natural del pueblo. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41086','mirador','Mirador del Monumento del Sagrado Corazón','8.3/10 Histórica y cenital visual de la cornisa sobre la cuenca del Guadalquivir, los puentes de hierro y Sevilla capital. Cómo llegar: Plaza alta del santuario del Sagrado Corazón, accesible por ascensor urbano o escaleras. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41088','mirador','Mirador de las Cascadas del Huéznar / Cerro del Hierro','9.2/10 Espectacular paraje de agua limpia, cascadas de toba calcárea y el imponente laberinto kárstico minero del Cerro del Hierro. Cómo llegar: Vía Verde de la Sierra Norte, pasarelas de madera frente a los saltos Monumento Natural. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41087','mirador','Mirador de las Murallas de la de San Pedro','8.4/10 Vista sobre el encajonamiento fluvial del río Guadiamar desde los restos consolidados del recinto amurallado almohade. Cómo llegar: Entorno mudéjar de la iglesia vieja de San Pedro en el espolón occidental urbano. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41089','mirador','Mirador de los Gradas del Teatro (Itálica)','9.0/10 Vista aérea del Anfiteatro e Itálica romana unida a la vega del Guadalquivir desde las ruinas imperiales de la ladera. Cómo llegar: Graderío superior porticado del anfiteatro romano del conjunto arqueológico protegido. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','mirador','Mirador de las Setas de Sevilla (Metropol Parasol)','9.6/10 Insuperable visual de la Giralda gótica, campanarios barrocos, el curso del Guadalquivir y los tejados de la ciudad vieja. Cómo llegar: Pasarela aérea transitable de madera fenólica de la plaza de la Encarnación, ascensor panorámico. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41092','mirador','Mirador de la Vereda del río','7.1/10 Perspectiva horizontal agrícola de las huertas citrícolas de la Vega asociadas al paso del ferrocarril de mercaderías. Cómo llegar: Paseo perimetral fluvial del Guadalquivir, junto al anejo de Los Rosales. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41093','mirador','Mirador del Parque Zaudín','8.2/10 Vista de la cornisa aljarafeña sobre el cinturón periurbano, olivares viejos integrados y lagunas con aves acuáticas. Cómo llegar: Torres de madera de observación del parque metropolitano del Zaudín, paseos de tierra. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41094','mirador','Mirador de los Jardines del Arzobispo','7.6/10 Vista del palacio arzobital barroco integrado en las extensas fincas agrícolas de aceituna gordal tradicionales. Cómo llegar: Paseo perimetral del conjunto histórico porticado del municipio central aljarafeño. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41095','mirador','Mirador del Torreón del Castillo de Utrera','8.6/10 Vista de pájaro sobre el entramado histórico medieval, los templos góticos mudéjares y campiñas cerealistas y ganaderas bajas. Cómo llegar: Almenas consolidadas de la torre de la fortaleza medieval alta, plaza del Castillo. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41096','mirador','Mirador del Dolmen de La Pastora','8.2/10 Valor histórico y místico único sobre los megalitos de la Edad del Cobre y la cornisa norte aljarafeña. Cómo llegar: Centro de interpretación arqueológico, sendero perimetral sobre el corredor de la tumba prehistórica. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41097','mirador','Mirador de la Raya Real','8.8/10 Histórico e impresionante camino de arena flanqueado por pinares piñoneros y sabinas salvajes, ruta del Rocío de Doñana. Cómo llegar: Pista forestal arenosa de la Raya Real, acceso regulado desde el palacio de Orleans. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41100','mirador','Mirador del Cañón del río Corbones','8.1/10 Vista del desfiladero profundo fluvial esculpido por el río entre olivares de montaña y matorral mediterráneo. Cómo llegar: Senda del puente de los seis ojos, camino rural de montaña al sur de la localidad. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41098','mirador','Mirador de las Bodegas tradicionales','7.4/10 Suave horizonte vitivinícola del Aljarafe occidental con plantaciones de cepas dedicadas al vino de naranja tradicional. Cómo llegar: Calle alta de la población junto a los lagares históricos de mampostería. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41099','mirador','Mirador de las Minas de la Reunión / Munigua','8.8/10 Espectacular combinación del imponente santuario romano de Mulva Munigua sobre la colina y lagos de antiguas canteras mineras. Cómo llegar: Senda peatonal de herradura de Munigua o plataforma arqueológica de las minas de carbón viejas. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41101','mirador','Mirador de las Calderas','7.8/10 Pozas de agua limpia naturales excavadas en el cauce rocoso del río Siete Arroyos bajo los pinos de Sierra Morena baja. Cómo llegar: Paraje natural de las Calderas, pasarela de madera peatonal de la ribera. 📍 Provincia: Sevilla.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41102','mirador','Mirador del Calvario (Los Alcores)','8.4/10 Espectacular balcón natural sobre la inmensa llanura de la Vega de los Alcores con huertas e hileras de frutales. Cómo llegar: Parque público de la colina del Calvario, barandilla de hierro urbana sobre el escarpe. ¡Misión cumplida! Con el municipio del Viso del Alcor cerrado con total rigor, la provincia de Sevilla queda oficialmente completada al 100% de su mapa territorial. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22003','mirador','Mirador de la Peña de Arias Montano','9.6/10 Mística y abrumadora atalaya caliza con vistas cenitales del pueblo blanco, frondosos bosques de castaños y encinas de la Sierra de Aracena. Cómo llegar: Explanada de la Ermita de Nuestra Señora de los Ángeles, en lo alto del monumento natural. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90456','mirador','Mirador de las Marismas del Odiel','7.8/10 Observatorio del laberinto acuático de canales, salinas y fangos costeros protegidos con avistamiento masivo de espátulas y flamencos. Cómo llegar: Pasarela peatonal de madera en el paraje fluvial cercano a la desembocadura. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22001','mirador','Mirador de la Mezquita (Cerro del Castillo)','9.5/10 Espectacular e histórica panorámica de la mezquita del siglo X integrada en la fortaleza, dominando valles de dehesas salvajes. Cómo llegar: Patio de armas exterior del recinto amurallado que corona el cerro del pueblo. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22002','mirador','Mirador de las Marismas de El Rocío','9.7/10 Legendaria postal de la mística aldea frente a la inmensa llanura de inundación de Doñana repleta de caballos y aves migratorias. Cómo llegar: Paseo Marismeño, barandilla de madera en el linde de la marisma frente a la ermita. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90457','mirador','Mirador de la Cuna del Fandango','7.4/10 Suave perspectiva del Andévalo minero y olivarero, ligada a la identidad musical del municipio y sus dehesas bajas. Cómo llegar: Parque elevado del Calvario, barandilla urbana en el sector occidental alto. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','mirador','Mirador del Castillo de Aracena','9.4/10 Imponente visual de la iglesia gótico-mudéjar, la fortaleza templaria y el espeso manto verde de la sierra de castaños. Cómo llegar: Almenas consolidadas del recinto fortificado que corona la colina sobre la Gruta de las Maravillas. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22005','mirador','Mirador de las Murallas del Castillo','9.0/10 Vista aérea del entramado urbano blanco fortificado, el valle del río Chanza y las ruinas imperiales de Turóbriga. Cómo llegar: Paseo de ronda medieval de la fortaleza andalusí que alberga la plaza de toros tradicional. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22006','mirador','Mirador del Parador / Desembocadura del Guadiana','92/10 Inmensa e impresionante postal costera internacional contemplando el curso bajo del río Guadiana, el puente internacional y Portugal. Cómo llegar: Explanada exterior del Parador de Turismo, en lo alto del cerro que domina el estuario. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90744','mirador','Mirador de la Cuesta del Clarín','7.5/10 Perspectiva de lomas olivareras y viñedos bajos que anuncian la campiña onubense, con cortijos agrarios tradicionales dispersos. Cómo llegar: Pista de servicio agrícola acondicionada cercana al recinto del Belén Viviente histórico. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90459','mirador','Mirador de la Estación de Berrocal (Río Tinto)','8.8/10 Impresionante e inhóspito paisaje marciano teñido de óxido rojo por las aguas ácidas del río Tinto entre densos jarales. Cómo llegar: Sendero de la Vía Verde del río Tinto, junto al antiguo puente de hierro ferroviario británico. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90460','mirador','Mirador de los Pagos de Viñedos','7.7/10 Horizonte llano vitivinícola cubierto de cepas de uva zalema de la D.O. Condado de Huelva bajo la luz atlántica. Cómo llegar: Ruta del vino del Condado, mirador rústico acondicionado junto a las cooperativas locales. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90461','mirador','Mirador de las Cruces de Mayo','7.3/10 Vista urbana y agrícola periférica ligada al entorno forestal de pinares piñoneros piñoneros y cultivos hortícolas del llano. Cómo llegar: Calle de la Ermita alta, pequeña plataforma peatonal con barandilla protectora. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90462','mirador','Mirador de la Sierra del Buho','7.9/10 Vista del relieve accidentado andevaleño dominado por pinares de repoblación, eucaliptos e infraestructuras eólicas modernas. Cómo llegar: Camino forestal de tierra compactada que corona la colina del antiguo molino de viento. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90463','mirador','Mirador del Castillo de Cala','8.5/10 Fortaleza gótica de piedra caliza que vigila las dehesas ganaderas fronterizas y las antiguas explotaciones de mineral de hierro. Cómo llegar: Muros perimetrales consolidados de la fortaleza medieval alta, accesible por rampa empedrada. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90464','mirador','Mirador del Morante','8.3/10 Soberbia visual del Andévalo minero, las dehesas del río Odiel y las antiguas infraestructuras ferroviarias inglesas. Cómo llegar: Cima del Cabezo de El Morante, pista de tierra desde la carretera A-496. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90465','mirador','Mirador de la Era de la Dehesa','8.4/10 Vista de dehesas ganaderas de encinas centenarias que se funden con los pinos piñoneros de la antesala serrana. Cómo llegar: Entorno acondicionado de la antigua era empedrada, en el sector norte de la villa. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90466','mirador','Mirador de La Laguna','8.9/10 Singular y fotogénico paisaje de agua limpia donde una inmensa balsa de riego árabe preside el centro del pueblo blanco. Cómo llegar: Paseo perimetral de la plaza de La Laguna, barandilla sobre las huertas tradicionales bajas. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21021','mirador','Mirador de la Flecha de El Rompido','9.1/10 Espectacular estampa litoral de la lengua de arena virgen que separa el río Piedras del océano Atlántico abierto. Cómo llegar: Paseo de la barriada marinera alta de El Rompido, carretera costera de las playas. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21022','mirador','Mirador del Monumento de la Sierra','9.3/10 Hermosa e impenetrable alfombra verde boscosa del municipio más alto de la sierra, rodeado de castaños gigantes y robles. Cómo llegar: Senda de montaña del alto del Chorrito, accesible a pie desde la iglesia inacabada. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21023','mirador','Mirador de la Ermita de San Benito','8.0/10 Atalaya mística andevaleña ligada a la romería más antigua de la provincia, rodeada de jarales y encinas. Cómo llegar: Explanada de piedra del santuario en lo alto del cerro de San Benito, camino rural. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21030','mirador','Mirador de los Olivares de Alcalá','7.1/10 Horizonte agrícola plano característico de la campiña baja onubense, con viñedos y cultivos extensivos modernos. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21024','mirador','Mirador del Valle de la fuente','8.8/10 Vista de dehesas ganaderas ibéricas de encinas y huertas tradicionales asociadas a los barrancos que vierten en Aracena. Cómo llegar: Camino forestal empedrado de la ruta de los molinos de agua tradicionales. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21025','mirador','Mirador del Castillo de Cortegana','94/10 Inmensa, monumental e histórica panorámica de la fortaleza medieval del siglo XIII dominando el entramado urbano blanco y dehesas. Cómo llegar: Paseo de ronda y almenas del recinto fortificado que corona el peñón de la villa. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21026','mirador','Mirador de la Corona de Cortelazor','8.9/10 Vista aérea idílica de los olivares de montaña abancalados, castañares y los profundos valles del arroyo de Guijarra. Cómo llegar: Plaza del mirador urbano alto, barandilla de madera en el extremo norte del casco antiguo. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21029','mirador','Mirador del Castillo de Sancho el Fuerte','9.2/10 Impresionante fortaleza de frontera señorial construida en 1293 con vistas completas de las dehesas ibéricas del norte. Cómo llegar: Muralla exterior transitable del castillo, accesible por rampa empedrada desde el centro urbano. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21027','mirador','Mirador del Municipio Menor','7.6/10 Perspectiva rural e íntima del pueblo más pequeño de Andalucía, rodeado de muros tradicionales de piedra y encinas viejas. Cómo llegar: Camino agrícola elevado que circunvala las pocas calles del casco urbano de piedra. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21028','mirador','Mirador de las Almenas de la Muralla','8.5/10 Vista de la campiña serrana y campos cerealistas tradicionales desde el recinto fortificado artillero medieval. Cómo llegar: Lienzo norte de la muralla histórica alta, en pleno núcleo de calles encaladas. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21031','mirador','Mirador del Castillo de San Juan (La Contienda)','9.0/10 Confín noroccidental absoluto de Huelva, balcón de frontera sobre las dehesas portuguesas del Alentejo y el río Múrtigas. Cómo llegar: Fuerte de San Juan, baluarte defensivo de la guerra de restauración de la colina. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21032','mirador','Mirador del Tejada la Vieja','7.2/10 Horizonte arqueológico sobre la llanura cerealista de la campiña baja, vinculada al antiguo poblamiento tartésico y minero. Cómo llegar: Loma del yacimiento arqueológico de Tejada, accesible por pistas agrarias desde el norte. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21033','mirador','Mirador de la Plaza del Coso (Fuente de los Doce Caños)','93/10 Idílica postal rural donde brota el río Múrtigas, rodeado por un frondoso bosque de castaños, lianas y huertas serranas. Cómo llegar: Entorno empedrado de la histórica fuente monumental en el centro de la villa. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21034','mirador','Mirador de la Ermita de Santa Brígida','9.2/10 Vista aérea del Valle de la Algaba con su espeso manto de chopos y frutales tradicionales que contrastan con los encinares. Cómo llegar: Cerro de Santa Brígida, sendero empinado rodeado de pinos piñoneros al norte del pueblo. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21035','mirador','Mirador de las Almenas del Castillo','7.8/10 Vista del cauce bajo del río Odiel, sotos de ribera y los primeros esteros salinos que anuncian la costa onubense. Cómo llegar: Ruinas consolidadas de la antigua fortaleza medieval que vigila el flanco fluvial urbano. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21037','mirador','Mirador del Puerto de la Laja','8.4/10 Impresionante perspectiva sobre el río Guadiana navegable, las antiguas estructuras de carga de mineral británicas y Portugal. Cómo llegar: Poblado minero abandonado del Puerto de la Laja, pasarela fluvial acondicionada. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21038','mirador','Mirador del Charco Malo','8.7/10 Recóndito y fotogénico barranco rocoso con cascadas de agua limpia y pozas escondidas bajo encinares y alcornocales densos. Cómo llegar: Senda de montaña escarpada de la ruta del agua que parte de la zona alta residencial. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21039','mirador','Mirador del Valle del río Tortillo','8.8/10 Vista de dehesas ganaderas ibéricas aisladas y muros tradicionales de piedra seca que tejen los pastizales del confín norte. Cómo llegar: Pista agrícola transitable de la Umbría, barandilla rústica de madera sobre el talud. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21041','mirador','Mirador del Conquero','8.9/10 Espectacular e histórica vista urbana y costera sobre las Marismas del Odiel, cabezos arcillosos locales y muelles mineros. Cómo llegar: Paseo de los Cabezos del Conquero, balaustrada urbana junto al Santuario de la Cinta. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21042','mirador','Mirador de las Salinas de las Marismas de Isla Cristina','9.1/10 Mar de canales salinos de color rosa con molinos de marea históricos tradicionales y avistamiento de aves acuáticas litorales. Cómo llegar: Sendero de madera del ecoturismo de las marismas, acceso desde la carretera costera de las playas. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21043','mirador','Mirador del Tiro Pichón','8.8/10 Vista aérea de la capital del jamón ibérico, rodeada de espesas dehesas de encinas y secaderos tradicionales de ladrillo. Cómo llegar: Terraza exterior del edificio regionalista de Aníbal González, flanco norte elevado de la población. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21044','mirador','Mirador de la Antilla','9.0/10 Inmensa llanura de arena dorada costera y dunas atlánticas que se estiran hacia las playas vírgenes de Nueva Umbría. Cómo llegar: Paseo marítimo alto de La Antilla, plataforma peatonal con escaleras de madera. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21045','mirador','Mirador de las Llanás','9.1/10 Idílica postal del pueblo blanco escondido en el valle con sus empedrados tradicionales de adoquines ("llanas") de piedra blanca. Cómo llegar: Senda de montaña que asciende hacia Aracena, balcón natural en las faldas de la colina. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21046','mirador','Mirador del Bosque de El Estero','7.4/10 Suave paisaje de pinares piñoneros piñoneros y arenales costeros que abrigan los extensos cultivos de fresas tradicionales del llano. Cómo llegar: Pista forestal compactada que bordea la riera estacional del arroyo de la Rocina. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21047','mirador','Mirador del Campo de Manzanilla','7.2/10 Horizonte agrícola plano de la campiña vinícola y olivarera baja con cortijos andaluces señoriales dispersos. Cómo llegar: Camino rural sobreelevado junto a las antiguas bodegas de vino zalema locales. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21048','mirador','Mirador del Valle de los Marines','8.6/10 Manto compacto verde de olivos de montaña y castaños centenarios que tapiza el accidentado relieve central serrano. Cómo llegar: Pista agrícola elevada del cementerio rústico, barandilla de madera sobre el desnivel. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21049','mirador','Mirador de Corta Atalaya','9.7/10 Impresionante, abrumador y colosal cráter minero escalonado a cielo abierto (el mayor de Europa) con lavas de colores ocres. Cómo llegar: Plataforma con paneles del Parque Minero de Riotinto, acceso restringido guiado desde el museo. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21050','mirador','Mirador del Convento de Santa Clara','8.8/10 Vista aérea del entramado histórico y marinero vinculado a Platero y a los viajes colombinos sobre la vega del Tinto. Cómo llegar: Terraza superior del complejo monástico mudéjar de piedra y ladrillo, centro de la villa. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21051','mirador','Mirador de la Ermita de las Virtudes','8.5/10 Vista de la vega fluvial del río Múrtigas con huertas tradicionales escalonadas bajo dehesas ganaderas serranas. Cómo llegar: Explanada de piedra del santuario del siglo XIII edificado en la falda caliza de la colina. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21052','mirador','Mirador de Peña de Hierro','8.6/10 Impresionante mina a cielo abierto que desvela el nacimiento de aguas de color rojo intenso del río Tinto entre pinos. Cómo llegar: Centro de interpretación minero de Peña de Hierro, pasarelas sobre el gran tajo geológico. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21053','mirador','Mirador de las Murallas de Niebla','9.3/10 Inmensa e histórica postal sobre el río Tinto encajado bajo el mayor recinto amurallado almohade rojo de España. Cómo llegar: Paseo de ronda fortificado de la muralla medieval alta junto al Castillo de los Guzmanes. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21054','mirador','Mirador del Embalse del Corumbel Bajo','8.1/10 Vista directa de las aguas integradas en la campiña vinícola tradicional, rodeadas de lomas bajas de monte mediterráneo. Cómo llegar: Corona de la presa de derivación, acceso señalizado por carretera local rústica. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21055','mirador','Mirador del Monasterio de La Rábida','9.4/10 Histórica panorámica sobre la confluencia de los ríos Tinto y Odiel, muelles de las Carabelas y dehesas costeras bajas. Cómo llegar: Paseo perimetral y jardines elevados del cenobio franciscano mudéjar tradicional. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21056','mirador','Mirador del Alpizar','7.8/10 Transición perfecta entre las ricas lomas agrarias de la campiña y los primeros relieves de jarales de Sierra Morena. Cómo llegar: Camino de herradura del calvario alto, pista forestal que corona la colina municipal. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21057','mirador','Mirador del Castillo de Paymogo','7.9/10 Fortaleza defensiva de frontera (guerra de restauración) sobre las dehesas de encinas y el río Chanza ibérico. Cómo llegar: Baluarte perimetral del castillo fortificado, accesible desde el casco antiguo empedrado. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21058','mirador','Mirador de la Peña de la Virgen de la Peña','8.4/10 Espectacular e inmensa atalaya andevaleña caliza sobre dehesas de encinas, matorrales y minas de manganeso viejas. Cómo llegar: Explanada de piedra del santuario serrano, carretera local de subida desde el norte. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21061','mirador','Mirador de las Haciendas Vinícolas','7.5/10 Suave oleaje de cepas de vid dedicadas a caldos tradicionales blancos bajo la luz de la campiña onubense. Cómo llegar: Ruta del vino del Condado, apartadero rural junto a los lagares de mampostería. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21062','mirador','Mirador de la riera del Chanza','8.2/10 Confín noroccidental absoluto de Huelva sobre las dehesas ganaderas portuguesas vecinas y campos de cultivo llanos. Cómo llegar: Camino agrícola elevado junto a los antiguos hitos fronterizos internacionales. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21063','mirador','Mirador de la Torre de San Bartolomé','7.6/10 Vista de la llanura andevaleña con la silueta exenta de la torre defensiva medieval cilíndrica de mampostería rústica. Cómo llegar: Parque público de la Torre, paseo peatonal acondicionado en lo alto de la colina. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21064','mirador','Mirador de las Riberas del Tinto','7.5/10 Perspectiva de los antiguos muelles ferroviarios y de madera sobre el cauce de inundación fluvial del río Tinto bajo. Cómo llegar: Paseo fluvial del embarcadero, sendero peatonal acondicionado del municipio. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21066','mirador','Mirador del Molino de la Junta','7.7/10 Vista de dehesas ganaderas bajas y jara presidida por el antiguo ingenio harinero tradicional de piedra restaurado. Cómo llegar: Colina exenta del molino, pista agrícola batida accesible desde la circunvalación norte. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21065','mirador','Mirador del Castillo de San Marcos','9.5/10 Insuperable, mística y bella postal de la fortaleza sobre el río Guadiana divisando Portugal y la tirolina internacional. Cómo llegar: Almenas consolidadas del castillo señorial alto, carretera local pavimentada de montaña. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21067','mirador','Mirador de los Bosques de los Hornos','8.9/10 Espectacular paisaje de montaña calizo con los hayedos y castañares de la ruta de los hornos de cal tradicionales. Cómo llegar: Sendero local botánico señalizado que arranca de las afueras residenciales. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21068','mirador','Mirador de los Dólmenes de la Zarcita','7.8/10 Paisaje prehistórico llano andevaleño con megalitos rodeados de pinos de repoblación, dehesas secas y ganadería. Cómo llegar: Yacimiento arqueológico acondicionado en la loma agrícola del término. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21069','mirador','Mirador del Castillo de Santa Olalla','9.1/10 Impresionante e histórica atalaya sobre la Ruta de la Plata, la fortaleza del siglo XIII, encinares y dehesas ganaderas. Cómo llegar: Muros exteriores transitables de la fortaleza señorial que corona el peñón de la villa. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21070','mirador','Mirador del Dolmen de Soto','8.6/10 Enorme valor místico e histórico sobre uno de los mayores monumentos megalíticos europeos integrado en la campiña baja. Cómo llegar: Centro de visitantes del Dolmen de Soto, sendero perimetral sobre el corredor prehistórico vallado. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21071','mirador','Mirador del Barrio Alto','92/10 Espectacular e idílica estampa de la villa de la pizarra colgada en el abismo, rodeada por densos castañares serranos. Cómo llegar: Plaza alta del Barrio Alto, inicio de los senderos del Parque Natural de Aracena. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21072','mirador','Mirador de las Oficinas de los Ingleses','83/10 Arquitectura industrial británica ferroviaria del siglo XIX integrada perfectamente en las dehesas y pinares del Andévalo este. Cómo llegar: Complejo histórico consolidado de los talleres ingleses, paseo urbano de la localidad. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21073','mirador','Mirador de los Molinos de Viento','7.7/10 Vista de la llanura agrícola costera citrícola presidida por ingenios tradicionales de molienda y cultivos hortícolas planos. Cómo llegar: Camino rural de la duna, pequeña plataforma peatonal con barandilla protectora. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21074','mirador','Mirador del Castillo de la Iglesia Parroquial','8.2/10 Vista desde las murallas fortificadas almohades del templo románico mudéjar dominando los viñedos del Condado bajo. Cómo llegar: Balcón fortificado urbano de la calle Adarve, acondicionado con bancos y rejería. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21075','mirador','Mirador del río Oraque','7.6/10 Suave oleaje de pizarras y dehesas andevaleñas cortadas por los sotos tradicionales y meandros del río Oraque. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21076','mirador','Mirador del Alto de los Molinos','8.3/10 Vista de dehesas ganaderas bajas y jara presidida por los antiguos ingenios harineros tradicionales de piedra restaurados. Cómo llegar: Parque de los Molinos, paseo peatonal acondicionado en lo alto de la colina que domina el puebloblanco. 📍 Provincia: Huelva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16001','mirador','Mirador de la Plaza de San Jorge','9.3/10 Soberbia visual de la campiña gaditana alta y los frondosos alcornocales del Parque Natural de los Alcornocales envolviendo la silueta del castillo. Cómo llegar: Explanada de la iglesia mayor barroca, en la cota más elevada del espolón rocoso. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90467','mirador','Mirador de la Virgen del Valle','8.6/10 Vista aérea del pueblo blanco encajonado en el valle, olivares tradicionales andaluces y los campos de cultivo de espárragos. Cómo llegar: Carretera de montaña CA-9107, ensanche habilitado con murete de piedra rústica. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90468','mirador','Mirador del Tajo de Algar','8.5/10 Vista limpia de la Sierra de Grazalema occidental, la lámina de agua del embalse de Guadalcacín y montes de encinas densas. Cómo llegar: Borde del tajo calizo junto a la plaza de toros, barandilla de hierro urbana. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16002','mirador','Mirador de Punta Carnero','9.4/10 Impresionante e histórica panorámica del Estrecho de Gibraltar, la costa de Marruecos y el paso marítimo internacional de barcos. Cómo llegar: Carretera de Punta Carnero, plataforma costera al pie del faro en los acantilados marinos. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16003','mirador','Mirador de la Sierra de Líjar','9.3/10 Espectacular rampa natural de despegue de vuelo libre con vistas de pájaro de la Sierra de Cádiz y olivares de montaña. Cómo llegar: Cima de la pista forestal asfaltada que corona la cordillera caliza calcaria alta. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16004','mirador','Mirador de la Peña (Plaza del Cabildo)','9.8/10 Abrumador y vertiginoso abismo vertical calizo de 100 metros con los meandros del Guadalete y huertas tradicionales abajo. Cómo llegar: Plaza del Cabildo, balconada protegida en el linde del castillo y la basílica barroca. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90031','mirador','Mirador de la Torre del Tajo','9.6/10 Colosal acantilado de corte vertical de 100 metros sobre el océano Atlántico presidido por una histórica atalaya rodeada de pinos piñoneros. Cómo llegar: Sendero forestal de la Torre del Tajo en el Parque Natural de La Breña. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16016','mirador','Mirador del Embalse de Charco Redondo','8.9/10 Vista limpia de la gran presa encajada entre canutos fluviales protegidos y la vegetación salvaje de los Alcornocales. Cómo llegar: Apartadero señalizado con paneles del parque forestal en la carretera nacional N-381. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90469','mirador','Mirador del Cintillo y de la Calzada Romana','9.4/10 Impresionante e imponente perspectiva caliza kárstica sobre el valle de Ubrique, la sendas empedradas romanas e hileras de encinas. Cómo llegar: Área recreativa del Cintillo, sendero local balizado en las faldas de la sierra. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90470','mirador','Mirador del Palacio de los Ribera','8.7/10 Vista señorial de la gran lámina de agua del embalse de Bornos y huertas desde los jardines platerescos renacentistas. Cómo llegar: Logia superior del palacio renacentista fortificado del siglo XVI. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','mirador','Mirador de la Torre Tavira','9.5/10 Insuperable y monumental visual de 360 grados sobre los tejados coloniales, los miradores tradicionales de comerciantes, la catedral barroca y el mar. Cómo llegar: Azotea de la torre vigía de Tavira en el centro histórico, acceso mediante escaleras a la cámara oscura. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16006','mirador','Mirador del Castillo de Castellar (Villa Vieja)','9.6/10 Espectacular e histórica atalaya medieval amurallada sobre el embalse de Guadarranque, el Peñón de Gibraltar y el mar mediterráneo. Cómo llegar: Almenas superiores del alcázar defensivo dentro del pueblo fortaleza medieval intacto. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16007','mirador','Mirador de la Ermita de Santa Ana','8.8/10 Vista aérea idílica de las marismas salinas, el castillo isleño de Sancti Petri y las playas doradas atlánticas del sur. Cómo llegar: Explanada de la ermita octogonal barroca en lo alto del cerro exento de la población. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90032','mirador','Mirador del Faro de Chipiona','9.1/10 Vista cenital desde el faro más alto de España sobre los históricos corrales de pesca tradicionales de marea y dunas. Cómo llegar: Balconada superior de la linterna del faro, acceso peatonal por escalera de caracol de piedra. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16008','mirador','Mirador de las Calas de Roche','9.0/10 Sucesión salvaje de acantilados arcillosos de color rojizo que cobijan pequeñas calas vírgenes bajo densos pinares marítimos. Cómo llegar: Sendero costero peatonal del GR-92, junto a la pasarela de madera de la Cala del Aceite. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90738','mirador','Mirador del Castillo de Fatetar','8.3/10 Vista panorámica de la campiña baja, campos cerealistas ondulados y las ruinas ibero-romanas de Carissa Aurelia. Cómo llegar: Muralla del patio de armas de la fortaleza islámica del siglo X que corona el cerro. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90737','mirador','Mirador del Tajo de Algarín / Balcón de los Pueblos Blancos','9.2/10 Espectacular e inmenso balcón natural sobre la lámina de agua de la presa de Zahara y el laberinto serrano. Cómo llegar: Cima del peñón de Algarín a 1.068 metros, accesible por sendero de montaña exigente. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11019','mirador','Mirador del Puerto de las Palomas','9.8/10 Insuperable visual alpina del Parque Natural de Grazalema con el Pinsapar, la Garganta Verde y el embalse abajo. Cómo llegar: Altura máxima de la carretera CA-9104 a 1.357 metros, apartadero acondicionado con paneles de piedra. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','mirador','Mirador de la Torre del Homenaje del Alcázar','9.1/10 Vista aérea monumental de los tejados históricos, bodegas tradicionales, la catedral barroca y los mares de viñas albarizas. Cómo llegar: Terraza superior de la torre defensiva almohade dentro del conjunto monumental fortificado. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11021','mirador','Mirador del Castillo de Jimena','9.3/10 Dominio absoluto sobre el estrecho valle del río Hozgarganta, los canutos fluviales protegidos de Los Alcornocales y Gibraltar. Cómo llegar: Torre albarrana del complejo amurallado romano-árabe en lo alto del cerro de San Cristóbal. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11022','mirador','Mirador de la Playa de Santa Bárbara','8.9/10 Vista única en primer plano de la imponente cara norte del Peñón de Gibraltar, las playas atlánticas y fortificaciones históricas. Cómo llegar: Paseo marítimo de levante, plataforma peatonal junto a los restos de los búnkeres de línea. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','mirador','Mirador del Cerro del Castillo (Techo de la Campiña)','9.5/10 Excepcional atalaya de 360 grados de toda la provincia gaditana, desde la bahía y Cádiz hasta las estribaciones de Grazalema. Cómo llegar: Cima del cerro del Castillo a 330 metros, entre las ruinas romanas, árabes y medievales. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11024','mirador','Mirador del Sagrado Corazón / Castillo','9.6/10 Impresionante e icónica estampa del pueblo blanco escalonado coronado por la iglesia neoclásica y el esbelto castillo rocoso. Cómo llegar: Plaza de la Iglesia o almenas de la fortaleza medieval del siglo XII sobre el risco calizo. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11025','mirador','Mirador de la Cuna del Cante por Peteneras','7.6/10 Suave relieve de cerros arcillosos dedicados a la ganadería brava y cultivos cerealistas tradicionales de secano de la campiña. Cómo llegar: Parque público elevado de la Libertad, barandilla de madera en el flanco norte urbano. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11026','mirador','Mirador del Yacimiento de Iptuci','8.4/10 Entorno rural olivarero que cobija las históricas salinas de interior romanas y murallas de la antigua ciudad fortificada. Cómo llegar: Loma del cabezo de Hortales, sendero local arqueológico señalizado a las afueras. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11027','mirador','Mirador de la Torre de la Iglesia Mayor Prioral','8.8/10 Panorámica fluvial de la desembocadura del río Guadalete, el parque de las Canteras y las marismas salinas bajas. Cómo llegar: Cuerpo alto transitable de la torre gótica mudéjar, plaza de España. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11028','mirador','Mirador del Parque Natural de las Canteras','8.3/10 Paisaje forestal de pinos piñoneros y antiguos frentes de extracción de piedra ostionera que sirvieron para la catedral gaditana. Cómo llegar: Sendero adaptado del interior de la cantera vieja, pasarelas de madera. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11029','mirador','Mirador de la Estación de la Vía Verde de la Sierra','8.5/10 Vista baja del cauce del río Guadalete encajonado por sotos de ribera, punto de inicio de la histórica vía cicloturística. Cómo llegar: Kilómetro 0 de la Vía Verde de la Sierra, antiguo hangar ferroviario acondicionado. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11030','mirador','Mirador de los Corrales de Rota','8.7/10 Monumento natural marino con parcelas artificiales de piedra caliza de marea de origen romano dedicadas a la pesca tradicional. Cómo llegar: Pasarela de madera ecológica del cordón dunar litoral de la playa de la Almadraba. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11031','mirador','Mirador del Castillo de San Romualdo','8.8/10 Vista histórica de la llanura de caños salinos de la Bahía de Cádiz, fortificaciones históricas de mampostería y el Real Instituto y Observatorio de la Armada [8.9]. Cómo llegar: Adosado a los muros consolidados del ribazo fortificado de la antigua aduana medieval. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11902','mirador','Mirador del Castillo de Gigonza','8.3/10 Vista limpia de la campiña baja, lomas de encinar y campos de girasol que arropan la fortificación medieval remodelada. Cómo llegar: Pista de acceso perimetral de la finca del complejo señorial tradicional. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11033','mirador','Mirador del Pinar del Rey','9.2/10 Impresionante e inmenso pulmón verde boscoso con vistas a la bahía de Algeciras, el Peñón de Gibraltar y alcornocales densos. Cómo llegar: Sendero botánico peatonal de la loma alta, área recreativa acondicionada de la sierra. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11032','mirador','Mirador de las Covachas / Barrio Alto','9.6/10 Espectacular e histórica panorámica sobre la desembocadura del Guadalquivir, el coto de Doñana, bodegas tradicionales y los pinares marineros bajos. Cómo llegar: Balconada de la plaza de la Paz, en el borde oriental elevado del núcleo histórico de la villa. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11034','mirador','Mirador de la Iglesia de Nuestra Señora de la Encarnación / Lizón','9.5/10 Vista de pájaro absoluta del singular entramado urbano con las espectaculares calles de casas excavadas bajo rocas gigantes calizas. Cómo llegar: Plaza alta de la fortaleza medieval, junto al torreón del homenaje y el tajo fluvial del río Guadalporcún. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11035','mirador','Mirador de El Estrecho','9.9/10 Mítica, abrumadora e insuperable atalaya continental con vistas directas al continente africano, el monte Musa en Marruecos y el oleaje. Cómo llegar: Kilómetro 91 de la carretera nacional N-340, amplio aparcamiento acondicionado con muretes y paneles geográficos. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11036','mirador','Mirador del Castillo de la Torre','8.4/10 Atalaya defensiva andalusí que domina el laberinto montañoso de la Sierra de Cádiz y valles de olivos tradicionales. Cómo llegar: Muralla exterior transitable de la fortaleza medieval alta, accesible por rampa empedrada desde el centro. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11037','mirador','Mirador de los Esteros (Caserío de la Algaida)','8.7/10 Espectacular e infinita retícula horizontal de las marismas bajas del Guadalquivir con puestas de sol de renombre fotográfico cinematográfico. Cómo llegar: Camino rural consolidado que discurre en paralelo a las lagunas someras de Doñana norte. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11038','mirador','Mirador de la Ermita del Calvario','9.4/10 Vertiginosa visual del casco urbano de la piel encajonado en un cañón kárstico calizo vertical bajo la Sierra de Grazalema. Cómo llegar: Explanada de la ermita alta, sendero empedrado balizado desde el casco histórico de la villa. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','mirador','Mirador de la Cobijada / Muralla','9.7/10 Insuperable, mística y bella postal de la villa blanca fortificada sobre el peñón, los molinos de viento tradicionales y el mar. Cómo llegar: Paseo de las murallas medievales, balconada colgada sobre el acantilado urbano histórico. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11040','mirador','Mirador del Puerto de las Viñas','9.3/10 Paisaje kárstico de alta montaña en el municipio más alto de la provincia con simas, pastizales rústicos y encinas. Cómo llegar: Carretera de montaña A-2302 que comunica con Grazalema, apartadero con paneles interpretativos ganaderos. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11041','mirador','Mirador del Castillo de Matrera','8.1/10 Vista de dehesas ganaderas bajas y olivares tradicionales desde los restos de la polémica torre fortificada medieval consolidada. Cómo llegar: Cerro testigo de Matrera, accesible por pistas agrícolas de tierra batida desde el sur. 📍 Provincia: Cádiz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90739','mirador','Mirador del Castillo de Zahara','9.8/10 Impresionante e icónica estampa del peñón fortificado, el pueblo blanco andaluz, el pinsapar y el inmenso embalse turquesa. Cómo llegar: Almenas superiores de la fortaleza medieval de la cumbre, sendero empinado de piedra caliza integrado en el risco. ¡Hito cartográfico monumental completado! Con el municipio de Zahara de la Sierra registrado de forma rigurosa, la provincia de Cádiz y toda la franja occidental andaluz quedan cerradas al 100%. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90471','mirador','Mirador del encajonamiento del río Gargáligas','7.1/10 Perspectiva llana sobre las vegas del regadío, dehesas bajas dispersas y el soto de ribera del río Gargáligas. Cómo llegar: Camino rural elevado cercano a las balsas de regulación del canal de Orellana. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90472','mirador','Mirador de las Lomas de Tierra de Barros','7.4/10 Suave oleaje de tierras arcillosas rojizas compactas dominadas por cultivos de viñedos tradicionales, olivares e hileras de ajos. Cómo llegar: Punto culminante junto al depósito de agua municipal, al sur del núcleo urbano. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90473','mirador','Mirador del Camino de la Ermita','7.3/10 Vista horizontal de la penillanura de la Campiña Sur, salpicada de encinas y campos cerealistas tradicionales de secano. Cómo llegar: Camino rústico que asciende hacia los antiguos cercados ganaderos perimetrales. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90474','mirador','Mirador del Castillo de Alange','9.3/10 Impresionante e histórica atalaya caliza sobre el inmenso embalse de Alange, las termas romanas y la llanura extremeña central. Cómo llegar: Almenas superiores de la fortaleza medieval del siglo XIII, sendero empedrado escarpado desde el pueblo blanco. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06001','mirador','Mirador del Castillo de Luna','9.5/10 Majestuosa e imponente postal de una fortaleza rocosa con vistas colosales de las infinitas dehesas de la Sierra de San Pedro. Cómo llegar: Torre del homenaje del recinto fortificado medieval, accesible por cuestas empedradas del barrio gótico. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06002','mirador','Mirador del Castillo de Miraflores','9.1/10 Fortaleza templaria encaramada en un cerro testigo que vigila el llanón fronterizo de dehesas del río Táliga. Cómo llegar: Paseo de ronda amurallado del castillo, accesible por rampa empedrada de la colina. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90475','mirador','Mirador de las Canteras de Mármol','7.8/10 Singular paisaje geológico minero con frentes de extracción de caliza y mármol rodeado por olivares tradicionales serranos. Cómo llegar: Parque de la cantera vieja, sendero local balizado desde el sur de la localidad. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90476','mirador','Mirador de la Vía de la Plata (Parque de Cornalvo)','8.4/10 Histórica panorámica de alcornocales dehesados y encinas integradas en el linde del Parque Natural de Cornalvo y calzadas romanas. Cómo llegar: Itinerario del sendero de gran recorrido, apartadero de madera en la pista forestal alta. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06004','mirador','Mirador de las Bodegas y Viñedos de Barros','8.2/10 Vista de la capital de la Tierra de Barros sobre un inmenso mar horizontal de viñedos y olivos alineados geométricamente. Cómo llegar: Terrazas superiores de las cooperativas vitivinícolas de la circunvalación agraria. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90477','mirador','Mirador de la Sierra de San Serván','8.6/10 Espectacular muralla caliza exenta que domina las ricas Vegas Bajas del Guadalquivir e hileras de frutales de regadío. Cómo llegar: Pista forestal transitable que corona el puerto de las antenas, barandilla sobre el desnivel. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06005','mirador','Mirador del Castillo de Miramontes','8.7/10 Vista sobre la penillanura de la Campiña Sur y dehesas ganaderas compactas desde los restos consolidados de la fortaleza gótica. Cómo llegar: Recinto amurallado alto del castillo de Azuaga, mirador urbano acondicionado con rejería. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06006','mirador','Mirador de la Torre de Espantaperros (Alcazaba de Badajoz)','9.2/10 Insuperable y majestuosa panorámica del río Guadiana, los puentes históricos, los baluartes y el casco amurallado islámico. Cómo llegar: Paseo de ronda amurallado de la mayor alcazaba de Europa, en lo alto del cerro de la Muela. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90838','mirador','Mirador del Ahitones (Sierra del Suroeste)','8.9/10 Espectacular e impenetrable alfombra verde boscosa de encinas centenarias y alcornocales dedicados a la montanera del cerdo ibérico. Cómo llegar: Carretera autonómica EX-313, apartadero acondicionado con murete de piedra rústica. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90478','mirador','Mirador del Cerro del Morro','8.4/10 Vista agreste del extremo oriental de La Siberia, pinares densos y el imponente relieve quebrado del valle del río Zújar. Cómo llegar: Pista forestal con rampa empinada hacia el puesto de vigilancia contiguo a la Ermita del Fuego. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90479','mirador','Mirador del Castillo de Benquerencia','9.1/10 Impresionante e histórica atalaya caliza sobre la inmensa llanura esteparia de La Serena, salpicada de canchales e hileras de olivos rústicos. Cómo llegar: Murallas de la fortaleza medieval del siglo XIII, sendero empedrado escarpado desde el barrio del Castillo. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90480','mirador','Mirador de las Cuatro de la Campiña','8.3/10 Suave horizonte de cultivos de secano cerealistas de la Campiña Sur que enlazan con el parque de las dehesas centenarias. Cómo llegar: Explanada perimetral del parque periurbano de Las Quinientas, caminos de tierra compactada. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90481','mirador','Mirador de la Ermita de los Milagros','7.5/10 Vista limpia de la planicie agraria baja, olivares tradicionales andaluces y los extensos campos de cultivo de cereal de secano. Cómo llegar: Atrio exterior vallado del santuario rural, accesible por paseo pavimentado desde el norte. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90482','mirador','Mirador de las Eras del Convento','8.5/10 Fotogénica e idílica estampa de la Sierra del Suroeste con dehesas de alcornoques viejos dedicadas a la montanera del cerdo ibérico. Cómo llegar: Paraje alto acondicionado de las eras de piedra, accesible por caminos rurales consolidados. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90483','mirador','Mirador de las Almenas del Castillo Templario','9.5/10 Insuperable, majestuosa e inmensa panorámica del conjunto medieval fortificado, su torre del homenaje, la villa blanca y dehesas infinitas. Cómo llegar: Paseo de ronda fortificado de la alcazaba musulmana y templaria que corona la cima de la colina. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06007','mirador','Mirador de la Ermita de la Belén (Sierra de Tiros)','9.2/10 Imponente muralla caliza vertical que domina las aguas de los embalses lejanos, el llano estepario de La Serena y dehesas bajas. Cómo llegar: Explanada de piedra sillar del santuario templario, carretera escénica de montaña BA-033. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90484','mirador','Mirador del Puerto de la Bonita (Tentudía)','8.9/10 Hermosa perspectiva a 1.000 metros de la alta montaña extremeña meridional, con castañares tupidos y encinares de ladera. Cómo llegar: Kilómetro 8 de la carretera paisajística de montaña BA-039, balcón natural colgado sobre el abismo. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06025','mirador','Mirador del Cerro de la Cruz','7.1/10 Vista llana periurbana de las Vegas Bajas del Guadiana, parcelas agrícolas tradicionales de regadío e industrias del área de Mérida. Cómo llegar: Prolongación de la calle Calvario, barandilla sobre el talud natural del depósito de agua alto. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06026','mirador','Mirador del Monasterio de Tentudía (Techo Provincial)','9.8/10 Mística, colosal e insuperable atalaya mudéjar a 1.104 metros de altura con visuales completas de Extremadura y las sierras andaluzas. Cómo llegar: Atrio exterior de la iglesia fortaleza de la Orden de Santiago, cima del Monasterio de Tentudía. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06027','mirador','Mirador de la Vía de la Plata','7.6/10 Perspectiva horizontal cerealista de la Tierra de Barros con olivares jóvenes e infraestructuras de transporte del corredor. Cómo llegar: Camino rural de servicio contiguo al enlace de la autovía nacional A-66. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06028','mirador','Mirador del Embalse de Orellana (Paredón)','8.4/10 Vista directa de las aguas turquesas del río Zújar encajonadas entre relieves de cuarcita gris con avifauna protegida. Cómo llegar: Corona de la presa de derivación, acceso señalizado por la carretera local BA-035. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06029','mirador','Mirador del Cementerio de los Italianos','7.9/10 Enorme valor histórico y místico vinculado a la Guerra Civil en un entorno de dehesas ganaderas y encinas viejas. Cómo llegar: Parque de la Memoria exterior, sendero local balizado desde el linde norte de la población. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06030','mirador','Mirador del Castillo de Capilla','9.4/10 Espectacular e imponente fortaleza medieval sobre el escarpe rocoso dominando las aguas azules del embalse de La Serena. Cómo llegar: Torre del homenaje del complejo amurallado islámico alto, acceso empedrado desde el casco antiguo. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06031','mirador','Mirador de la Rivera de Aljucén','7.8/10 Vista de dehesas de alcornoques y jarales que marcan el confín norte provincial con el paso del tren de alta velocidad. Cómo llegar: Camino forestal de tierra batida que arranca desde el linde norte de las vías. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06032','mirador','Mirador del Camino Romano','7.0/10 Paisaje llano agrícola de campos de secano y olivares tradicionales asociados a la ruta jacobea de la Plata. Cómo llegar: Margen de la pista rural consolidada que conecta el término con Aljucén. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06033','mirador','Mirador de la dehesa del embalse','8.8/10 Amplia visual de la lámina de agua de la presa de Orellana encajada entre encinares densos de la comarca de la Siberia. Cómo llegar: Pista agrícola sobreelevada que comunica el núcleo con los puestos de pesca recreativos. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06034','mirador','Mirador de Regina Turdilorum','9.3/10 Espectacular e histórica vista aérea sobre el teatro romano y la antigua urbe imperial bajo la alcazaba de Reina. Cómo llegar: Pasarela del complejo arqueológico protegido o balcón de la fortificación del cerro contiguo. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06035','mirador','Mirador del Templo de San Cristóbal','9.1/10 Atalaya sobre el encajonamiento fluvial de los ríos Guadiana y Guadalupejo, con los relieves de la Siberia extremeña. Cómo llegar: Cima del cerro de San Cristóbal, explanada de piedra del santuario mudéjar alto. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06036','mirador','Mirador del Museo del Turrón / La Serena','8.7/10 Vista horizontal del inmenso pastizal estepario cuna del queso de la Serena, con olivares tradicionales escalonados. Cómo llegar: Plataforma con paneles interpretativos en la zona alta de los depósitos de la población. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06008','mirador','Mirador de la Playa de Cheles (Alqueva)','8.9/10 Inmensa e impresionante postal costera de interior sobre el gran embalse transfronterizo de Alqueva lindando con Portugal. Cómo llegar: Paseo de la playa fluvial, rampas de madera ecológica en pleno linde con el cauce del Guadiana. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06043','mirador','Mirador de las Riberas del Guadiana','8.2/10 Vista del cauce medio del río Guadiana cruzado por sotos de ribera tupidos y dehesas bajas ganaderas de encinas. Cómo llegar: Paseo fluvial del embarcadero, sendero peatonal acondicionado del municipio. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06009','mirador','Mirador de la Ermita de las Cruces','8.5/10 Panorámica rural de las ricas vegas hortícolas del regadío con el cerro testigo calizo de la ermita emergiendo solitario. Cómo llegar: Explanada de piedra del santuario, carretera local escénica de la Sierra de la Ortiga. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06045','mirador','Mirador del llano de los Entrines','7.1/10 Perspectiva horizontal de cultivos de viñedos tradicionales y olivares bajos que marcan la campiña de Barros occidental. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06047','mirador','Mirador del Cerro de la Fuente','8.1/10 Suave oleaje de pizarras y dehesas de la Serena cortadas por los sotos tradicionales y huertas rústicas. Cómo llegar: Pista agrícola transitable de la colina que corona el puebloblanco. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06048','mirador','Mirador del Cerro Masatrigo (La Siberia)','9.5/10 Impresionante, abrumador y colosal cono rocoso perfecto exento (la "rotonda más bonita de España") rodeado por las aguas de la presa. Cómo llegar: Carretera EX-322, senderos pedestres circulares y mirador de madera en la cumbre del cerro Masatrigo. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06049','mirador','Mirador del Castillo de Feria','9.6/10 Imponente e icónica silueta de la fortaleza señorial con su torre del homenaje cuadrangular dominando la Tierra de Barros de forma absoluta. Cómo llegar: Almenas consolidadas de la fortaleza medieval del siglo XV, rampa empedrada desde la villa alta. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06010','mirador','Mirador del Castillo Templario (Plaza de Toros)','9.2/10 Espectacular e histórica atalaya medieval amurallada que alberga en su patio de armas la plaza de toros tradicional y el mercado. Cómo llegar: Paseo de ronda de la fortaleza templaria, en el centro histórico de la villa blanca. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06051','mirador','Mirador de las Bardenas de la Miel','8.8/10 Vista de dehesas ganaderas compactas de encinas y colmenares tradicionales en el Parque de la Siberia extremeña. Cómo llegar: Senda de montaña de la ruta apícola, pista forestal que corona la colina periférica. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06011','mirador','Mirador de la Casa de Zurbarán','7.8/10 Valor pictórico y geográfico sobre los llanos cerealistas de secano tradicionales que inspiraron los fondos barrocos del pintor. Cómo llegar: Hito exterior del centro de interpretación del pintor en el casco histórico de la población. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06053','mirador','Mirador de la Mina La Jayona / Santuario del Ara','9.4/10 Impresionante e inhóspito paisaje kárstico minero de grandes cortes en la roca con helechos gigantes y la "capilla sixtina extremeña". Cómo llegar: Monumento Natural Mina de la Jayona, pasarelas de madera en los frentes de los niveles mineros. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06054','mirador','Mirador de las Murallas de la de San Pedro','8.1/10 Vista desde los restos consolidados del recinto amurallado mudéjar dominando las plantaciones de olivar de Barros. Cómo llegar: Balcón fortificado urbano de la calle Adarve, acondicionado con bancos y rejería. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06055','mirador','Mirador del Monumento Natural Cuevas de Fuentes','92/10 Espectacular complejo kárstico de cavidades con estalactitas rodeado por dehesas de alcornoques de Tentudía. Cómo llegar: Centro de recepción de visitantes de las Cuevas, senderos peatonales exteriores de madera. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06056','mirador','Mirador de los Castro de Garbayuela','8.4/10 Entorno rural serrano con restos arqueológicos prerromanos célticos dominando el llano de la Siberia baja. Cómo llegar: Cresta del cerro testigo de la fortificación del castro, sendero local arqueológico señalizado. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06057','mirador','Mirador del río Zújar (Minas)','8.6/10 Vista del desfiladero profundo fluvial y las canteras mineras de plomo viejas que cortan las dehesas montañosas. Cómo llegar: Pista agrícola de tierra compactada en el sector norte de la pedanía alta. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06059','mirador','Mirador del Campanario de la Asunción','8.3/10 Vista aérea del singular conjunto histórico mudéjar de ladrillo y la llanura cerealista limítrofe con Córdoba. Cómo llegar: Cuerpo de campanas transitable de la majestuosa torre mudéjar del templo central. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06012','mirador','Mirador del Yacimiento del Turuñuelo','8.5/10 Inmenso valor histórico sobre el edificio tartésico mejor conservado del Mediterráneo occidental integrado en las vegas de cultivo. Cómo llegar: Pasarela del parque arqueológico protegido, accesos peatonales a las afueras residenciales. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06062','mirador','Mirador del Puerto de San Vicente (Cíjara)','9.3/10 Inmensa y abrumadora panorámica de la lámina de agua de la presa de Cíjara rodeada por los densos pinares alpinos norteños. Cómo llegar: Kilómetro 40 de la carretera nacional N-502, mirador acondicionado con muretes y paneles de piedra. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06013','mirador','Mirador del Castillo de Herrera','9.1/10 Fortaleza gótica de piedra caliza que vigila el valle del río Guadiana y dehesas de la Siberia central alta. Cómo llegar: Muros perimetrales consolidados de la fortaleza medieval de la colina, pista forestal. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06064','mirador','Mirador de las dehesas de la Serena','7.8/10 Suave oleaje de tierras arcillosas con un mosaico de olivos tradicionales y pastizales ovinos estacionales. Cómo llegar: Punto geodésico y mirador rústico accesible por el camino de la Ermita alta. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06065','mirador','Mirador del llano de la Higuera','7.4/10 Perspectiva horizontal de cultivos cerealistas tradicionales que marcan la llanura baja de la campiña. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06066','mirador','Mirador del Castillo de Vargas','8.2/10 Vista de dehesas ganaderas de la Sierra del Suroeste cruzada por las ruinas del antiguo bastión defensivo de frontera. Cómo llegar: Baluarte perimetral del castillo fortificado, accesible desde el casco antiguo empedrado. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06067','mirador','Mirador del Castro de Capote','8.9/10 Espectacular e histórico asentamiento céltico prerromano rodeado por dehesas de encinas y alcornocales en la frontera andaluza. Cómo llegar: Centro de interpretación del Castro de Capote, sendero arqueológico señalizado del cañón fluvial. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06068','mirador','Mirador de la Torre del Homenaje','7.2/10 Suave horizonte de la Tierra de Barros oriental, con olivares tradicionales y cultivos extensivos modernos del llano. Cómo llegar: Calle de la Torre baja, pequeña plataforma peatonal con barandilla protectora. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06069','mirador','Mirador de los Riscos de Hornachos','9.6/10 Abrumadora, salvaje e icónica visual de una sierra caliza kárstica vertical con el pueblo blanco de pasado morisco colgado del abismo. Cómo llegar: Senda del castillo hispanomusulmán o peñas de la Sierra de Hornachos, Zona de Especial Protección de Aves. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06014','mirador','Mirador del Torreón Sangriento (Castillo)','9.6/10 Inmensa, monumental e histórica panorámica de la villa de las torres barrocas de azulejos y dehesas desde la fortaleza templaria. Cómo llegar: Almenas de la Torre Sangrienta del recinto amurallado, parque del Castillo urbano alto. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06015','mirador','Mirador de la Torre de la Granada','9.1/10 Vista aérea del trazado renacentista de la sede de la Inquisición, la plaza porticada mudéjar y campiñas bajas. Cómo llegar: Campanario e hito transitable de la Iglesia de Nuestra Señora de la Granada, plaza mayor. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06072','mirador','Mirador del Balcón del Guadiana','8.4/10 Espectacular caída visual desde el borde del talud arcilloso del escarpe hacia las ricas huertas del regadío y el Guadiana. Cómo llegar: Paseo de la Ermita alta, mirador urbano acondicionado con barandilla de hierro sobre las Vegas Bajas. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06075','mirador','Mirador del Castillo de Magacela','9.5/10 Impresionante e icónica estampa del peñón rocoso coronado por la fortaleza defensiva medieval divisando el llano de La Serena y dólmenes. Cómo llegar: Patio de armas del castillo de la cumbre, sendero empedrado de herradura desde el casco urbano escalonado. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06076','mirador','Mirador de los Secanos de la Campiña','7.3/10 Horizonte agrícola plano característico de la comarca baja de secano con cortijos extremeños tradicionales dispersos. Cómo llegar: Camino rural sobreelevado junto a las antiguas cooperativas agrarias del pueblo. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06077','mirador','Mirador de las dehesas del Guadiato','8.4/10 Vista de dehesas ganaderas ibéricas de encinas y huertas tradicionales serranas vinculadas al nacimiento del río. Cómo llegar: Camino forestal de tierra compactada del calvario alto que corona la colina municipal. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06078','mirador','Mirador del río Guadalefra','7.8/10 Suave oleaje de pizarras y dehesas de pastizales ovinos cortadas por los sotos tradicionales del río Guadalefra. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua agrarios. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06080','mirador','Mirador del Castillo de Medellín / Teatro Romano','9.6/10 Impresionante e histórica atalaya sobre el puente barroco del Guadiana, la fortaleza del siglo XIV y el grandioso teatro romano bajo la roca. Cómo llegar: Almenas superiores del castillo de la cumbre, acceso pavimentado desde el conjunto arqueológico protegido. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06081','mirador','Mirador de la Torre de los Casos/Castillo','8.5/10 Vistas de dehesas y cultivos desde el entorno del castillo medieval, integrado en el conjunto histórico. Cómo llegar: Entorno del castillo y atalaya, accesible desde la zona alta del casco urbano. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06082','mirador','Mirador del vado del río Ortiga','7.1/10 Panorámica llana de la vega del Guadiana con sus mosaicos de cultivos hortícolas, frutales de regadío y sotos de ribera bajos. Cómo llegar: Camino agrícola de servicio contiguo a las pasarelas del río, al norte del término. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','mirador','Mirador de la Alcazaba Árabe / Puente Romano','9.7/10 Majestuosa e incomparable postal histórica que divisa el puente romano más largo de España y el río Guadiana desde la fortaleza omeya. Cómo llegar: Paseo de ronda fortificado del alcázar islámico del siglo IX, en pleno conjunto Patrimonio de la Humanidad. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06084','mirador','Mirador de la Sierra de la Moheda','8.1/10 Vista de dehesas ganaderas compactas de encinas y monte bajo que anuncian el entorno protegido del embalse de Cornalvo. Cómo llegar: Pista forestal de tierra compactada que asciende hacia los cerros del norte de la población. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06016','mirador','Mirador de Tentudía (Puerto de las Marismas)','9.0/10 Entrada natural histórica desde Andalucía con extensas dehesas de encinas dedicadas a la montanera del cerdo ibérico y pinares altos. Cómo llegar: Puerto de montaña de la carretera nacional N-630, desvío acondicionado con paneles informativos. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06086','mirador','Mirador del Castillo de Montemolín','9.1/10 Impresionante e histórica atalaya amurallada sobre el valle del río Ardila y las extensas llanuras ganaderas de la Campiña Sur. Cómo llegar: Almenas superiores de la fortaleza de la Orden de Santiago que corona el peñón de la villa blanca. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06087','mirador','Mirador de las Eras del Olivar','8.6/10 Espectacular e inmenso tapiz de millones de olivos tradicionales que tejen el relieve ondulado calizo de la Serena meridional. Cómo llegar: Paraje elevado de las antiguas eras comunales de piedra, al sur del núcleo urbano. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06017','mirador','Mirador de las Riberas del Guadiana','7.8/10 Vista baja y diáfana sobre el cauce de inundación de las Vegas Bajas del regadío, canales y plantaciones frutales. Cómo llegar: Paseo fluvial acondicionado junto a las compuertas de derivación del canal de Montijo. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06091','mirador','Mirador del Parque de Lacimurga','8.9/10 Vista sobre los meandros del Guadiana y el cerro testigo que alberga las ruinas de la mística ciudad íbero-romana. Cómo llegar: Loma del yacimiento arqueológico de Cogolludo, accesible por pistas rurales desde la EX-115. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06092','mirador','Mirador del Castillo de Nogales','8.8/10 Soberbia torre del homenaje prismática del siglo XV alzada sobre un peñón exento que domina la llanura de olivar y dehesa. Cómo llegar: Muros exteriores transitables de la fortaleza señorial alta que corona la colina del pueblo blanco. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06093','mirador','Mirador del Santuario de la Virgen de la Gracia','8.9/10 Entorno místico de encinas y alcornocales densos que vigila el pasillo fronterizo luso-extremeño y el río Ardila. Cómo llegar: Explanada de piedra del ermitorio barroco, carretera local de subida desde el suroeste. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06094','mirador','Mirador de la Sierra de la Oliva','8.3/10 Vista de los tajos de piedra caliza calcaria que abrigan el pueblo blanco, olivares tradicionales y la cuenca del río Aljucén. Cómo llegar: Senda del calvario alto, pista forestal de tierra compactada que corona la colina. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06019','mirador','Mirador de la Torre del Homenaje (Alcázar)','9.4/10 Inmensa, monumental e histórica panorámica de influencia manuelina lusa sobre los llanos del Guadiana, la raya fronteriza y Portugal. Cómo llegar: Azotea superior de la torre defensiva más alta de la frontera, accesible por rampa interior empedrada. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06096','mirador','Mirador de la Sierra de Orellana','9.0/10 Impresionante balcón kárstico rocoso sobre las aguas del embalse de Orellana, sus playas de interior con bandera azul y dehesas. Cómo llegar: Sendero local balizado hacia el punto geodésico de la sierra, norte del núcleo urbano. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06097','mirador','Mirador del Palacio de los Altamirano / Embalse','9.2/10 Espectacular stampa que combina los torreones del palacio medieval con la inmensa lámina de agua dulce rodeada de encinares. Cómo llegar: Balconada de la plaza de la Iglesia alta o zonas recreativas de la playa costera de interior. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06098','mirador','Mirador del río Palomas','7.4/10 Perspectiva horizontal cerealista de la Tierra de Barros oriental con dehesas bajas y huertas tradicionales dispersas. Cómo llegar: Camino rural sobreelevado junto a los antiguos silos agrícolas del término. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06100','mirador','Mirador del Peñón de Capilla / La Serena','9.1/10 Impresionante relieve calizo vertical que domina las aguas de la presa de la Serena y los pastizales esteparios ovinos rústicos. Cómo llegar: Senda de montaña escarpada de los abrigos rupestres, acceso desde el embalse. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06102','mirador','Mirador del Castillo de Puebla de Alcocer','9.8/10 Abrumadora, indómita e insuperable visual de 360 grados sobre los gigantescos embalses de La Serena y Orellana desde un nido de águilas fortificado. Cómo llegar: Torre del homenaje circular exenta a 700 metros, accesible por escaleras metálicas y pasarelas colgadas de la roca. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06103','mirador','Mirador de la Plaza de España','7.3/10 Paisaje llano residencial de las Vegas Bajas ligado a las ricas fincas agrícolas de regadío y huertas citrícolas. Cómo llegar: Balcón del Ayuntamiento o paseos transitables contigüos a los canales fluviales bajos. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06104','mirador','Mirador del Cerro de la Horca','7.6/10 Suaves pendientes arcillosas con un mosaico de olivos tradicionales de secano de la campiña de Barros oriental. Cómo llegar: Hito de tierra batida en la colina exenta acondicionada, camino agrario. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06107','mirador','Mirador de la Sierra de Loriana','8.5/10 Vista forestal de densos alcornocales y jarales de la Sierra de San Pedro en la loma que marca el límite provincial cacereño. Cómo llegar: Puerto de montaña de la carretera nacional N-523, apartadero señalizado con muros de mampostería. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06108','mirador','Mirador de la Ermita de Belén','7.9/10 Entorno de olivos y viñedos de Barros que arropa la singular plaza de toros tradicional rectangular anexa al santuario mudéjar. Cómo llegar: Atrio empedrado exterior de la ermita de la Virgen de la Belén, acceso pavimentado. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06109','mirador','Mirador de las Canteras de Granito','8.4/10 Singular paisaje minero de frentes de extracción de granito gris ("Gris Quintana") integrado en la inmensa penillanura esteparia. Cómo llegar: Parque público de la cantera vieja, centro de interpretación del granito a las afueras. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06110','mirador','Mirador de la Alcazaba de Reina','95/10 Espectacular e imponente recinto fortificado almohade con su ermita visigoda dominando el altiplano cerealista de la Campiña Sur. Cómo llegar: Almenas y lienzos de la muralla de la alcazaba islámica de la cumbre, acceso por pista de montaña. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06113','mirador','Mirador del Pozo de San Juan','8.0/10 Panorámica sobre el mar de viñas y olivares de la Tierra de Barros baja con cortijos tradicionales andaluces dispersos. Cómo llegar: Loma de tierra batida acondicionada junto al histórico pozo de herencia andalusí. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06114','mirador','Mirador de los Riscos de Risco','8.8/10 Espectacular e impenetrable muralla de cuarcitas verticales de la Siberia que albergan importantes colonias de aves rapaces protegidas. Cómo llegar: Balcón natural vallado en la parte alta del casco urbano de piedra, vistas hacia el embalse de la Serena. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06115','mirador','Mirador del río Alcazaba','7.6/10 Suave horizonte de dehesas ganaderas de encinas centenarias cortadas por los sotos tradicionales y huertas del río. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06116','mirador','Mirador del Monte Porrino','91/10 Incomparable y majestuoso paisaje ganadero ibérico de dehesa comunal con encinas gigantes e hitos de la montanera tradicional. Cómo llegar: Senda botánica adaptada de la finca comunal del Monte Porrino, refugios de piedra rústicos. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06117','mirador','Mirador del Castillo de Salvatierra','9.3/10 Impresionante castillo señorial de torreones circulares dominando la capital de la alfarería roja y las laderas forestales del suroeste. Cómo llegar: Balcón exterior del recinto fortificado medieval privado, cota de montaña sobre el pueblo encalado. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06119','mirador','Mirador de las dehesas del Aljucén','7.8/10 Vista de dehesas ganaderas de encinas y monte bajo mediterráneo en la antesala del Parque Natural de Cornalvo. Cómo llegar: Pista agrícola de la loma exenta, accesible desde el casco de la población. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06123','mirador','Mirador del Castillo de Piedrabuena','9.1/10 Espectacular e histórica fortaleza de la Orden de Alcántara encajada perfectamente entre inmensos alcornocales del corcho capitalinos. Cómo llegar: Lienzo norte de la muralla histórica alta de la finca señorial, carretera EX-110. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06118','mirador','Mirador del Embalse de la Serena (Peña Alta)','8.9/10 Vista aérea del gran desfiladero del río Zújar inundado por la inmensa presa con los relieves de cuarcita de la Siberia. Cómo llegar: Peñón calizo de la Peña Alta, sendero local de montaña con barandilla rústica. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06120','mirador','Mirador del canal de las Vegas Altas','7.2/10 Paisaje plano de colonización agrícola caroliniana moderna con plantaciones frutales de regadío intensivo hileradas. Cómo llegar: Pista de servicio agrícola asfaltada junto al puente de los canales de agua locales. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90839','mirador','Mirador de las Minas de Santa Marta','8.1/10 Paisaje industrial y geológico singular con los restos de castilletes de las antiguas minas de plomo y vanadio entre olivos. Cómo llegar: Complejo minero abandonado de los ingleses, sendero local interpretativo señalizado. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06122','mirador','Mirador de la Sierra de San Jorge','8.5/10 Vista aérea de la llanura vinícola de Barros que se quiebra en los riscos calizos donde se practica la escalada deportiva. Cómo llegar: Explanada de la Ermita de San Jorge, en la cresta de la colina que domina la villa. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06124','mirador','Mirador del Castillo de Segura','9.5/10 Impresionante, mística y magnífica postal de la fortaleza de la Orden de Santiago intacta con sus almenas dominando el suroeste de dehesas. Cómo llegar: Torre del homenaje del recinto fortificado medieval del siglo XIV, en pleno casco histórico alto de piedra. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06125','mirador','Mirador de las Dehesas de Siruela','8.8/10 Enorme valor e interés astroturístico (Starlight) de la Siberia norte sobre inmensos pastizales de la Mesta y encinares. Cómo llegar: Hito de la pista forestal alta de los ganaderos, accesible desde el norte del núcleo. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06126','mirador','Mirador del río Guadajira','7.5/10 Suave horizonte de viñedos tradicionales y olivares de regadío asociados a las terrazas aluviales del río Guadajira. Cómo llegar: Camino rural sobreelevado junto a los depósitos agrícolas de almacenamiento del pueblo. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06127','mirador','Mirador de la Ermita de la Virgen de la Antigua','92/10 Espectacular e imponente peñón de cuarcita gris presidiendo las aguas del embalse de Puerto Peña y los pinares densos. Cómo llegar: Explanada perimetral del santuario medieval, accesos desde la carretera nacional N-430. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06128','mirador','Mirador del Base Aérea de Talavera','7.4/10 Visual llana del corredor del Guadiana baja integrada con las pistas militares de aviación e hileras de cultivos frutales. Cómo llegar: Prolongación de las pistas agrícolas de servicio periféricas colindantes con el río Limonetes. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06020','mirador','Mirador de las dehesas de Táliga','8.4/10 Paisaje tradicional ganadero ibérico con encinas viejas y muros rústicos de piedra seca de herencia histórica templaria raya portuguesa. Cómo llegar: Senda local del arroyo de Táliga, pasarela de madera ecológica sobre el talud agrario. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06131','mirador','Mirador del Molino harinero de agua','7.8/10 Complejo etnográfico tradicional rodeado de olivares y cultivos cerealistas con antiguas acequias de mampostería hidráulicas romanas. Cómo llegar: Parque del molino restaurado a las afueras de la localidad, caminos peatonales de tierra. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06132','mirador','Mirador de las Vegas Bajas','7.1/10 Perspectiva horizontal del regadío intensivo del Guadiana con plantaciones de tomates y frutales de la cuenca baja. Cómo llegar: Camino de servicio agrícola junto a las balsas de regulación hidráulicas del término. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06133','mirador','Mirador del marquesado de la Sierra de Graja','7.6/10 Vista de la llanura caliza de Tierra de Barros vinculada a la obra literaria de la familia de Pascual Duarte. Cómo llegar: Hito de la antigua calzada romana de la Plata que bordea la sierra de la Graja, camino agrario. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06134','mirador','Mirador del Puerto de la Dehesa','8.6/10 Paso de montaña en las faldas de la Sierra del Suroeste con vistas de dehesas ganaderas compactas de encinas y castaños. Cómo llegar: Arcén habilitado en la carretera local de montaña BA-141 que conecta con Llerena. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06135','mirador','Mirador del Embalse de Cornalvo','8.5/10 Incomparable valor monumental sobre la mítica presa romana del siglo II en perfecto funcionamiento rodeada por encinares protegidos. Cómo llegar: Corona de piedra sillar de la presa del Parque Natural de Cornalvo, accesos peatonales de tierra. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06136','mirador','Mirador de la cuenca del río Bembezar','8.1/10 Vista del encajonamiento fluvial del río con olivares de montaña tradicionales y llanuras cerealistas altas de la campiña. Cómo llegar: Senda del puente de los moros, camino rural de montaña al sur del núcleo urbano. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06137','mirador','Mirador del Balcón de la central de Valdecaballeros','90/10 Paisaje industrial y natural icónico con los restos de la central nuclear inacabada emergiendo de las dehesas y el embalse de García Sola. Cómo llegar: Plataforma con paneles interpretativos de la carretera escénica BA-136, junto a los riscos calizos. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06901','mirador','Mirador de la floración de los Frutales','7.5/10 Espectacular e inmenso mar de color rosa y blanco durante la floración de los melocotoneros y ciruelos de las Vegas Bajas. Cómo llegar: Torres de madera de observación del plan de colonización agrícola, accesos peatonales entre parcelas. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06138','mirador','Mirador de la vega del río Guadianilla','7.1/10 Perspectiva horizontal agrícola de las huertas de regadío tradicionales del llano con choperas e hileras de frutales. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06139','mirador','Mirador del río Matachel','7.9/10 Vista de dehesas ganaderas de la Campiña Sur cortadas por los sotos tradicionales y meandros arcillosos del río Matachel. Cómo llegar: Pista agrícola transitable de la loma exenta que comunica con el término de Llera. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06140','mirador','Mirador del fuerte de la raya','8.4/10 Fuerte defensivo de frontera abaluartado del siglo XVII sobre el valle del río Ardila e inmensas dehesas portuguesas vecinas. Cómo llegar: Ruinas de la fortificación militar de la colina de la raya, sendero empedrado de herradura. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06141','mirador','Mirador del Castillo-Palacio de los Duques de Segorbe','8.8/10 Majestuosa e imponente fortificación gótica del siglo XV integrada perfectamente en el casco urbano blanco y olivares tradicionales de Barros. Cómo llegar: Patio de armas superior accesible del conjunto monumental fortificado señorial del municipio. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06146','mirador','Mirador de las Minas de wolframio de la Serena','8.2/10 Paisaje geológico e histórico con los restos de frentes mineros de wolframio y estaño entre dehesas y encinas rústicas. Cómo llegar: Complejo arqueológico industrial abandonado, sendero local balizado desde el casco de piedra. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06147','mirador','Mirador de la Sierra de San José','8.9/10 Idílica postal del pueblo blanco escondido en un profundo y estrecho valle montañoso con arboledas de castaños y huertas. Cómo llegar: Plaza del mirador urbano alto, barandilla de madera en el extremo norte del casco antiguo empedrado. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06148','mirador','Mirador del Templo de Santa Ana','8.5/10 Suave oleaje de cerros cubiertos de olivares compactos y encinares de la comarca de la Sierra del Suroeste. Cómo llegar: Explanada perimetral arbolada de la iglesia parroquial de las afueras, punto culminante urbano. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06142','mirador','Mirador de la ruta de los molinos de agua','8.3/10 Paisaje etnográfico fluvial del arroyo Bodión con las ruinas de piedra de los ingenios harineros tradicionales entre dehesas. Cómo llegar: Sendero local fluvial señalizado accesible desde las afueras residenciales de la villa blanca. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06143','mirador','Mirador del Dolmen de la Cardenilla','8.1/10 Enorme valor místico sobre el monumento megalítico de enterramiento colectivo rodeado de dehesas ganaderas llanas. Cómo llegar: Yacimiento arqueológico acondicionado en la loma agrícola del término, camino agrario. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06144','mirador','Mirador del llano de la campiña','7.6/10 Perspectiva horizontal de cultivos cerealistas tradicionales que marcan la llanura baja de la Campiña Sur extremeña. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06145','mirador','Mirador de los meandros del Guadiana','8.2/10 Vista del cauce del río Guadiana rompiendo las colinas calizas con sotos de ribera tupidos y huertas tradicionales. Cómo llegar: Paseo de la barriada fluvial alta, barandilla de hierro sobre el escarpe natural de la localidad. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06149','mirador','Mirador de la Ciudad de la Música / Tierra de Barros','8.6/10 ⭐ Valoración y Atractivo: 8.6/10 Inmensa panorámica sobre la llanura de Tierra de Barros, donde los viñedos alineados y olivares tradicionales de secano tapizan el relieve arcilloso. Cómo llegar: Explanada de la Ermita de San Isidro, en la zona elevada perimetral del municipio. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06150','mirador','Mirador del Castillo de Villagarcía','8.4/10 Atalaya señorial del siglo XV con vistas diáfanas a la campiña, olivares y campos de cereal que rodean la gran torre mudéjar. Cómo llegar: Entorno amurallado de la fortaleza medieval, accesible por rampa desde el casco urbano. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06151','mirador','Mirador del Embalse de Alange (Cola del Guadiana)','7.8/10 Vista limpia de las orillas del embalse y los densos sotos de ribera donde remansan las aguas fluviales antes de la presa. Cómo llegar: Pista agrícola sobreelevada cercana al club náutico y zonas ganaderas tradicionales. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06152','mirador','Mirador del Castillo de Villalba','8.7/10 Imponente fortaleza señorial con una gran torre del homenaje mudéjar dominando un mar geométrico de cepas de vid y olivares. Cómo llegar: Paseo de ronda fortificado del castillo, en la cota más alta de la villa blanca. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06022','mirador','Mirador de la Ermita de la Aurora','8.8/10 Panorámica de la fértil vega del río Guadiana, cultivos de regadío intensivos de arroz y la transición hacia la estepa. Cómo llegar: Atrio de piedra del santuario de la Aurora, situado sobre un cerro testigo periférico. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06154','mirador','Mirador del Castillo de Villanueva / Alqueva','9.2/10 Espectacular e histórica atalaya defensiva de frontera sobre las dehesas del Guadiana y las colas del embalse portugués de Alqueva. Cómo llegar: Restos de los baluartes de la fortaleza del siglo XVII, paseo perimetral en lo alto del pueblo. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06156','mirador','Mirador de la Mesa de Villar / Arte Rural','8.0/10 Vista de las llanuras agrícolas del regadío del Plan Badajoz combinada con las espectaculares esculturas urbanas de materiales reciclados. Cómo llegar: Plataforma acondicionada con barandilla rústica en el acceso norte del núcleo urbano. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06155','mirador','Mirador del Embalse de Peña del Águila','8.5/10 Vista directa de la presa encajada en la cuenca fluvial del río Zapatón entre densas dehesas de alcornoques y jarales. Cómo llegar: Corona de la presa de derivación, acceso señalizado por carretera local de montaña rústica. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06023','mirador','Mirador de la Torre del Homenaje del Palacio de los Duques de Feria','9.3/10 Insuperable visual aérea de la "Sevilla Chica", sus plazas porticadas históricas, el alcázar medieval y el cinturón de olivares. Cómo llegar: Torre del homenaje del actual Parador de Turismo, acceso peatonal por escaleras del recinto monumental. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06024','mirador','Mirador del Castillo de Zahínos (Torreón)','8.4/10 Vista de dehesas ganaderas compactas de la Sierra del Suroeste integradas de forma singular con los restos del torreón medieval urbano. Cómo llegar: Balcón fortificado junto al Ayuntamiento, cimientos de la antigua fortaleza templaria de frontera. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06160','mirador','Mirador del Dístilo Romano / Castillo','9.1/10 Monumental e histórica visual sobre el dístilo sepulcral del siglo II d.C. (único en la Península), el alcázar de Calderón y estepas. Cómo llegar: Almenas consolidadas de la fortaleza medieval o plaza porticada del conjunto monumental romano. 📍 Provincia: Badajoz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06161','mirador','Mirador de las Pinturas Rupestres de la Sierra de lares','8.9/10 Impresionante abrigo calizo con pinturas rupestres prehistóricas dominando las dehesas y las aguas azules del embalse de La Serena. Cómo llegar: Senda de montaña señalizada que asciende por los abrigos rocosos de la cresta caliza serrana. ¡Hito e hito de máxima envergadura alcanzado! Con el municipio de Zarza-Capilla finalizado de forma rigurosa de la A a la Z, la provincia de Badajoz queda oficialmente cerrada al 100% de su geografía municipal. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28062','mirador','Mirador del Mondalindo / Cuadrón','9.4/10 Inmensa e impresionante panorámica del Valle del Lozoya alto, los prados cercados de piedra y cumbres calizas de la Cabrera norte. Cómo llegar: Kilómetro 5 de la carretera escénica de montaña M-604, balcón vallado de piedra con paneles. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28063','mirador','Mirador del Embalse de Riosequillo','8.9/10 Vista de pájaro sobre el gran estanque del Lozoya rodeado de robledales umbríos, con las cumbres de Guadarrama nevadas detrás. Cómo llegar: Mirador de la plaza alta de Pinilla de Buitrago, balaustrada sobre el vaso de la presa. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28064','mirador','Mirador de las Cañadas de Gascones','8.4/10 Paisaje pastoril de la Sierra de Somosierra con regueros tradicionales de agua de deshielo y encinares de ladera. Cómo llegar: Senda de la Cañada Real Segoviana, pista forestal que arranca del linde norte urbano. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28065','mirador','Mirador del Cerro de los Ángeles (Centro Geográfico)','8.6/10 Vista aérea perfecta del área metropolitana meridional ligada a la mística atalaya del monumento y dehesas de pinos piñoneros. Cómo llegar: Explanada de piedra sillar del Sagrado Corazón de Jesús, cima del cerro testigo exento. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28069','mirador','Mirador de las Eras de la Hiruela','9.5/10 Idílica postal de montaña de la Reserva de la Biosfera de la Sierra del Rincón, rodeada de colosales dehesas de robles melojos y huertas. Cómo llegar: Conjunto etnográfico de las eras altas de trilla de grano, sendero balizado al este de la villa de piedra. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28070','mirador','Mirador de la dehesa de Aoslos','8.5/10 Vista de dehesas ganaderas serranas cubiertas de fresnos e hileras de muros de piedra seca tradicionales que tejen los prados. Cómo llegar: Pista agrícola transitable de la loma que corona la pedanía de Aoslos. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28071','mirador','Mirador de la Ermita de Nuestra Señora de los Dolores','9.1/10 Espectacular anfiteatro montañoso del valle del arroyo de la Garita con el núcleo de pizarra negra encajonado abajo. Cómo llegar: Explanada perimetral del santuario barroco mudéjar, balcón natural en las faldas norteñas. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28072','mirador','Mirador del Picazo (Sierra de Hoyo)','90/10 Alucinante y fotogénica perspectiva de un laberinto de bloques graníticos y encinas del parque regional con el skyline urbano madrileño al fondo. Cómo llegar: Senda de montaña de la ruta de los decorados de cine del oeste viejos, cima rocosa del Picazo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28084','mirador','Mirador de la Catedral de Justo Gallego','8.4/10 Abrumador valor histórico y humano ante una imponente catedral levantada por un solo hombre con materiales reciclados en la vega. Cómo llegar: Cúpula transitable o andamios superiores del complejo arquitectónico de Justo, centro urbano alto. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28114','mirador','Mirador del Búnker de Gandullas','8.5/10 Vista de dehesas ganaderas y campos de secano desde un fortín de hormigón militar intacto del Frente del Agua. Cómo llegar: Ruta fortificada del agua, sendero local balizado desde la plaza de Gandullas. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28902','mirador','Mirador de la Torre de Mirabel (Mangirón)','9.1/10 Vista directa del río Lozoya serpenteando entre los embalses y la silueta de una atalaya militar medieval exenta. Cómo llegar: Senda del GR-10, entorno arqueológico de la torre cilíndrica de piedra caliza alta. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28168','mirador','Mirador de los Atanores (El Espartal)','8.5/10 Impresionante brecha rocosa caliza excavada por el río Guadalix con encinares densos y la silueta del acueducto histórico. Cómo llegar: Sendero peatonal de montaña balizado que parte de la pedanía de El Espartal. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28171','mirador','Mirador de la Huerta de Madrid','8.3/10 Amplio vergel del valle bajo del Alberche sembrado de viñedos centenarios, campos hortícolas de regadío y densas alamedas. Cómo llegar: Balcón de la Ermita de Nuestra Señora de la Poveda, sobre el meandro fluvial. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28177','mirador','Mirador del río Guadarrama','8.1/10 Vista baja del cauce medio del río Guadarrama flanqueado por densos bosques de ribera y encinares del Parque Regional. Cómo llegar: Paseo fluvial del embarcadero viejo, sendero peatonal acondicionado del municipio. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34002','mirador','Mirador del Monte da do Castelo','9.4/10 Espectacular e histórica vista del casco medieval de Allariz, los meandros del río Arnoia y el frondoso valle boscoso gallego. Cómo llegar: Cima del cerro del antiguo castillo, accesible por escaleras y senderos de piedra desde el centro. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90507','mirador','Mirador del Pazo de Trasalba','7.8/10 Paisaje rural de suaves colinas cubiertas de robledales y viñedos tradicionales, vinculado a la figura literaria de Otero Pedrayo. Cómo llegar: Jardines elevados del pazo histórico de Trasalba, barandilla de piedra de la solana. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90508','mirador','Mirador de San Trocado','8.8/10 Impresionante panorámica sobre la confluencia de los ríos Miño y Arnoia, laderas de viñedos en terrazas de la D.O. Ribeiro. Cómo llegar: Explanada de la ermita en la cima del monte San Trocado, pista forestal de montaña. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90509','mirador','Mirador del Conjunto de Hórreos de Berducedo','9.1/10 Extraordinario paisaje etnográfico de montaña caliza con construcciones tradicionales de piedra que dominan el valle glaciar del río Avia. Cómo llegar: Paraje elevado de la pedanía de Berducedo, accesos peatonales empedrados acondicionados. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90510','mirador','Mirador de la Sierra de Larouco','8.4/10 Vista descarnada y salvaje de alta montaña gallega sobre la frontera con Portugal, pastizales alpinos y aerogeneradores modernos. Cómo llegar: Hito geodésico superior en la cresta de la sierra, pista forestal compactada. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90511','mirador','Mirador de Aquis Querquennis / Embalse de Las Conchas','9.2/10 Increíble e histórica vista del campamento militar romano inundado intermitentemente por las aguas del embalse, rodeado de robles. Cómo llegar: Centro de interpretación Aquae Querquennae, pasarelas de observación sobre la orilla fluvial. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90512','mirador','Mirador del Santuario de Los Milagros','8.1/10 Entorno de gran misticismo que domina el valle del río Medo con la imponente silueta barroca del santuario mariano. Cómo llegar: Explanada exterior elevada de piedra sillar del complejo monástico, carretera local. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90513','mirador','Mirador de Piñor','7.6/10 Vista suburbana de la periferia industrial y residencial de la capital orensana enmarcada por colinas de pinos. Cómo llegar: Calle del mirador en el barrio alto de Piñor, barandilla de hierro urbana. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90514','mirador','Mirador de Alixo','8.9/10 Inmensa visual sobre el valle del río Sil, los viñedos de la D.O. Valdeorras y las explotaciones históricas de pizarra. Cómo llegar: Pedanía de Alixo, mirador vallado con madera en el escarpe natural del pueblo. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90676','mirador','Mirador de San Roque de Beade','8.0/10 Suave oleaje de vides de la variedad treixadura plantadas en bancales tradicionales que descienden hacia el río Avia. Cómo llegar: Atrio empedrado de la ermita de San Roque, punto geográfico más alto del término. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90515','mirador','Mirador de la Ermita de San Domingos','8.5/10 Panorámica de montaña en el linde provincial con Pontevedra, rodeada de jarales, pinos y antiguos pozos mineros. Cómo llegar: Cima de la colina de San Domingos, pista agrícola transitable de tierra compactada. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90516','mirador','Mirador de la Villa de Pazos de Arenteiro','8.8/10 Hermosa estampa de una aldea noble señorial de piedra gallega encajada entre los ríos Arenteiro y Avia con hórreos. Cómo llegar: Puente medieval de piedra, sendero local fluvial acondicionado en la base rocosa. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90517','mirador','Mirador del Monte de San Trocado (Vertiente Sur)','7.9/10 Suave transición de colinas cubiertas de espesos pinares piñoneros repoblados y explotaciones agrarias dispersas. Cómo llegar: Pista de servicio forestal accesible desde el núcleo de Podentes. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90518','mirador','Mirador del Santuario de As Ermidas / Castillo','9.3/10 Impresionante e imponente desfiladero vertical del río Bibei que alberga un grandioso santuario barroco excavado en la roca viva. Cómo llegar: Balconada fortificada de la torre del castillo medieval o balcones del santuario colgado. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90520','mirador','Mirador de Couso','8.4/10 Vista aérea del valle del Avia, suaves laderas tapizadas de cepas tradicionales del Ribeiro y densos bosques de robles autóctonos. Cómo llegar: Entorno acondicionado de la Ermita de Lodairo, en la zona alta de la ladera forestal. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90521','mirador','Mirador de Pena Trevinca','9.5/10 El techo de Galicia a 2.127 metros, con panorámicas alpinas completas de circos glaciares, lagunas de alta montaña y valles de pizarra. Cómo llegar: Cumbre de Pena Trevinca, alcanzable por la red de senderos de alta montaña desde Fonte da Cova. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34007','mirador','Mirador del Parque do Carballiño / Templo de la Veracruz','8.8/10 Panorámica urbana y forestal de la villa del pulpo, presidida por la imponente e histórica silueta neogótica de Antonio Palacios. Cómo llegar: Explanada alta del Gran Balneario o paseo perimetral de la majestuosa Torre de la Veracruz. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90522','mirador','Mirador del Castro de Sande','8.2/10 Atalaya fortificada medieval y prerromana sobre un espolón de roca que domina el encajonamiento fluvial del río Arnoia. Cómo llegar: Cima del peñón rocoso donde se asienta la Torre de Sande, sendero forestal desde el pueblo. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90523','mirador','Mirador de San Lourenzo de Barral','9.1/10 Espectacular e inmensa postal fluvial sobre el ancho embalse de Castrelo, el río Miño y laderas repletas de viñedos viejos. Cómo llegar: Explanada de piedra sillar de la iglesia parroquial de Barral, balconada colgada sobre el agua. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90524','mirador','Mirador de Fontefría (Parque de Invernadeiro)','8.6/10 Paisaje indómito de montaña con profundos barrancos cubiertos de acebedos, robles y fauna salvaje protegida como el lobo. Cómo llegar: Pista de acceso regulada al Parque Natural de O Invernadeiro, cota de vigilancia forestal alta. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34003','mirador','Mirador del Castillo de Castro Caldelas','9.6/10 Insuperable, majestuosa e histórica visual sobre las tierras de Caldelas, los cañones del Sil y la villa medieval encalada. Cómo llegar: Almenas superiores de la fortaleza señorial de los Condes de Lemos, en lo alto de la colina. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34004','mirador','Mirador de la Torre del Homenaje / San Rosendo','92/10 Vista monumental del gigantesco Monasterio de San Salvador, la joya mozárabe de San Miguel y los llanos agrícolas bajos. Cómo llegar: Balconada alta junto a las ruinas del Castillo de Vilanova o azoteas del casco histórico colonial. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90525','mirador','Mirador de Razamonde','8.5/10 Suave oleaje de vides del Ribeiro ordenadas geométricamente en bancales que mueren en las aguas quietas del río Miño. Cómo llegar: Ruta del vino, mirador rústico acondicionado con paneles junto a la carretera nacional N-120. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32029','mirador','Mirador de la Sierra de Queixa','9.3/10 Impresionante e inmensa panorámica de alta montaña sobre el embalse de Chandrexa y prados ganaderos alpinos infinitos. Cómo llegar: Vértice de montaña, pista forestal que sube hacia los altos pastizales de la vertiente norte de Manzaneda. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32026','mirador','Mirador de Barra de Miño','7.8/10 Perspectiva del soto fluvial bajo del río Miño y las ricas terrazas agrícolas salpicadas de pazos señoriales tradicionales. Cómo llegar: Camino rural sobreelevado contiguo a la estación de tren, barandilla sobre el talud fluvial. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32027','mirador','Mirador del Balneario Viejo / Coto da Moura','8.6/10 Vista del encajonamiento fluvial del río Miño en la frontera con Pontevedra, arropado por pinos y aguas termales. Cómo llegar: Antiguo edificio modernista del balneario o pista forestal que corona la colina del Coto da Moura. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32028','mirador','Mirador del Castro de Cidá / Saceda','8.5/10 Enorme valor histórico y místico sobre un colosal poblado fortificado de la Edad del Hierro entre montes de jara y pinos. Cómo llegar: Pasarelas del parque arqueológico acondicionado en la loma del castro de Saceda. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32030','mirador','Mirador de Pedreiriño (Xurés)','9.4/10 Abrumador y salvaje paisaje granítico del Parque Natural Baixa Limia-Serra do Xurés con colosales bolos de piedra y valles profundos. Cómo llegar: Sendero local balizado desde la pedanía de Olelas, mirador de madera colgado sobre el abismo fronterizo. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32031','mirador','Mirador de San Pedro de Rocas','9.5/10 Mística postal del monasterio más antiguo de Galicia, excavado íntegramente dentro de roca viva granítica entre densos helechos y robledales. Cómo llegar: Entorno arqueológico de las tumbas antropomorfas talladas en la roca del campanario exento de Rocas. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32033','mirador','Mirador de O Viso','7.8/10 Vista panorámica del valle del río Arnoia, colinas cubiertas de densos pinares, matorrales y pequeñas huertas escalonadas en laderas calmas. Cómo llegar: Pista forestal que corona la cima de la colina de O Viso, cerca del hito de vigilancia. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34001','mirador','Mirador del Alto do Cañizo','8.4/10 Amplia visual del altiplano y paso de montaña de la meseta ourensana, cruzada de forma singular por las modernas vías del AVE. Cómo llegar: Apartadero de la carretera nacional N-525, punto de máxima altitud del trazado escénico. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90526','mirador','Mirador do Tellado','8.2/10 Perspectiva limpia de la Sierra de Faro, valles fluviales encajonados de la cuenca alta del Avia y pastizales rústicos de ganado. Cómo llegar: Sendero forestal que asciende hacia los aerogeneradores desde la aldea de Tellado. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32038','mirador','Mirador de As Covas','8.9/10 Impresionante e imponente tajo geológico del río Bibei esculpido en roca viva con laderas escarpadas cubiertas de viñedos viejos de Valdeorras. Cómo llegar: Pequeña plataforma de madera con barandillas junto a la carretera comarcal OU-636. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32039','mirador','Mirador de O Invernadeiro (Vertiente Laza)','9.1/10 Espectacular e indómito anfiteatro de montaña del Parque Natural, con profundos bosques autóctonos, cortados calizos y hábitat de fauna salvaje. Cómo llegar: Pista de acceso forestal de montaña desde el núcleo urbano alto hacia las cumbres de Queixa. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32040','mirador','Mirador del Monasterio de San Clodio','92/10 Solemne perspectiva del majestuoso complejo monástico medieval, cuna del Ribeiro, perfectamente integrado en la fértil cuenca del río Avia. Cómo llegar: Atrio empedrado exterior y balconada elevada de la iglesia parroquial de San Clodio. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32041','mirador','Mirador de O Viso (Xurés)','9.3/10 Colosal e imponente atalaya granítica a 850 metros con vistas de infarto de toda la comarca de la Baixa Limia. Cómo llegar: Cima del Monte do Viso, explanada rocosa junto a la antigua ermita de la Virgen del Viso. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32042','mirador','Mirador de Corga da Fecha (Xurés)','9.6/10 Impresionante vista de la mayor cascada de Galicia salvaje precipitándose entre colosales bolos de granito en el Parque Natural. Cómo llegar: Sendero de gran recorrido transfronterizo de la Vía Nova romana, pasarela metálica frente al gran salto. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32043','mirador','Mirador del Castillo de Maceda','8.6/10 Vista aérea del entramado histórico medieval, los campos agrícolas llanos de la Limia norte y la umbría de San Mamede. Cómo llegar: Almenas transitables de la fortaleza del siglo XII reconvertida en hotel, en el cerro del pueblo. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32044','mirador','Mirador de Cabeza de Manzaneda','9.4/10 Techo de la provincia a 1.778 metros con una panorámica circular de 360 grados de los valles del Sil y del Miño. Cómo llegar: Estación de montaña y esquí de Manzaneda, punto culminante superior junto a las antenas de telecomunicación. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32045','mirador','Mirador de San Tomé','7.7/10 Perspectiva de suaves colinas boscosas de robles y pinos que enmarcan pequeños viñedos tradicionales de la comarca del Carballiño. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32046','mirador','Mirador de las Pozas de Melón','9.2/10 Espectacular e idílico rosario de saltos de agua y pozas de granito natural esculpidas por el río Cerves entre densos helechos. Cómo llegar: Sendero local acondicionado con pasarelas de madera y miradores desde la autovía A-52. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32047','mirador','Mirador de la Canasta de Hórreos','8.3/10 Mayor concentración de hórreos tradicionales de España integrados de forma monumental en un prado verde de la loma comunal. Cómo llegar: Conjunto etnográfico protegido de A Merca, paseos empedrados peatonales acondicionados. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32048','mirador','Mirador de O Castelo','8.1/10 Atalaya fronteriza sobre las dehesas montañosas que delimitan las provincias de Ourense, Zamora y el territorio de Portugal. Cómo llegar: Cima del montículo de pizarras exento, accesible por caminos rurales desde el casco urbano. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32049','mirador','Mirador del Bidueiral de Montederramo','9.1/10 Impresionante santuario forestal prehistórico con un denso abedular relicto bajo los prados alpinos de la Sierra de Queixa. Cómo llegar: Senda botánica peatonal protegida que arranca desde las inmediaciones del monasterio de San Juan. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32052','mirador','Mirador de los Balcones de Madrid','9.8/10 Vistas apoteósicas de los Cañones del Sil, con paredes verticales calcáreas que caen a plomo sobre las aguas turquesas del río. Cómo llegar: Sendero forestal acondicionado desde la pedanía de Parada de Sil, pasarelas de madera al borde del abismo. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32053','mirador','Mirador de los Lagares Rupestres','8.4/10 Conjunto histórico y geográfico singular sobre el valle de Verín, viñedos de la D.O. Monterrei y lagares de piedra tallados en roca viva. Cómo llegar: Ruta de los lagares excavados en las laderas de la pedanía de Bousés. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34008','mirador','Mirador de las Termas de Outariz / Ponte do Milenio','9.2/10 Combinación perfecta del curso majestuoso del río Miño, las pozas termales al aire libre y la audaz arquitectura del puente moderno. Cómo llegar: Pasarelas peatonales de Outariz o pasadizo elevado del Puente del Milenio. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32055','mirador','Mirador del Monte de San Cibrao','7.6/10 Suaves lomas de carballos y pastizales tradicionales gallegos que miran hacia la cubeta agraria y los perfiles de Allariz. Cómo llegar: Camino rural sobreelevado junto a la ermita de San Cibrao. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32056','mirador','Mirador de O Condado','8.8/10 Impresionante balcón natural sobre el cañón del río Miño y la frontera fluvial gallego-portuguesa arropada por densos viñedos. Cómo llegar: Pista de circunvalación agrícola de herradura que domina los riscos fronterizos del sur. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32057','mirador','Mirador de Caxide / Cabezoás','9.8/10 Uno de los puntos más vertiginosos e icónicos de la Ribeira Sacra, con visuales cenitales de los meandros del Sil y viñedos heroicos. Cómo llegar: Plataforma metálica volada sobre el abismo en la carretera local OU-0508. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32058','mirador','Mirador del Embalse de Cachamuíña','8.2/10 Remanso fluvial apacible y arbolado de pinos piñoneros con un sendero perimetral ideal para la observación de aves. Cómo llegar: Paseo de madera del área recreativa de la presa de Cachamuíña. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90527','mirador','Mirador del Castillo de A Peroxa','8.7/10 Atalaya histórica excepcional sobre el valle del río Miño y el cañón del Bubal desde las ruinas fortificadas medievales. Cómo llegar: Explanada de la antigua torre del homenaje, en lo alto del espolón calizo de la población. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32060','mirador','Mirador del Embalse de Santa Eulalia','8.3/10 Vista directa de la lámina de agua encajada entre laderas de pizarra y viñedos de la D.O. Valdeorras. Cómo llegar: Malecón peatonal del paseo fluvial o carretera de subida a Carballal. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32061','mirador','Mirador de los Talleres de Piedra rústica','7.5/10 Vista rural de transición montañosa de la comarca del Carballiño, salpicada de canteras tradicionales de granito gallego. Cómo llegar: Camino agrícola elevado junto a las naves artesanales de labra de cantería. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90528','mirador','Mirador de A Cabana / Macizo de Manzaneda','9.2/10 Magnífica perspectiva de las tierras ricas de Trives, valles glaciares y castañares centenarios bajo las laderas nevadas. Cómo llegar: Mirador de A Cabana, ensanche acondicionado con murete de piedra en la carretera OU-536. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90529','mirador','Mirador de la riera del Deva','7.9/10 Paisaje forestal íntimo con arroyos limpios de montaña, pequeños viñedos de ladera y hórreos tradicionales dispersos. Cómo llegar: Senda fluvial señalizada de los molinos de agua, accesos peatonales de tierra. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90530','mirador','Mirador del Castro de San Cibrao de Las','7.8/10 Gran valor arqueológico sobre uno de los castros fortificados de la Edad del Hierro más grandes de Galicia, dominando la llanura. Cómo llegar: Cima de la colina de la "Cidade", pasarelas del centro de interpretación arqueológico. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32066','mirador','Mirador de la Sierra de Penagache','8.1/10 Vista salvaje y desértica de canchales graníticos que marcan el linde montañoso del Parque Natural del Xurés. Cómo llegar: Pista de servicio forestal que sube hacia los puestos de vigilancia del cordal fronterizo. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32067','mirador','Mirador del Carballo da Rocha','8.4/10 Monumento natural centenario de un roble colosal rodeado de prados inundables de la antigua laguna de Antela. Cómo llegar: Entorno protegido de la finca del Carballo da Rocha, senderos peatonales de madera. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','mirador','Mirador del Castillo de los Sarmiento / Barrio Judío','9.5/10 Majestuosa e histórica postal de la capital del Ribeiro con los ríos Avia y Miño uniéndose entre murallas medievales y viñedos. Cómo llegar: Paseo de ronda amurallado de la fortaleza medieval o balconada de la plaza de la Magdalena alta. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32071','mirador','Mirador de la Ruta del Castaño (A Silva)','8.5/10 Paisaje etnográfico hermoso dominado por sotos monumentales de castaños y los relieves que conducen a la meseta zamorana. Cómo llegar: Sendero forestal interpretativo de A Silva, zona de descanso con bancos rústicos de madera. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32072','mirador','Mirador del Barranco de San Roque','8.9/10 Vista aérea perfecta del entramado urbano berciano, el embalse de San Martiño y las laderas de vides de Valdeorras. Cómo llegar: Explanada de la ermita alta de San Roque, pista agrícola pavimentada desde el norte. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32074','mirador','Mirador de las Mámoas de las las de San Trocado','7.7/10 Suave transición de montes bajos de matorral con restos tumulares megalíticos prehistóricos que miran a la campiña del Carballiño. Cómo llegar: Pista agrícola transitable de tierra compactada que corona la colina exenta. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90531','mirador','Mirador del Polígono Industrial Alto','7.3/10 Vista utilitaria de la gran plataforma logística de la provincia integrada en el paisaje de suaves carballedos perimetrales. Cómo llegar: Calle de la Innovación, zona ajardinada de la loma industrial contigua a los campos rústicos. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32076','mirador','Mirador del Monasterio de Oseira','8.9/10 Solemne perspectiva del "Escorial Gallego" cisterciense medieval, arropado por un recóndito valle de densos bosques de robles. Cómo llegar: Loma alta de aproximación del camino real, sendero jacobeo de la Plata. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90532','mirador','Mirador de los Codos de Larouco','8.6/10 Impresionante e histórica calzada romana que serpentea por las laderas de pizarra de los valles del macizo central ourensano. Cómo llegar: Sendero de la Vía XVIII de Antonino, apartadero rústico con bancos de madera. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32077','mirador','Mirador de la Torre de Sandiás','8.0/10 Histórica torre medieval solitaria que corona una roca con vistas completas de la inmensa llanura desecada de la laguna de Antela. Cómo llegar: Base de la antigua torre fortificada del castillo, sendero empedrado peatonal de la colina. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32078','mirador','Mirador de las canteras de arcilla de la Limia','7.5/10 Paisaje horizontal agrícola cerealista roto por los antiguos humedales estacionales asociados a la cuenca fluvial de Limia. Cómo llegar: Camino rural de servicio contiguo a las balsas de regulación del término municipal. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32081','mirador','Mirador del Teso de San Pedro','8.1/10 Panorámica sobre el valle bajo del río Miño y las ricas terrazas donde se asientan las bodegas artesanales locales. Cómo llegar: Cerro exento del calvario alto, barandilla de hierro urbana sobre el escarpe. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32082','mirador','Mirador del llano de la Limia oriental','7.4/10 Perspectiva horizontal de pastizales ganaderos y campos agrícolas que marcan el fondo de la cubeta sedimentaria gallega. Cómo llegar: Camino rural de la duna, pequeña plataforma peatonal con barandilla protectora. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32083','mirador','Mirador Estelar de Cabeza de la dehesa (Destino Starlight)','9.6/10 Impresionante e inmensa panorámica de alta montaña con la certificación astronómica Starlight más limpia de Galicia sobre valles glaciares. Cómo llegar: Pista forestal transitable que corona los altos pastizales de Trevinca, observatorio nocturno acondicionado. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32084','mirador','Mirador del parque eólico de la Sierra del Aguillón','7.9/10 Suave oleaje montañoso con aerogeneradores modernos combinados con dehesas rústicas gallegas y robledales relictos. Cómo llegar: Pista forestal compactada que recorre el cordal eólico alto de la sierra. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32085','mirador','Mirador del Castillo de Monterrei','9.5/10 Insuperable, mística y bella postal de la mayor acrópolis fortificada gallega dominando el valle del Támega y la frontera. Cómo llegar: Patio de armas del gran castillo señorial de la cumbre, carretera local de subida desde el casco histórico. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34012','mirador','Mirador de la Torre del Homenaje del Castillo','9.2/10 Impresionante villa fortificada cercada casi en su totalidad por las aguas del embalse de Bao, rodeada de montes de pizarra. Cómo llegar: Almenas superiores de la torre medieval cilíndrica del siglo XV, en pleno núcleo de calles empedradas. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32087','mirador','Mirador del Pazo de Vilamarín','8.0/10 Vista señorial de la campiña boscosa del norte provincial, carballedos densos que arropan el pazo-castillo rehabilitado. Cómo llegar: Muralla exterior perimetral del complejo fortificado señorial del municipio. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32088','mirador','Mirador de las Cuevas del Vino (Seixo)','8.7/10 singular relieve ondulado con las chimeneas arcillosas de las bodegas tradicionales subterráneas excavadas en laderas de viñedos. Cómo llegar: Barrio de las cuevas altas de Seixo, callejuelas empedradas peatonales acondicionadas. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32089','mirador','Mirador de la Sierra de San Mamede','8.6/10 Espectacular e imponente rampa de montaña caliza que domina los valles agrícolas tradicionales y la cubeta alta de la Limia. Cómo llegar: Pista forestal transitable que asciende hacia el puesto de vigilancia y ermita de la cumbre. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32090','mirador','Mirador del Museo Etnográfico de la Limia','7.8/10 Vista rural de campos labrados y canales de drenaje rústicos asociados a la memoria histórica agrícola de la comarca. Cómo llegar: Entorno ajardinado elevado del complejo museístico rústico de la localidad. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32091','mirador','Mirador de la Fervenza da Cerveira','8.5/10 Espectacular paraje de agua limpia con un salto natural gigante encajado en la roca viva fronteriza de Portugal. Cómo llegar: Sendero peatonal acondicionado con miradores de madera del cañón del río Cerveira. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32092','mirador','Mirador de las Casariñas (Valle de Cenza)','9.4/10 Abrumadora y vertical visual de un cañón geológico colosal con un salto de agua alpino rompiendo entre murallas de pizarra. Cómo llegar: Pista de montaña asfaltada que sube hacia la presa de Cenza, balconada metálica sobre el precipicio. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34013','mirador','Mirador del canal de la Laguna de Antela','8.1/10 Perspectiva horizontal de la inmensa llanura patatera central gallega, cruzada por la red de canales e infraestructuras del tramo bajo. Cómo llegar: Mota lateral reforzada de la acequia de drenaje de la antigua laguna, caminos agrarios. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32036','mirador','Mirador de la Colegiata de Santa María','8.8/10 Vista aérea del imponente monasterio románico gótico, tramo del Camino de Santiago y valles ganaderos tradicionales de carballos. Cómo llegar: Plaza alta porticada de la colegiata medieval, en pleno núcleo de calles empedradas de piedra. 📍 Provincia: Orense (Ourense).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32037','mirador','Mirador del Monte Meda / Monasterio','8.9/10 Espectacular atalaya a 1.300 metros con vistas de infarto de toda la Ribeira Sacra meridional, dehesas y el cenobio cisterciense. Cómo llegar: Cima del Monte Meda, pista forestal de montaña asfaltada que arranca desde el linde norte urbano. ¡Éxito sin paliativos! Con el municipio de Xunqueira de Espadanedo completado, la provincia de Orense (Ourense) queda oficialmente cerrada al 100% de su geografía municipal. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36020','mirador','Mirador de los Pendellos de Agolada','8.3/10 Vista aérea del singular conjunto etnográfico de ferias del siglo XVIII medieval, rodeado de pastizales y densas carballeiras. Cómo llegar: Entorno elevado de la plaza pública del antiguo recinto de piedra de la villa. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90533','mirador','Mirador de las Pesqueiras del Miño','9.1/10 Espectacular e histórica vista del río Miño fronterizo con las monumentales construcciones de piedra romanas dedicadas a la pesca de la lamprea. Cómo llegar: Sendero local de los pescadores, pasarela de madera sobre el escarpe del río. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36002','mirador','Mirador de la Virgen de la Roca / Castillo de Monterreal','9.8/10 Insuperable, mística y bella postal de la bahía, las islas Cíes flotando en el océano, la carabela y el monumento de granito con barco. Cómo llegar: Monumento de la Virgen de la Roca, acceso por la escalera interior de caracol del brazo de la escultura. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90677','mirador','Mirador del Parque de la Naturaleza del Río Barosa','8.4/10 Espectacular cascada y rosario de molinos de agua tradicionales de piedra que escalonan la ladera granítica entre frondosos helechos. Cómo llegar: Sendero circular acondicionado con pasarelas de madera y zonas recreativas del parque fluvial. [1, 2, 3] 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36003','mirador','Mirador del Cabo Udra / Isla de Ons','9.6/10 Impresionante saliente marino de canchales graníticos con vistas directas al Parque Nacional, las rías de Pontevedra y Aldán. Cómo llegar: Complejo de interpretación del Cabo Udra, senderos pedestres costeros del GR-92. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90534','mirador','Mirador de Segade / Río Umia','8.5/10 Vista de un desfiladero profundo fluvial con una cascada salvaje, las ruinas de una antigua central hidroeléctrica y sotos tupidos. Cómo llegar: Paseo botánico de la carballeira de Caldas, sendero hacia los saltos de agua de Segade. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36004','mirador','Mirador del Monte da Pastora / San Sadurniño','9.3/10 Vista cenital de la capital del albariño con la torre fortificada isleña rota, las marismas del Umia y la ría de Arousa. Cómo llegar: Cima del Monte da Pastora, explanada rocosa junto a las ruinas de la antigua capilla. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90535','mirador','Mirador del Parque Arqueológico del Arte Rupestre','8.9/10 Enorme valor místico e histórico sobre la mayor concentración de petroglifos de la Edad del Bronce en un entorno forestal de robles. Cómo llegar: Pasarelas exteriores del centro de interpretación del arte rupestre de la loma comunal. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36005','mirador','Mirador del Cabo Home (Costa da Vela)','9.8/10 Abrumador y mundialmente famoso balcón costero sobre acantilados marinos verticales gigantes flanqueados por los faros y las Cíes. Cómo llegar: Extremo de la pista de tierra de la Costa da Vela, junto al faro esbelto rojo de Cabo Home. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90536','mirador','Mirador de las Torres de Oeste','92/10 Legendaria postal de las fortalezas gemelas románicas que defendían Compostela de los vikingos en la desembocadura del río Ulla. Cómo llegar: Paseo de madera de las marismas de Oeste, en la base de los torreones medievales. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36902','mirador','Mirador del Monte Seixo (Portalén)','8.8/10 Paisaje kárstico de montaña con un imponente monumento megalítico natural conocido como la puerta del más allá entre vientos. Cómo llegar: Pista forestal que recorre el parque eólico alto de la Sierra del Cando, cumbre rocosa. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90537','mirador','Mirador del Faro de Avión','8.6/10 Techo de la comarca del Condado a 1.155 metros con una panorámica completa de los valles del Tea y las sierras orensanas. Cómo llegar: Hito de vigilancia forestal accesible por pista de tierra de montaña desde Paraños. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90538','mirador','Mirador de la Torre de Fornelos','8.4/10 Atalaya histórica feudal que vigila la cuenca baja del río Miño y el río Ribadil, rodeada de viñedos y pinos. Cómo llegar: Ruinas consolidadas de la torre fortificada del castillo, camino de herradura del cerro. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90539','mirador','Mirador del Castrolandín','8.1/10 Vista arqueológica e interior de un poblado fortificado de la Edad del Hierro excavado sobre una colina con huertas. Cómo llegar: Pasarelas del parque arqueológico acondicionado en la loma del castro de Castrolandín. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90540','mirador','Mirador de la Iglesia del Monasterio de San Pedro de Vilanova','7.8/10 Solemne perspectiva de la iglesia románica solitaria rodeada de pastizales y robledales que marcan el Alto Deza. Cómo llegar: Atrio de piedra del santuario del siglo XII, sendero jacobeo de la Vía de la Plata norte. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36017','mirador','Mirador de la Torre de Guimarei','8.4/10 Esbelta atalaya gótica que domina las fértiles tierras agrícolas del valle del Ulla, flanqueada por extensos viñedos y carballeiras. Cómo llegar: Entorno rural consolidado de la parroquia de Guimarei, acceso por camino asfaltado local. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36018','mirador','Mirador de la Ermita de San Bieito (Candán)','9.1/10 Impresionante balcón de montaña en la Serra do Candán con panorámicas bravas de brezales, rocas graníticas y valles fluviales vírgenes. Cómo llegar: Explanada de la pequeña capilla alta, accesible por pista de servicio del parque eólico. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36019','mirador','Mirador del Embalse de Eiras','8.6/10 Vista de la gran masa de agua dulce que abastece a Vigo, encajonada en un entorno boscoso cerrado de pinos y eucaliptos. Cómo llegar: Corona de la presa e inmediaciones de la carretera PO-250 que bordea el embalse. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36021','mirador','Mirador de San Antoniño (Monte Galiñeiro)','9.0/10 Espectacular atalaya sobre las afiladas crestas de granito que vigila de forma impecable el valle de Miñor y Vigo. Cómo llegar: Sendero local escarpado que asciende hacia los abrigos rocosos del macizo del Galiñeiro. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36009','mirador','Mirador del Monte Siradella','9.7/10 Insuperable, majestuosa e icónica postal del istmo de la playa de La Lanzada, las marismas protegidas y el mar abierto de Arousa. Cómo llegar: Pasarela de madera y base del centro de interpretación en la cumbre rocosa de la colina. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36901','mirador','Mirador del Con do Forno','9.6/10 Impresionante panorámica costera de 360 grados sobre el parque natural de Carreirón, las playas vírgenes y las bateas mejilloneras. Cómo llegar: Cima del monte exento de la isla, balcón acondicionado con la imagen del Corazón de Jesús. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36024','mirador','Mirador del Pazo de Liñares','8.4/10 Vista señorial del kilómetro cero de Galicia con sus prados verdes de ganado, robledales y los jardines del palacio restaurado. Cómo llegar: Balconada de piedra sillar del complejo señorial tradicional de la comarca del Deza. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36007','mirador','Mirador de Coto Redondo (Lago Castiñeiras)','8.9/10 Vista de pájaro absoluta que abarca de forma simultánea las rías de Pontevedra, Vigo y los pinares recreativos. Cómo llegar: Torre de vigilancia forestal del Parque de Coto Redondo, carretera local escénica EP-0004. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36027','mirador','Mirador de San Benito','8.3/10 Hermosa alfombra de viñedos de albariño del Valle de Salnés bajo la intensa luz atlántica de la comarca costera. Cómo llegar: Explanada de la pequeña capilla barroca, accesible por rampa empedrada desde el centro urbano. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36028','mirador','Mirador del Monte San Tomé','8.7/10 Atalaya sobre los valles de cultivo tradicionales, la red de acequias y el Monasterio de la Armenteira forestal. Cómo llegar: Cerro exento del calvario alto, pista forestal acondicionada al norte del término municipal. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36008','mirador','Mirador de O Con (Monte Faro)','9.4/10 Espectacular e imponente balcón rocoso colgado sobre el puente de Rande, la ría de Vigo y la península del Morrazo. Cómo llegar: Pista de montaña que sube hacia las antenas, ensanche acondicionado con bancos de madera. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36030','mirador','Mirador del Castillo de Sobroso','8.8/10 Imponente postal de la fortaleza medieval del siglo XII alzándose sobre el bosque umbrío y el valle del río Tea. Cómo llegar: Muralla exterior perimetral del complejo fortificado señorial, carretera de subida pavimentada. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36031','mirador','Mirador de la Fuente de Gándara','8.5/10 Vista baja señorial de la joya arquitectónica modernista de Antonio Palacios junto a los paseos del río Tea. Cómo llegar: Recinto de los jardines del balneario histórico, paseo peatonal acondicionado. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36032','mirador','Mirador del Lameiro / Petroglifos','7.8/10 Suave horizonte de carballeiras y pastizales que arropan los históricos grabados prehistóricos de la Edad del Bronce. Cómo llegar: Entorno rural arqueológico de la pedanía de Gargantáns, caminos pedestres de tierra. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36033','mirador','Mirador de O Santiaguiño','7.6/10 Perspectiva del nudo logístico periférico y el paso del Camino de Santiago Portugués entre colinas de pinos. Cómo llegar: Entorno de la capilla de San Benito, zona alta recreativa en el cordal montañoso. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36034','mirador','Mirador de San Nomedio','8.8/10 Inmensa visual sobre el río Miño internacional fronterizo con Portugal, olivares y viñedos de condal treixadura. Cómo llegar: Cima del Monte San Nomedio, explanada del santuario mariano de las afueras. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36035','mirador','Mirador de Monteferro','9.5/10 Impresionante península de canchales graníticos con vistas directas del monumento a la marina, bahía de Baiona y las Cíes. Cómo llegar: Carretera de subida al faro, área recreativa forestal acondicionada con barandillas. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36010','mirador','Mirador del Real Monasterio de Santa María de Oia','9.6/10 Legendaria e incomparable estampa del abadía cisterciense románica rompiendo el fuerte oleaje del océano Atlántico salvaje. Cómo llegar: Margen de la carretera nacional costera PO-552, apartaderos sobre los acantilados marinos. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36037','mirador','Mirador del Monte de O Viso','8.1/10 Suave oleaje montañoso compuesto por bosques mediterráneos y prados ganaderos tradicionales que miran hacia Vigo. Cómo llegar: Pista forestal transitable de tierra compactada de la colina que corona el pueblo. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','mirador','Mirador de Samieira / Tambo','9.3/10 Espectacular caída visual desde el escarpe forestal hacia la ría de Pontevedra, los viveros y la isla de Tambo. Cómo llegar: Mirador de la Granxa, carretera costera PO-308, plataforma peatonal acondicionada. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90848','mirador','Mirador de las Pasarelas del río Verdugo','8.5/10 Vista baja de un cañón geológico fluvial de agua limpia con saltos, puentes románicos y densos robledales de ribera. Cómo llegar: Sendero peatonal acondicionado de la ruta del agua, pasarelas de madera ecológicas. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90849','mirador','Mirador del Monte de A Picaraña','8.9/10 Atalaya mística granítica con caprichosas formaciones de bolos de piedra y una cruz monumental que vigila el valle del Tea. Cómo llegar: Explanada de la ermita alta, sendero empedrado balizado desde el casco viejo de la población. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36011','mirador','Mirador de las Marismas de Alba / Alameda','92/10 Vista horizontal calmada de la red de canales salinos y el humedal recuperado con el puente de los tirantes. Cómo llegar: Pasarela de madera del itinerario ornitológico del espacio natural protegido periférico. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36039','mirador','Mirador de las Gándaras de Budiño','7.6/10 Paisaje minero e industrial singular de canteras de granito rosa integrado en humedales y lagunas bajas. Cómo llegar: Ruta de las lagunas de Budiño, pasarelas del centro de interpretación ambiental. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36040','mirador','Mirador de la Azucarera tradicional','7.8/10 Vista de la campiña baja agrícola y plantaciones de vid con la imponente chimenea de la fábrica de azúcar histórica. Cómo llegar: Calle del mirador, entorno rehabilitado de la antigua factoría de mampostería e hito. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36012','mirador','Mirador de Cedeira (El mejor banco de Redondela)','9.4/10 Inmensa, monumental e histórica panorámica de los viaductos ferroviarios decimonónicos, la ensenada de San Simón y Vigo. Cómo llegar: Alto de Cedeira, sendero local que conduce a la plataforma rocosa con el famoso banco panorámico. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36046','mirador','Mirador de las Riberas del Umia','8.0/10 Perspectiva de las huertas tradicionales y sotos de ribera del Salnés que abastecen los lagares de vino albariño. Cómo llegar: Paseo fluvial de los molinos de agua, sendero peatonal acondicionado del municipio. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36047','mirador','Mirador do Faro / Dehesas','8.1/10 Paso de montaña alto a las afueras con praderas ganaderas y los primeros relieves forestales del norte lucense. Cómo llegar: Carretera PO-533, apartadero acondicionado con muretes y paneles interpretativos de la dehesa. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36048','mirador','Mirador de los Molinos de Folón y Picón','93/10 Impresionante cascada de sesenta molinos tradicionales de piedra escalonando la ladera caliza, un monumento de ingeniería rural. Cómo llegar: Sendero circular señalizado de los molinos, pasarelas de madera con barandillas protegidas. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36049','mirador','Mirador del Parque da Gándara','7.8/10 Suave horizonte agrícola de cultivos hortícolas del regadío y pequeños viñedos condales que anuncian Tui. Cómo llegar: Paseo alto arbolado del parque público en la circunvalación del término residencial. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36050','mirador','Mirador de las Murallas del Castillo','8.6/10 Vista aérea del entramado histórico amurallado, el río Miño y el puente internacional que conecta con Monção. Cómo llegar: Recinto fortificado alto de doña Urraca, paseo perimetral en la plaza de las murallas. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','mirador','Mirador de Punta Faxilda / Silgar','9.5/10 Espectacular e icónico saliente de rocas con vistas de infarto de las playas atlánticas, la ría de Pontevedra y Ons. Cómo llegar: Paseo costero peatonal de Punta Faxilda, mirador acondicionado sobre los acantilados marinos. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36052','mirador','Mirador de la Fervenza do Toxa','9.4/10 Impresionante y colosal salto de agua de 30 metros (el más alto de Galicia) rompiendo entre murallas calizas y robledales. Cómo llegar: Sendero forestal del Deza, pasarela de madera con balcón colgado sobre el abismo fluvial. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90541','mirador','Mirador del Castillo de Soutomaior','9.5/10 Majestuosa postal de la fortaleza señorial con su doble recinto amurallado rodeado por un inmenso jardín botánico de camelias. Cómo llegar: Patio de armas y adosado a los muros consolidados de la torre de la loma medieval. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36054','mirador','Mirador de San Xoán (Amorín)','8.9/10 Vista del curso fluvial bajo del río Miño ensanchándose hacia el estuario, rodeado de viveros de plantas tradicionales. Cómo llegar: Explanada perimetral de la capilla de San Xoán, balcón natural sobre la ribera fronteriza. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36014','mirador','Mirador del Paseo de la Corredera / Catedral','9.6/10 Insuperable, mística y bella postal de la catedral fortificada gótica, el casco medieval de piedra, el puente y Portugal. Cómo llegar: Paseo fluvial del adarve de las murallas medievales, balconada colgada urbana histórica. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36056','mirador','Mirador de la Fervenza de Raxoi','8.2/10 Paisaje fluvial encajonado de montaña con molinos hidráulicos tradicionales de piedra y saltos de agua del río Valga. Cómo llegar: Sendero peatonal acondicionado del paraje natural de Raxoi, pasarelas de madera. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36015','mirador','Mirador de O Castro / El Olivo','9.8/10 Abrumadora visual cenital de la mayor ciudad gallega, el puerto comercial, el puente de Rande y las paradisíacas islas Cíes. Cómo llegar: Almenas del castillo fortificado del monte de O Castro, parque ajardinado céntrico elevado. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36059','mirador','Mirador de la Carixa / Ulla','8.8/10 Vista espectacular de la vega del río Ulla con áreas recreativas de agua limpia, puentes tradicionales y carballeiras densas. Cómo llegar: Paraje natural de A Carixa, senderos de herradura fluviales acondicionados de la ribera. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36058','mirador','Mirador de las Salinas de Ulló','8.9/10 Histórico e impresionante complejo de salinas de los jesuitas del siglo XVII con canales, aves y la ensenada de San Simón. Cómo llegar: Pasarela de madera ecológica del sendero litoral del fondo de la ría de Vigo. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36016','mirador','Mirador del Monte Lobeira','9.4/10 Inmensa dehesa y canchales de granito coronados por un hito monumental que vigila toda la inmensa ría de Arousa. Cómo llegar: Cima del pico de Lobeira a 290 metros, pasarelas metálicas con escaleras sobre la roca viva. 📍 Provincia: Pontevedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36061','mirador','Mirador del Monte Lobeira (Vertiente Vilanova) / Valle-Inclán','8.9/10 Vista aérea del entramado histórico y marinero vinculado al escritor modernista sobre las playas y bateas litorales. Cómo llegar: Explanada de la Cruz de Lobeira, sendero local balizado desde las afueras residenciales. ¡Cierre cartográfico rotundo! Con el municipio de Vilanova de Arousa finalizado meticulosamente, la provincia de Pontevedra queda registrada al 100% de su mapa territorial. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','mirador','Mirador del Pazo de Mariñán','8.8/10 Vista señorial e idílica del jardín botánico de camelias volcándose sobre las marismas y aguas tranquilas de la ría de Betanzos. Cómo llegar: Terrazas superiores y escalinatas de piedra sillar del complejo palaciego fortificado. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90184','mirador','Mirador de Pedras de Pasos','8.4/10 Vista limpia de la cuenca del río Tambre, campos agrícolas del interior gallego y los contrafuertes boscosos periurbanos de Santiago. Cómo llegar: Senda forestal acondicionada en el cordal del cerro de Pedras de Pasos. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90185','mirador','Mirador del Campo da Frieira','8.6/10 Impresionante e inhóspito paisaje serrano de matorral atlántico y roca granítica dominando el salvaje curso alto del río Mandeo. Cómo llegar: Pista forestal transitable que asciende hacia los aerogeneradores de la Serra da Loba. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90001','mirador','Mirador de Montefaro','9.2/10 Espectacular perspectiva de doble vertiente sobre las rías de Ferrol y Ares-Betanzos, con el océano Atlántico fundiéndose en el horizonte. Cómo llegar: Inmediaciones del antiguo monasterio fortificado de Montefaro, batería militar transitable de cañones. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90002','mirador','Mirador de O Santuario (Monte de Angra)','8.9/10 Contraste absoluto entre el salvaje oleaje que rompe en las playas de Sabón y el potente cinturón industrial portuario exterior. Cómo llegar: Cima del Monte de Angra, plataforma acondicionada con barandilla protectora al oeste del núcleo. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90186','mirador','Mirador del Embalse de Portodemouros','8.5/10 Hermosa vista de la inmensa lámina de agua dulce encajada entre colinas boscosas, con la barcaza tradicional cruzando el cauce. Cómo llegar: Área recreativa de la orilla norte, carretera local pavimentada de acceso al embarcadero. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90187','mirador','Mirador del Teso de San Baínz','7.6/10 Suave horizonte agrícola de cultivos cerealistas y carballeiras dispersas características del interior coruñés del valle del Tambre. Cómo llegar: Hito de tierra batida en la meseta agraria alta, junto al depósito regulador de agua. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01003','mirador','Mirador del Parque del Pasatiempo / Murallas','9.4/10 Vista aérea del entramado medieval de la capital gótica del gótico gallego unida a los caprichosos relieves del parque enciclopédico modernista. Cómo llegar: Balconada alta de las murallas de la plaza de la Constitución o terraza del león del parque. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90188','mirador','Mirador del Camino del Norte','7.5/10 Perspectiva rural de prados verdes infinitos ganaderos y muros tradicionales de piedra que guían a los peregrinos jacobeos. Cómo llegar: Pista agrícola sobreelevada cercana a las canteras de tejas romanas restauradas. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01004','mirador','Mirador del Monte Iroite','9.6/10 Inmensa, abrumadora y monumental visual de toda la ría de Arousa tapizada de bateas, la sierra del Barbanza y dólmenes. Cómo llegar: Base exterior de la base militar de radares aéreos, carretera de montaña de alta cota. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90189','mirador','Mirador del Pico Sacro','9.5/10 Mística e imponente aguja de cuarzo blanco sagrada con vistas completas de 360 grados del valle del Ulla y Compostela. Cómo llegar: Cima rocosa del Pico Sacro, escaleras excavadas en la roca viva con barandilla metálica de protección. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90190','mirador','Mirador de las Torres de Altamira','8.4/10 Atalaya sobre el valle de Mahía desde las ruinas consolidadas del imponente castillo feudal medieval de la comarca. Cómo llegar: Espolón rocoso de la fortaleza señorial alta, sendero empedrado peatonal desde el núcleo. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90004','mirador','Mirador del Castro de Borneiro / Monte Branco','93/10 Impresionante vista del poblado fortificado de la Edad del Hierro excavado y el estuario del río Anllóns cubierto de dunas blancas. Cómo llegar: Pasarelas de madera del conjunto arqueológico de la ladera forestal de robles. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90005','mirador','Mirador del pinar de la Playa de Madalena','8.7/10 Vista costera apacible de la playa arqueada, el frondoso bosque de pinos marítimos y la desembocadura de la ría de Ares. Cómo llegar: Paseo de madera ecológico perimetral de las dunas del frente litoral protegido. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01005','mirador','Mirador del Faro Vilán','9.7/10 Salvaje e indómito confín de la Costa da Morte, con acantilados de granito rosado azotados por el Atlántico y un faro monumental [10.2]. Cómo llegar: Pasarela rocosa junto al enclave del faro, final de la carretera provincial DP-1603 [10.2]. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90191','mirador','Mirador del Embalse de Cecebre','7.8/10 Perspectiva boscosa y lacustre sobre el humedal protegido, rodeado de fragas atlánticas e hileras de sauces del río Mero. Cómo llegar: Entorno acondicionado del área recreativa de la presa, accesible desde el casco urbano. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01006','mirador','Mirador de Razo - Baldaio','8.9/10 Inmensa panorámica costera sobre el cordón dunar virgen, las marismas salinas y la kilométrica playa atlántica abierta. Cómo llegar: Explanada elevada del escarpe del extremo occidental de la playa de Razo. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15901','mirador','Mirador de Cabo Ortegal / Vixía de Herbeira','9.9/10 Abrumador y colosal balcón sobre los acantilados marinos más altos de la Europa continental, cortados a plomo sobre el oleaje [10.3, 10.4]. Cómo llegar: Kilómetro 12 de la carretera escénica de montaña DP-2205, caseta de piedra al borde del abismo [10.4]. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01007','mirador','Mirador de As Paxareiras','9.6/10 Espectacular e infinita vista aérea sobre la kilométrica playa de Carnota, la marisma protegida y el indómito Monte Pindo. Cómo llegar: Puerto de montaña de la carretera AC-550, apartadero acondicionado con paneles interpretativos geográficos. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15022','mirador','Mirador de San Andrés de Teixido','9.8/10 Mística postal de la mítica aldea de peregrinación colgada en un acantilado vertical salvaje sobre el océano Atlántico bravo. Cómo llegar: Senda de herradura de los acantilados altos, balconada de piedra caliza integrada en el linde del pueblo. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15023','mirador','Mirador de la Ría de Corcubión / Gures','9.0/10 Vista limpia de la ensenada marina, los pinares costeros densos y la silueta lejana de las faldas del cabo Fisterra. Cómo llegar: Mirador de Gures, ensanche acondicionado con muretes y vallas en la carretera comarcal AC-550. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15024','mirador','Mirador de la Lagoa das Encrobas','7.9/10 Impactante paisaje de una colosal mina de lignito a cielo abierto recuperada y convertida en un gran lago turquesa forestal. Cómo llegar: Plataforma con paneles del itinerario ambiental protegido de la antigua explotación minera. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15025','mirador','Mirador del valle de las explotaciones de cobre','8.1/10 Paisaje interior ondulado caracterizado por densos bosques atlánticos de castaños y las cuencas fluviales que miran a Ortigueira. Cómo llegar: Pista forestal transitable que corona la loma del antiguo hito minero de la población. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15027','mirador','Mirador de la Espenuca','8.6/10 Impresionante atalaya rocosa sobre los meandros encajonados del río Mandeo, rodeada por robledales densos y pinares altos. Cómo llegar: Atrio empedrado de la ermita románica en la cima del monte de A Espenuca, acceso forestal. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15029','mirador','Mirador del llano de Bergantiños','7.4/10 Perspectiva horizontal agrícola de la fértil capital de la patata gallega, con parcelas de cultivo tradicionales y lomas bajas. Cómo llegar: Camino rural elevado de tierra compactada cercano a las cooperativas agrarias del norte. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15028','mirador','Mirador del Castillo de Cardenal','9.2/10 Histórica panorámica defensiva de la ría desde la fortaleza del siglo XVIII, controlando el paso marítimo de la bocana portuaria. Cómo llegar: Murallas exteriores de la batería de costa fortificada, sendero costero peatonal adaptado. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01001','mirador','Mirador del Monte de San Pedro / Torre de Hércules','9.8/10 Insuperable y monumental visual cenital del faro romano más antiguo del mundo, el istmo urbano, las playas y las baterías. Cómo llegar: Cúpula del ascensor panorámico esférico o balconadas del parque fortificado del Monte de San Pedro. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15031','mirador','Mirador del Monte Xalo','8.0/10 Gran altitud sobre el área metropolitana, las pistas aeronáuticas del aeropuerto de Alvedro y la ría del Burgo forestal. Cómo llegar: Hito de vigilancia y canchales de granito de la cumbre del Monte Xalo, pista de montaña. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15032','mirador','Mirador del Teso de Carral','7.8/10 Amplia perspectiva rural del interior gallego central, compuesta por un mosaico de prados verdes ganaderos, pinares y dehesas de robles. Cómo llegar: Camino agrícola elevado de tierra compactada contiguo a los depósitos de agua municipales. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15033','mirador','Mirador de las Brañas de Laíño','8.4/10 Espectacular vista horizontal del ancho valle fluvial del río Ulla, sus humedales protegidos, marismas bajas y plantaciones forestales. Cómo llegar: Sendero peatonal interpretativo de las brañas, pasarela de madera en el linde del cauce. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15034','mirador','Mirador del Ézaro','9.6/10 Impresionante e insuperable atalaya sobre la desembocadura en cascada del río Xallas directos al océano Atlántico y el Monte Pindo. Cómo llegar: Pasarelas de madera y plataforma volada sobre el abismo de la carretera local que sube a la presa. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15035','mirador','Mirador de Maniños','8.2/10 Vista aérea de la ría de Ferrol, los astilleros históricos industriales tradicionales y las lomas forestales densas del interior. Cómo llegar: Calle del mirador, plataforma de piedra con barandilla protectora urbana en el barrio alto. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15036','mirador','Mirador de los Castillos de la Palma y San Felipe','9.4/10 Soberbia panorámica defensiva militar del angosto canal de entrada a la ría con las monumentales fortalezas del siglo XVIII de piedra sillar. Cómo llegar: Almenas superiores del Castillo de San Felipe, paseo de ronda accesible del frente litoral. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01011','mirador','Mirador del Cabo Fisterra (Fin del Mundo)','9.9/10 Mítica, abrumadora e incomparable atalaya costera considerada el confín occidental del mundo antiguo con puestas de sol eternas. Cómo llegar: Explanada del faro de Fisterra, tramo terminal de la carretera paisajística de la península caliza. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15038','mirador','Mirador del río Tambre (A Ponte Carreira)','7.2/10 Vista baja y despejada del remanso del río Tambre flanqueado por densos carballeiras de robles y huertas tradicionales rústicas. Cómo llegar: Paseo de la ribera del área recreativa, senderos pedestres de tierra compactada. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90192','mirador','Mirador de la Sierra de la Pena del Oso','8.1/10 Vista salvaje y serrana de matorrales atlánticos espesos que marcan el linde del espacio natural protegido del río Mandeo. Cómo llegar: Pista forestal transitable que corona la colina eólica alta de la sierra. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15041','mirador','Mirador de Caión','8.6/10 Espectacular e histórica villa marinera colgada de la roca rompiendo el fuerte oleaje de la antesala de la Costa da Morte. Cómo llegar: Paseo de las murallas del puerto viejo, barandilla de hierro sobre los acantilados marinos bajos. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90006','mirador','Mirador del Faro de Laxe / Monte Insua','9.5/10 Impresionante saliente calizo marino azotado por la tramontana con vistas directas de la ría de Corme y Laxe y acantilados. Cómo llegar: Complejo del faro de Laxe, sendero costero del GR-92 perimetral de la roca viva. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15042','mirador','Mirador de San Lois / Minas de San Finx','9.1/10 Excepcional balcón de montaña granítico que domina de forma cenital toda la ría de Muros y Noia e históricas minas de wolframio. Cómo llegar: Cima del Monte de San Lois, pasarelas metálicas con escaleras integradas en el cerro. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15043','mirador','Mirador del Cabo San Adrián / Islas Sisargas','9.6/10 Impresionante e icónica perspectiva del archipiélago virgen de las Sisargas recortando el oleaje bravo atlántico desde el acantilado. Cómo llegar: Explanada de la ermita de San Adrián, pista costera de herradura señalizada del norte. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15044','mirador','Mirador del Estaca de Bares','9.9/10 Hito geográfico supremo al ser el punto septentrional absoluto de la Península Ibérica, divisoria exacta entre el Atlántico y el Cantábrico [10.5]. Cómo llegar: Sendero de los acantilados del faro de Bares, balconada de piedra caliza colgada sobre el abismo marino [10.5]. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15045','mirador','Mirador de Ruña','8.8/10 Vista de dehesas montañosas rústicas e inmenso pastizal alpino rodeado por los imponentes canchales graníticos del macizo. Cómo llegar: Pista de servicio del parque eólico alto de la Sierra de Ruña, barandilla de madera. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90842','mirador','Mirador del Cruceiro de Melide','8.4/10 Valor histórico y místico único en el corazón geográfico de la confluencia de los caminos de Santiago Francés y Primitivo. Cómo llegar: Entorno empedrado de la capilla de San Roque, plaza monumental urbana del centro. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15047','mirador','Mirador del Castillo de Mesía','7.3/10 Ruinas consolidadas de la fortaleza defensiva medieval rodeadas de prados de ganado tradicionales y pequeños robledales. Cómo llegar: Cima de la loma del complejo arqueológico fortificado de la pedanía de Póboa. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15048','mirador','Mirador de la Ría de Betanzos (Punta de Fraga)','8.5/10 Vista de la ensenada marina con playas bajas de arena blanca, marismas del cauce del Baxoi y pinares marítimos densos. Cómo llegar: Paseo marítimo alto del litoral, pasarelas de madera ecológicas de la costa. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15049','mirador','Mirador del Castillo de Moeche','8.6/10 Imponente postal del castillo de piedra sillar vinculado a las históricas revueltas de los Irmandiños, en un verde valle. Cómo llegar: Muros exteriores y foso de la fortaleza de la loma medieval, accesible por rampa. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15050','mirador','Mirador del Monasterio de Monfero / Fragas do Eume','9.5/10 Solemne perspectiva de la imponente fachada ajedrezada barroca barroca rodeada por el mayor bosque atlántico protegido de Europa. Cómo llegar: Explanada de piedra de la abadía medieval alta, carretera local escénica de las Fragas. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15051','mirador','Mirador del Castillo de la Palma','8.9/10 Histórica panorámica del estrecho canal militar de Ferrol desde el baluarte defensivo bajo, controlando los barcos. Cómo llegar: Paseo de ronda fortificado costero, carretera local del muelle marinero tradicional. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15053','mirador','Mirador del Monte Louro','9.6/10 Impresionante e icónica estampa del cono granítico perfecto exento cerrando la ría, con la laguna dunares de Xarfas en su base. Cómo llegar: Carretera costera AC-550, apartaderos señalizados con paneles interpretativos geográficos en los riscos. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01013','mirador','Mirador de la Virgen de la Barca / Monte Corpiño','9.8/10 Místico santuario marino alzado sobre las rocas del oleaje con la "Pedra de Abalar" y vistas de infarto de la Costa da Morte. Cómo llegar: Cima rocosa del Monte Corpiño, senderos pedestres escalonados desde la explanada del santuario costero. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15054','mirador','Mirador de los Acantilados de O Coto','8.8/10 Vista costera salvaje de los riscos que protegen el norte del municipio, playas batidas e hileras de pinos piñoneros. Cómo llegar: Senda del litoral norte, pasarela de madera con barandilla sobre el escarpe natural. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15055','mirador','Mirador de Anca','8.5/10 Panorámica sobre el valle de Neda, las cascadas del río Belelle y la fosa fluvial de la ría ferrolana. Cómo llegar: Explanada alta arbolada de la colina de Anca, barandilla de madera sobre el talud. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15056','mirador','Mirador del Pazo de Cotón','8.4/10 Vista del entramado histórico señorial gallego con la monumental galería fortificada sobre el Camino de Fisterra. Cómo llegar: Paseo público peatonal de la calle alta contiguo a los arcos de piedra del pazo. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01014','mirador','Mirador de San Marcos / Ría de Noia','9.1/10 Vista de pájaro del casco histórico medieval de piedra, los puentes que cruzan el río Tambre y la ensenada marina. Cómo llegar: Explanada de la ermita alta de San Marcos, pista de subida helicoidal pavimentada. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15058','mirador','Mirador del Castillo de Santa Cruz','9.3/10 Preciosa e icónica postal de la fortaleza isleña unida por una pasarela de madera, dominando la bahía coruñesa. Cómo llegar: Paseo marítimo perimetral de la isla del castillo, accesos adaptados peatonales de tierra. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90193','mirador','Mirador de la Vía Verde de Órdenes','7.2/10 Perspectiva horizontal de prados verdes ganaderos tradicionales y dehesas forestales del corredor central de comunicaciones. Cómo llegar: Antiguo apeadero ferroviario acondicionado del tramo peatonal cicloturístico. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15060','mirador','Mirador de Sigüeiro / Río Tambre','7.4/10 Vista de la vega baja agrícola tradicional y sotos de ribera cruzados por el histórico puente medieval de piedra de Sigüeiro. Cómo llegar: Parque fluvial de la ribera del Tambre, accesos peatonales de tierra. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15061','mirador','Mirador del Banco de Loiba','9.7/10 Mundialmente famoso e impresionante balcón con el "mejor banco del mundo" colgado sobre acantilados costeros verticales calcáreos gigantes. Cómo llegar: Senda del litoral norte de Loiba, plataforma con el banco de madera fijado al borde del abismo. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15062','mirador','Mirador de Tremuzo','9.0/10 Inmensa atalaya a 500 metros sobre la desembocadura del río Tállara, astilleros de madera viejos y la ría de Noia. Cómo llegar: Cima del Monte Tremuzo, pista forestal de montaña asfaltada que arranca de las afueras. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15902','mirador','Mirador del Sanatorio de Cesuras','7.6/10 Paisaje forestal íntimo de pinos y eucaliptos gigantes que cobija las ruinas racionalistas del antiguo sanatorio antituberculoso de piedra. Cómo llegar: Claro del bosque del área monumental recreativa, sendero pedestre señalizado. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15064','mirador','Mirador de San Pantaleón','8.3/10 Vista del valle de inundación de los ríos Mandeo y Mendo abriéndose paso hacia las marismas de la ría de Betanzos. Cómo llegar: Explanada de la ermita gótica superior, colina exenta con murete de piedra. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15065','mirador','Mirador del Convento del Carmen / Santiaguiño do Monte','9.1/10 Histórica y legendaria atalaya de la traslación jacobea, dominando el valle del Sar, el río Ulla y las plantaciones hortícolas de pimientos. Cómo llegar: Explanada de las rocas sagradas del Santiaguiño do Monte, escaleras de piedra monumentales de la ladera. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15066','mirador','Mirador de Amenal (Antesala de Lavacolla)','7.8/10 Vista de dehesas forestales de eucaliptos y carballeiras en el último linde del Camino Francés previo a las pistas aeronáuticas. Cómo llegar: Sendero jacobeo de la colina de Amenal, área forestal acondicionada con bancos rústicos. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01002','mirador','Mirador de Valle-Inclán / Las Piscinas do Río Pedras','9.6/10 Abrumadora visual de un cañón geológico fluvial de pozas naturales excavadas en granito y el majestuoso mirador de A Curota [10.6]. Cómo llegar: Cima del monte de A Curota, carretera de alta montaña de la sierra del Barbanza [10.6]. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90194','mirador','Mirador de Monte Branco (Valdoviño)','92/10 Espectacular e inmensa duna de arena blanca gigante remontando la ladera boscosa de la desembocadura de la ría de Corme. Cómo llegar: Plataforma con paneles interpretativos de la duna móvil de Monte Branco, sendero costero local. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01017','mirador','Mirador de la Torre de los Andrade / Cabanas','9.6/10 Insuperable, mística y bella postal del puente de los osos medieval, el torreón señorial de la villa y la ría del Eume. Cómo llegar: Paseo de ronda de la torre de los Andrade o mirador urbano alto de la calle de la muralla. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15070','mirador','Mirador del Lago de las Pontes (Playa de Interior)','8.9/10 Espectacular paisaje de una colosal mina de carbón a cielo abierto reconvertida en el lago artificial más grande de España con playa. Cómo llegar: Paseo marítimo de interior del lago de las Pontes, muelles y rampas de madera ecológica. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90007','mirador','Mirador del Castro de Baroña','9.7/10 Impresionante e histórica atalaya sobre un poblado celta fortificado de la Edad del Hierro edificado sobre una península exenta de rocas marínas [10.7]. Cómo llegar: Sendero pedestre arqueológico de Baroña, acceso desde el centro de recepción de la carretera AC-550 [10.7]. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01018','mirador','Mirador de la Torre de Teodomiro (Castelo de Luna)','8.8/10 Vista costera de la ensenada del río Ulla desembocando en el Salnés, las bateas marineras y campos tradicionales gallegos. Cómo llegar: Ruinas consolidadas de la torre de la fortaleza costera medieval de la punta de Rianxo. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15073','mirador','Mirador de las Dunas de Corrubedo / Pedra da Rá','9.6/10 Impresionante monumento natural de la duna móvil gigante de arena blanca, lagunas costeras protegidas y la peña de la Rana. Cómo llegar: Complejo de pasarelas del Parque Natural de Corrubedo o mirador granítico alto de Pedra da Rá. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15074','mirador','Mirador de O Castelo de San Alberto','7.9/10 Suave oleaje montañoso con bosques de pinos y carballeiras que arropan los restos de la antigua fortificación medieval. Cómo llegar: Pista forestal transitable de tierra compactada de la colina alta periférica del municipio. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15075','mirador','Mirador de la Terraza de Sada / Puerto','8.8/10 Vista costera urbana del dinámico puerto deportivo presidido de forma icónica por la gran joya modernista de madera de La Terraza. Cómo llegar: Paseo marítimo de la playa de las Delicias, plataforma peatonal frente al monumento modernista. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15076','mirador','Mirador del Pazo de San Sadurniño','8.2/10 Entorno de campiña arbolada de castaños y camelias que alberga el histórico pazo señorial señorial al norte de Ferrol. Cómo llegar: Jardines y arboledas del complejo monumental rústico de la localidad, paseos de tierra. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15077','mirador','Mirador del llano de la Terra de Xallas','7.3/10 Perspectiva horizontal agrícola ganadera de prados verdes infinitos que marcan la meseta central interior de la provincia. Cómo llegar: Camino rural de servicio contiguo a las balsas de regulación del término municipal. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','mirador','Mirador del Paseo de la Herradura (Parque de la Alameda)','9.8/10 Insuperable, mística y bella visual de las torres barrocas de la Catedral surgiendo de forma majestuosa sobre el casco viejo de piedra. Cómo llegar: Paseo de la Herradura, balconada urbana acondicionada con bancos de piedra bajo robles monumentales. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15079','mirador','Mirador de las Riberas del río Ulla','7.8/10 Paisaje fluvial encajonado interior con densas dehesas boscosas tradicionales asociadas al límite provincial de Lugo. Cómo llegar: Camino forestal de tierra compactada de la ribera, desvío señalizado del sendero local. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15080','mirador','Mirador de la Laguna de Sobrado / Monasterio','9.1/10 Espectacular e histórica laguna artificial medieval monástica con carrizales, aves acuáticas y los muros de la abadía cisterciense. Cómo llegar: Sendero perimetral de la laguna de Sobrado dos Monxes, tramo del Camino del Norte protegido. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15081','mirador','Mirador de la Sierra de Faladoira','7.5/10 Vista de dehesas forestales onduladas cubiertas por prados rústicos e infraestructuras eólicas modernas del norte. Cómo llegar: Pista agrícola transitable de la loma exenta, camino de servicio del parque eólico. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15082','mirador','Mirador de los Pasos de San Xoán / río Sar','8.4/10 Vista baja de un cañón fluvial arbolado con puentes de piedra tradicionales, canteras de granito viejas y fragas densas. Cómo llegar: Senda fluvial del río Sar, área recreativa acondicionada con miradores y pasarelas de madera. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15083','mirador','Mirador de la Fervenza de Brañas / San Antoniño','8.9/10 Impresionante paraje de agua limpia con una cascada natural gigante y la joya prerrománica de San Antoniño excavada en el bosque. Cómo llegar: Sendero pedestre arqueológico de la ruta de Toques, pasarelas de madera del desfiladero. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90843','mirador','Mirador del Dolmen de Cabaleiros','7.4/10 Paisaje megalítico prehistórico llano con la gran mesa de piedra del dolmen rodeada de prados de ganado y dehesas de eucaliptos. Cómo llegar: Yacimiento arqueológico acondicionado en la loma agrícola del término de Cabaleiros. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15085','mirador','Mirador de la Fervenza de Chousa / río Ulla','8.5/10 Espectacular salto de agua natural encajado entre densos robledales, fragas atlánticas e históricas zanjas mineras de cobre viejas. Cómo llegar: Sendero interpretativo de la ruta de las cascadas de Touro, pasarelas de madera de la ribera. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15086','mirador','Mirador del valle del Tambre central','7.3/10 Suave oleaje de tierras agrarias ganaderas tradicionales cortadas por los meandros boscosos del río Tambre alto. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90195','mirador','Mirador de las dehesas del Dubra','7.5/10 Perspectiva horizontal de prados verdes e hileras forestales que marcan el fondo del valle fluvial agrícola de la comarca. Cómo llegar: Camino agrícola elevado de la colina que domina la villa de Bembibre. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15087','mirador','Mirador de la Laguna de Frouxeira / Playa de Pantín','9.6/10 Espectacular e inmenso humedal costero con dunas, avifauna protegida y la mítica ola del santuario del surf mundial de Pantín. Cómo llegar: Mirador de O Paraño, apartadero acondicionado con paneles de piedra caliza en la carretera costera. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15089','mirador','Mirador del Pazo de Santa Cruz de Rivadulla','8.9/10 Paisaje señorial botánico incomparable con paseos monumentales de olivos centenarios tradicionales e hileras de camelias gigantes. Cómo llegar: Jardines y cascadas artificiales del complejo del pazo, acceso señalizado en el valle del Ulla. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90844','mirador','Mirador do Monte da Feira','7.8/10 Vista de dehesas forestales de pinos y matorral atlántico en las lomas que marcan la transición hacia las rías de Miño. Cómo llegar: Hito de la antigua feria tradicional rústica, camino forestal batido del cerro de la población. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15090','mirador','Mirador del Campamento Romano de Ciadella','8.0/10 Valor histórico único sobre el recinto arqueológico militar imperial del siglo II d.C. integrado en las verdes dehesas ganaderas. Cómo llegar: Centro de interpretación arqueológico, sendero perimetral sobre los muros de piedra del campamento romano. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15092','mirador','Mirador del Castillo de Vimianzo / Ruta de los Dólmenes','9.1/10 Impresionante fortaleza señorial medieval con sus torres almenadas perfectamente conservadas dominando el valle y valles de dólmenes. Cómo llegar: Almenas superiores del castillo señorial alto, acceso peatonal empedrado en el centro de la villa. 📍 Provincia: La Coruña (A Coruña).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15093','mirador','Mirador del Pico de Picoña / Torres de Allo','8.4/10 Espectacular panorámica de la cuenca interior de la Tierra de Soneira, dehesas forestales densas y el entorno noble del pazo histórico de las Torres de Allo. Cómo llegar: Hito rocoso elevado de la colina de Picoña, accesible por caminos rurales de tierra compactada. ¡Misión completada con éxito rotundo! Con el municipio de Zas registrado rigurosamente de la A a la Z, la provincia de La Coruña (A Coruña) queda oficialmente cerrada al 100% de su geografía municipal. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90543','mirador','Mirador de la Frouxeira / Castillo de Castro de Ouro','8.6/10 Impresionante e histórica atalaya sobre el valle de Alfoz y el mariscal Pardo de Cela, rodeada por rocas graníticas y densos eucaliptales. Cómo llegar: Cima de la peña de A Frouxeira o murallas fortificadas de la torre del homenaje de Castro de Ouro. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90544','mirador','Mirador del Castillo de Amarante','8.2/10 Vista de dehesas forestales ricas de robles y prados ganaderos tradicionales que custodian el palacio amurallado fortificado de la comarca. Cómo llegar: Camino rural sobreelevado de tierra compactada en el perímetro de la fortaleza medieval. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90545','mirador','Mirador de la Marronda (Alto do Acebo)','8.5/10 Majestuoso e impenetrable pulmón verde boscoso del bosque de hayas más meridional de Europa, con profundos barrancos del río Eo. Cómo llegar: Puerto del Acebo en la carretera LU-530, sendero de montaña señalizado hacia los riscos altos. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90040','mirador','Mirador del Monte Comado','9.2/10 Espectacular e inmensa rampa natural de despegue de parapente con vistas de pájaro de las playas de la Mariña y el mar Cantábrico. Cómo llegar: Cima del Monte Comado, pista forestal asfaltada de alta cota desde San Cosme. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28001','mirador','Mirador de Cruz de Carballal (Os Ancares)','8.9/10 Salvaje e imponente perspectiva de los valles del Navia, prados alpinos ganaderos y los contrafuertes de la reserva de la biosfera. Cómo llegar: Arcén acondicionado con murete de piedra rústica en la carretera de montaña de acceso a los Ancares. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90546','mirador','Mirador de las Insuas del Miño','7.6/10 Vista baja y despejada del curso alto del río Miño, islas fluviales de gravas y humedales someros con densos carrizales. Cómo llegar: Sendero botánico peatonal adaptado con pasarelas de madera en el espacio natural protegido. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90547','mirador','Mirador del Pazo de Tor (Lemos)','81/10 Vista de la llanura de la comarca de Lemos y campos de cultivo tradicionales que arropan el monumental pazo palaciego neoclásico. Cómo llegar: Terrazas superiores y balaustrada del jardín señorial del pazo fortificado. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90548','mirador','Mirador de A Cova (Ribeira Sacra)','9.4/10 Impresionante e icónica estampa del espectacular meandro de herradura (O Cabo do Mundo) del río Miño encajado bajo viñedos heroicos. Cómo llegar: Senda del vino de Barantes, plataforma metálica con barandilla volada directamente sobre el abismo fluvial. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90549','mirador','Mirador del Castro de Viladonga','7.8/10 Enorme valor histórico y místico sobre un colosal poblado fortificado galaico-romano excavado que domina toda la Terra Chá. Cómo llegar: Pasarelas del parque arqueológico acondicionado y mirador contiguo al museo de interpretación. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90550','mirador','Mirador de la Torre del Homenaje del Castillo','8.3/10 Atalaya defensiva del siglo XIV que domina el paso del Camino de Santiago Primitivo, campos de cereal y robledales densos. Cómo llegar: Plataforma superior accesible de la antigua e histórica torre del homenaje prismática del pueblo. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90551','mirador','Mirador del Castillo de Doiras (Os Ancares)','9.6/10 Impresionante e indómito paisaje montanés de canchales con la majestuosa fortaleza medieval encaramada en una cresta entre robles y pallozas. Cómo llegar: Pista de aproximación al peñón del castillo de Doiras, carretera escénica alpina de alta cota. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90041','mirador','Mirador de San Roque (Sargadelos)','8.8/10 Vista de la cuenca industrial histórica papeleras y cerámica de Sargadelos, rodeada de frondosos bosques de eucaliptos y mar. Cómo llegar: Paseo de los enamorados de la presa vieja, sendero peatonal de tierra compactada de la ribera. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27016','mirador','Mirador de San Fiz / Ribeira Sacra','9.5/10 Insuperable visual de laderas verticales cultivadas de cepas heroicas de mencía descendiendo abruptamente hacia el embalse de Belesar. Cómo llegar: Iglesia románica de San Fiz de Asma, apartadero rústico con barandilla en el borde del talud vinícola. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90552','mirador','Mirador del río Chamoso','7.4/10 Suave horizonte de carballeiras y pastizales rústicos de ganado cortados por los sotos tradicionales del río Chamoso. Cómo llegar: Camino rural sobreelevado junto a los antiguos molinos hidráulicos del término municipal. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90553','mirador','Observatorio de la Lagoa de Cospeito','8.0/10 Extenso humedal de la Terra Chá con pasarelas de madera para el avistamiento de aves migratorias, ánades y carrizales. Cómo llegar: Centro de interpretación de la laguna, senderos peatonales adaptados sobre la llanura. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27017','mirador','Mirador de Penoselo / Alto do Couto','9.8/10 Abrumadora y salvaje postal de la Serra do Courel con espectaculares valles glaciales tectónicos, densas dehesas paleolíticas de castaños y picos calizos. Cómo llegar: Carretera de montaña de alta cota LU-P-1301, apartadero rocoso acondicionado al borde del abismo forestal. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27019','mirador','Mirador del Monte Pico de Cornería / San Martiño','9.3/10 Vista aérea idílica de la ría de Foz, playas doradas cantábricas y la histórica Basílica de San Martiño de Mondoñedo [10.5, 10.6]. Cómo llegar: Cima del Monte Cornería, plataforma de madera con paneles interpretativos dominando el litoral mariñano. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27020','mirador','Mirador de la Fortaleza de San Paio de Narla','8.1/10 Atalaya feudal con una imponente torre del homenaje granítica que vigila prados verdes y carballeiras del interior de la provincia. Cómo llegar: Almenas superiores del conjunto fortificado medieval, actual museo etnográfico local. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27022','mirador','Mirador de la Fervenza de Díaz','8.2/10 Hermoso y denso rincón de bosque atlántico con un salto de agua limpia esculpiendo el cauce rocoso del río Parga. Cómo llegar: Senda del agua de Guitiriz, pasarelas rústicas de madera en el paraje natural de la cascada. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27023','mirador','Mirador de Ferreira / Río Miño','7.8/10 Suave transición de colinas cubiertas de espesos pinos piñoneros y carballeiras sobre las riberas del cauce medio del Miño. Cómo llegar: Pista agrícola transitable de tierra compactada en paralelo al corredor verde fluvial. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27026','mirador','Mirador del puente medieval de Carracedo','7.6/10 Vista rural apacible de los prados de pastizal ganadero tradicionales cortados por el curso fluvial del río Neira. Cómo llegar: Entorno empedrado inmediato al histórico puente de sillería de herencia jacobea. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90554','mirador','Mirador de la Cuesta de Vilanova / San Salvador','8.7/10 Panorámica sobre el fértil valle del haba de Lourenzá arropado por eucaliptales y el imponente monasterio barroco. Cómo llegar: Tramo elevado de la carretera nacional N-634, mirador acondicionado con barandillas de madera. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27028','mirador','Mirador del Adarve de la Muralla de Lugo','9.5/10 Insuperable, majestuosa e histórica visual sobre el entramado urbano medieval y las torres de la catedral desde el único cinturón romano intacto. Cómo llegar: Paseo de ronda peatonal de la muralla de piedra Patrimonio de la Humanidad, accesos por rampas históricas. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27029','mirador','Mirador de Pedregal de Irimia / Serra de Meira','8.4/10 Impresionante e icónica estampa geológica de un río de piedras graníticas subterráneo que marca el nacimiento oficial del río Miño. Cómo llegar: Paraje natural de O Pedregal, plataforma de piedra con vallas interpretativas en la falda serrana. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','mirador','Mirador de los Remedios / Catedral','9.4/10 Vista aérea espectacular de la ciudad episcopal arropada por colinas boscosas, su rosetón catedralicio gótico y el barrio de los molinos. Cómo llegar: Explanada del santuario alto de la Virgen de los Remedios, barandilla de piedra sillar urbana. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','mirador','Mirador de San Vicente del Pino / Alcazaba','9.6/10 Inmensa visual sobre el valle de Lemos, el conjunto monumental fortificado de la torre del homenaje, monasterios y viñedos bajos. Cómo llegar: Parador de Turismo de Monforte, plaza alta de la torre señorial del siglo XIV que corona el peñón. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27032','mirador','Mirador de las Riberas del Ulla (A Peneda)','8.1/10 Vista baja de la vega del río Ulla con áreas recreativas tradicionales de agua limpia de carballeiras y huertas del Alto Ulla. Cómo llegar: Parque de A Peneda, sendero peatonal acondicionado junto al histórico azud de mampostería. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27033','mirador','Mirador de la Serra do Xistral','8.3/10 Paisaje bravío de montaña redondeada azotado por el viento con brezales húmedos, caballos salvajes e hileras de aerogeneradores. Cómo llegar: Pista de servicio forestal de alta cota que recorre los parques eólicos de la sierra. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27034','mirador','Mirador del Puente de la Puebla / Os Ancares','9.2/10 Preciosa e imponente estampa de un monumental puente medieval de arco apuntado gigante cruzando el río Navia salvaje. Cómo llegar: Sendero local fluvial del Parque Natural de los Ancares, en la base rocosa del núcleo antiguo. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27035','mirador','Mirador del Embalse de Salime / Viñedos heroicos','8.9/10 Espectacular encajonamiento fluvial del río Navia transformado en gran lámina de agua dulce entre vertiginosos viñedos altos de ladera. Cómo llegar: Apartadero de la carretera local de montaña que desciende hacia el embarcadero abandonado. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90845','mirador','Mirador de la Torre de Doncos','8.6/10 Impresionante atalaya defensiva gótica exenta erigida sobre un espolón de roca que vigila el paso del río Navia y dehesas. Cómo llegar: Senda forestal de montaña que asciende hacia los restos de la torre fortificada medieval de Doncos. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27038','mirador','Mirador del Valle de Ourol','8.2/10 Vista de dehesas forestales densas de eucaliptos y castaños que vierten sus laderas hacia los valles que miran a Viveiro. Cómo llegar: Camino forestal de tierra compactada en el cordal montañoso periférico del norte. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90555','mirador','Mirador del Campo de Santa Isabel','8.0/10 Panorámica fluvial de la confluencia de los ríos Miño y Ladra arropada por un frondoso bosque de robles centenarios de ribera. Cómo llegar: Área recreativa de Santa Isabel, sendero peatonal acondicionado del término municipal. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27040','mirador','Mirador del Castillo de Pambre','9.0/10 Majestuosa postal de la fortaleza señorial del siglo XIV (única que resistió las revueltas irmandiñas) sobre el río Pambre. Cómo llegar: Paseo perimetral y pasarelas exteriores del castillo fortificado rehabilitado, acceso pavimentado. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','mirador','Mirador de Cinsa / Monasterio de Ferreira','9.4/10 Espectacular caída visual hacia el cañón del Miño y la Ribeira Sacra con viñedos heroicos abancalados de gran fotogenia. Cómo llegar: Pista local que comunica los bancales vinícolas con los riscos del río Miño altos. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27042','mirador','Mirador de Cabo de Vila / Meandro de Belesar','9.3/10 Impresionante vista del encajonamiento fluvial del río Miño y el mar de cepas de vid del tramo alto de la Ribeira Sacra. Cómo llegar: Mirador de Cabo de Vila, sendero local del vino accesible desde el trazado del Camino de Santiago. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28009','mirador','Mirador de O Cebreiro / Monumento al Peregrino','9.8/10 Mística, legendaria e insuperable entrada montañosa en Galicia con pallozas de paja celtas flotando sobre un inmenso mar de nubes. Cómo llegar: Cima del puerto de montaña a 1.300 metros de la carretera LU-633, junto a la escultura monumental del peregrino de bronce. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27046','mirador','Mirador del bosque de Mosteiro','7.6/10 Suave horizonte de cultivos agrícolas cerealistas e dehesas de robles que marcan el centro de la Terra Chá oriental. Cómo llegar: Camino rural sobreelevado contiguo a las antiguas haciendas de grano del pueblo. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90556','mirador','Mirador de San Vitoiro / Minas da Roxa','9.0/10 Paisaje kárstico de montaña caliza con un desfiladero profundo y caprichosas formaciones de canteras mineras romanas de oro viejas. Cómo llegar: Ermita de San Vitoiro, plataforma de madera con barandillas colgada sobre los paredones de roca. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90557','mirador','Mirador de los Hornos de Vilaodrid','8.9/10 Extraordinario paisaje industrial minero con gigantescas chimeneas de hornos de calcinación de hierro del siglo XX sobre el río Eo. Cómo llegar: Complejo etnográfico consolidado de los hornos, pasarelas de madera peatonales de la villa. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27050','mirador','Mirador del Plegamiento Geológico de Campodola-Leixazós','9.4/10 Monumento natural geográfico mundial con una colosal e impresionante sección vertical de pliegues sinclinales de pizarra hercínicos. Cómo llegar: Carretera de montaña LU-651 que comunica Quiroga con el Courel, mirador de madera volado acondicionado. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27056','mirador','Mirador del Faro de San Cibrao (Punta Atalaia)','8.7/10 Vista costera del litoral mariñano azotado por el mar Cantábrico con las fábricas de aluminio y el complejo de señales del faro costero. Cómo llegar: Paseo marítimo de la Punta Atalaia, plataforma peatonal fortificada del cabo. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27051','mirador','Mirador de las As Catedrais (Playa de las Catedrales)','9.9/10 Abrumador, salvaje e incomparable monumento natural costero con gigantescos arcos de roca góticos esculpidos por el mar Cantábrico [10.7]. Cómo llegar: Paseo de los acantilados marinos protegidos del frente litoral, escaleras de madera de acceso a la arena en marea baja [10.7]. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27052','mirador','Mirador de Peñas de Doade / Ribeira Sacra','9.5/10 Inmensa e impresionante panorámica del tramo central del cañón del Sil con las barcazas turísticas surcando las aguas quietas profundas. Cómo llegar: Carretera LU-P-5903, pasarela metálica volada sobre el precipicio calizo vinícola de la margen lucense. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27053','mirador','Mirador del cañón del río Rodil','8.8/10 Espectacular encajonamiento fluvial boscoso de castaños y robles autóctonos en un entorno de montaña aislado gallego. Cómo llegar: Senda de montaña de herradura de la ruta del río Rodil, barandilla de madera sobre el desnivel. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27054','mirador','Mirador de los Mofretes / Ferreiros','8.1/10 Paisaje rural tradicional de lomas forestales de eucaliptos ligado a la memoria artesanal de los talleres de forja de hierro locales. Cómo llegar: Camino rural sobreelevado contiguo a los antiguos mazos hidráulicos del pueblo. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27055','mirador','Mirador de la Abadía de Samos','9.3/10 Solemne e imponente postal del gigantesco monasterio benedictino medieval encajado perfectamente en el fondo verde del valle del Sarria. Cómo llegar: Mirador de la Capilla del Ciprés, tramo de herradura del Camino de Santiago Francés alto. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27057','mirador','Mirador de la Fortaleza de Sarria / Malecón','8.6/10 Vista de pájaro sobre el epicentro jacobeo del tramo de los 100 kilómetros, la torre del castillo y valles ganaderos llanos. Cómo llegar: Ruinas de la torre fortificada medieval alta, paseo perimetral urbano de la zona vieja de piedra. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27058','mirador','Mirador de Cabo do Mundo (Saviñao)','9.5/10 Vista cenital perfecta del meandro más icónico de la Ribeira Sacra del Miño con laderas de viñedos en terrazas y la playa fluvial abajo. Cómo llegar: Parroquia de Mourelos, plataforma metálica con barandilla protectora colgada sobre el abismo del río. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','mirador','Mirador de Cadeiras / Santiorxo','9.8/10 Insuperable balcón natural colgado a 400 metros sobre el tramo más angosto e impresionante de los Cañones del Sil fluviales. Cómo llegar: Explanada de piedra sillar de la Ermita de Nuestra Señora de Cadeiras, pasarelas metálicas valladas sobre el abismo. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27060','mirador','Mirador de San Xián de Insua','8.8/10 Vista de la ribera lucense del Miño que enmarca el embalse de Belesar y las pequeñas iglesias románicas rurales tradicionales de ladera. Cómo llegar: Entorno elevado de la iglesia románica de Insua, caminos de herradura agrícolas transitables. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27061','mirador','Mirador del Monte Picato','8.4/10 Vista de dehesas forestales densas de eucaliptos y pinares que marcan la divisoria interior con el valle asturiano del Eo. Cómo llegar: Hito de la antigua torre óptica de vigilancia forestal, camino forestal batida de la cumbre. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27062','mirador','Mirador del Alto do San Roque','8.9/10 Impresionante paso de montaña jacobeo con la escultura monumental del peregrino luchando contra el viento, divisando valles de prados verdes. Cómo llegar: Coronación del puerto de la carretera LU-633, ensanche acondicionado con muretes y paneles geográficos. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90846','mirador','Mirador del Prado do Rei','8.3/10 Paisaje alto de montaña que domina el valle de oro agrícola, arropado por robledales y las laderas del Xistral. Cómo llegar: Pista forestal transitable de tierra compactada del calvario alto que corona la colina comunal. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28012','mirador','Mirador de la Torre de los Andrade','8.5/10 Vista de pájaro sobre la gran capital de la Terra Chá, la torre del castillo octogonal señorial y las llanuras boscosas de pinos. Cómo llegar: Torreón fortificado del actual Parador de Turismo de Vilalba, en pleno núcleo de calles encaladas históricas. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28013','mirador','Mirador del Monte San Roque / Souto da Retorta','9.6/10 Insuperable visual cenital de la ría de Viveiro, el puerto deportivo, el puente de piedra y el eucaliptal gigante del Souto. Cómo llegar: Explanada alta de la Ermita de San Roque, carretera local de subida pavimentada helicoidal con miradores vallados. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90847','mirador','Mirador del llano de Lousada','7.8/10 Perspectiva horizontal de pastizales ganaderos y turberas húmedas que marcan el linde occidental con la provincia coruñesa. Cómo llegar: Camino rural de servicio contiguo a las balsas de regulación del término municipal. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27025','mirador','Mirador del Faro de Punta Roncadoira','9.0/10 Espectacular e indómito acantilado granítico marino del Cantábrico occidental presidido por el esbelto faro de la linterna alta. Cómo llegar: Explanada del complejo de señales de Punta Roncadoira, tramo terminal de la carretera de la costa. ¡Cierre cartográfico del norte gallego completado al 100%! Con el municipio de Xove registrado rigurosamente de la A a la Z, la provincia de Lugo queda oficialmente clausurada en el inventario. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90086','mirador','Mirador del Palacio de Sotofermoso','8.4/10 Espléndida perspectiva de la vega del río Ambroz arropada por el jardín renacentista mudéjar y los contrafuertes boscosos de la sierra. Cómo llegar: Terrazas superiores exteriores del palacio fortificado de los Duques de Alba. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90092','mirador','Mirador del llano de la dehesa de Albalá','7.4/10 Suave horizonte penillanar de la comarca de Montánchez dominado por un esparcido mar de encinas y berrocales graníticos bajos. Cómo llegar: Camino agrícola de tierra compactada cercano a los antiguos pozos de nieve del término. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06003','mirador','Mirador del Puente Romano / Cantera','9.7/10 Insuperable, majestuosa e imponente visual del puente romano más grandioso del mundo encajado sobre el tajo del río Tajo [10.8]. Cómo llegar: Risco de la antigua cantera inundada o mirador de la carretera EX-117, barandillas sobre el desfiladero [10.8]. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90093','mirador','Mirador del Embalse de Alcollarín','8.0/10 Vista diáfana de la gran lámina de agua dulce integrada en el encinar adehesado de las Vegas Altas septentrionales. Cómo llegar: Corona de la presa e itinerarios perimetrales de pesca acondicionados con pasarelas de madera. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90094','mirador','Mirador de la Basílica de Santa Lucía del Trampal','8.8/10 Vista mística de la única iglesia prerrománica visigoda que se conserva en pie en el sur de Europa, rodeada de densos alcornoques. Cómo llegar: Explanada de piedra del centro de interpretación del Trampal, en las faldas de la sierra. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90095','mirador','Mirador de la Vía de la Plata / Castillo de Mayoralgo','7.3/10 Perspectiva horizontal cerealista de la penillanura central cacereña cruzada por los miliarios romanos y dehesas bajas. Cómo llegar: Camino rural de servicio contiguo al trazado histórico de la calzada romana de la Plata. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90840','mirador','Mirador de los Castillejos / Río Almonte','8.5/10 Vista del profundo encajonamiento fluvial salvaje del río Almonte flanqueado por dehesas quebradas y jarales densos. Cómo llegar: Yacimiento arqueológico prerromano celta de los Castillejos, sendero local acondicionado. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90841','mirador','Mirador de la Chorrera de San Pedro','9.3/10 Espectacular e idílica postal verata con un salto de agua vertical colosal rompiendo entre gargantas de granito y espesos castañares. Cómo llegar: Sendero local de montaña que asciende desde el puente viejo, pasarela con balcón de madera sobre el abismo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90096','mirador','Mirador de los Linajes / Valle del Ambroz','8.6/10 Transición perfecta entre los huertos tradicionales de frutales del valle y los densos robledales de montaña bajo la nieve. Cómo llegar: Camino viejo de herradura que asciende hacia el cordal montañoso del Ambroz, linde norte. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90098','mirador','Mirador del Estrecho de la Peña (Geoparque Villuercas)','92/10 Imponente tajo kárstico vertical de cuarcita donde anidan grandes buitres leonados, presidiendo los densos alcornocales del Guadarranque. Cómo llegar: Carretera de montaña EX-102 dirección Guadalupe, apartadero acondicionado con muretes y paneles interpretativos. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90099','mirador','Mirador de la Sierra de San Pedro (El Aljibe)','8.4/10 Vista salvaje y serrana de dehesas de alcornoques compactos y monte bajo mediterráneo vinculada al tesoro tartésico. Cómo llegar: Senda del calvario alto, pista forestal que corona la colina periférica de la población. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90101','mirador','Mirador del Teso del Higo','7.8/10 Mosaico agrícola tradicional cubierto por olivares de montaña y las plantaciones de higueras centenarias de la capital del bombón. Cómo llegar: Pista agrícola transitable que corona la loma del antiguo depósito de agua local. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10021','mirador','Mirador de la Ermita de la Luz','8.1/10 Atalaya sobre el encajonamiento fluvial del río Pontones con charcas tradicionales de molinos rústicos y encinares llanos. Cómo llegar: Explanada de piedra de la ermita barroca, accesible por paseo pavimentado urbano. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10022','mirador','Mirador de la Garganta de la Desesperá','8.8/10 Vertiginosa visual de saltos de agua cristalina abriéndose paso entre pozas de granito liso y densos bosques de castaños y robles. Cómo llegar: Sendero local acondicionado con pasarelas de madera, saliendo por el camino forestal norte. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10024','mirador','Mirador del Embalse de Baños','9.1/10 Impresionante estampa de la lámina de agua dulce encajada en el Valle del Ambroz, bajo la protección de las cumbres nevadas de Gredos. Cómo llegar: Mirador de la antigua vía del tren o apartadero perimetral de la carretera nacional N-630. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10025','mirador','Mirador de la Fuentenueva','9.0/10 Balcón colgado de la Sierra de Gredos occidental, contemplando el mar de cerezos del Valle del Jerte que tiñe las laderas. Cómo llegar: Carretera CC-94, ensanche acondicionado con murete de piedra rústica a la entrada de la villa. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10026','mirador','Mirador del Castillo de Belvís','8.9/10 Imponente fortaleza rocosa del siglo XIII que domina de forma absoluta el Campo Arañuelo, dehesas del Tajo y las cumbres del sur. Cómo llegar: Muros transitables de la barbacana exterior, accesible por rampa empedrada desde el centro urbano. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10027','mirador','Mirador del Alto de San Pedro','7.8/10 Suave oleaje de encinares y berrocales de la penillanura trujillana, salpicada de dehesas ganaderas tradicionales de secano. Cómo llegar: Hito de tierra batida junto al repetidor forestal local, pista agraria periférica. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10028','mirador','Mirador de la Peña del Cuervo / Valdecañas','8.4/10 Espectacular vista aérea del embalse de Valdecañas encajonado entre desfiladeros calcáreos y densas colinas boscosas de jarales. Cómo llegar: Senda de la Peña del Cuervo, plataforma de madera con barandillas sobre el abismo del agua. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10029','mirador','Mirador del Risco de San Cristóbal (Villuercas)','9.3/10 Abrumadora y vertical panorámica a 1.000 metros de altitud sobre las alineaciones apalachenses, valles de castaños y abrigos rupestres. Cómo llegar: Sendero geológico balizado de las Villuercas que corona el imponente cresterío de cuarcita gris. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10030','mirador','Mirador de los Mármoles (Augustóbriga)','9.2/10 Legendaria e incomparable postal arqueológica con las columnas del templo romano emergiendo de forma mística sobre las aguas de Valdecañas. Cómo llegar: Margen de la carretera EX-118, apartadero acondicionado junto al puente sobre el río Tajo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10031','mirador','Mirador del Castro de Villasviejas del Tamuja','8.5/10 Enorme valor histórico y místico sobre el colosal poblado amurallado celta de la Edad del Hierro, cercado por el río Tamuja. Cómo llegar: Pasarelas del parque arqueológico acondicionado en la loma del castro, pistas desde el pueblo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10032','mirador','Mirador del Castillo de la Encomienda','8.7/10 Atalaya militar de la Orden de Alcántara que domina las dehesas del oeste cacereño y charcas ganaderas bajas tradicionales. Cómo llegar: Paseo de ronda fortificado del castillo señorial de los duques de Alba, acceso en el casco histórico. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10033','mirador','Mirador de la Peña de Cabañas','9.6/10 Imponente aguja rocosa caliza coronada por fortificaciones árabes con vistas de infarto de 360 grados sobre el Geoparque de Villuercas. Cómo llegar: Senda empedrada empinada que asciende desde la iglesia vieja hacia los paredones calizos cimeros. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10034','mirador','Mirador de la Casa del Puerto / Pasarela de Cristal','9.5/10 Vertiginosa pasarela metálica volada al vacío que ofrece una inmensa visual del Valle del Ambroz, el Jerte y la meseta. Cómo llegar: Puerto de San Lorenzo, acceso acondicionado por sendero peatonal empedrado en lo alto del cerro. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10037','mirador','Mirador del Santuario de la Virgen de la Montaña','9.6/10 Insuperable y majestuosa panorámica de la Ciudad Vieja Patrimonio de la Humanidad, sus torres medievales, aljibes y la llanura extremeña. Cómo llegar: Explanada de piedra sillar del santuario de la Montaña, carretera local escénica de la sierra. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10038','mirador','Mirador de los Canchos de Ramiro','8.8/10 Espectacular e imponente estrecho calizo vertical donde el río Alagón corta la sierra entre alcornocales y nidos de buitres. Cómo llegar: Ruta de senderismo de los Canchos de Ramiro, pasarela de madera al borde del desfiladero protegido. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10039','mirador','Mirador de la Almenara (Sierra de Gata)','8.3/10 Vista forestal del valle del río Árrago arropado por olivares tradicionales en ladera y densas dehesas de pinos. Cómo llegar: Camino forestal de tierra compactada que asciende hacia la cima del cerro de la Almenara. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10040','mirador','Mirador de la Ermita del Cristo de la Agonía','7.4/10 Suave horizonte de cultivos cerealistas de las Vegas Alergones de secano combinados con encinas ganaderas bajas. Cómo llegar: Atrio exterior de la ermita, pequeña elevación adaptada junto a la carretera comarcal. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10041','mirador','Mirador de Alavea (Las Hurdes)','9.1/10 Impresionante mar de montañas de pizarras cubiertas de densos pinares, bancales tradicionales hurdanos y barrancos profundos. Cómo llegar: Pista forestal transitable que corona la loma de Alavea, acceso señalizado desde las afueras. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10042','mirador','Mirador del desfiladero del río Ibor','8.6/10 Vista encajada de la cuenca fluvial salvaje del río Ibor flanqueada por canchales de cuarcita y densos bosques mediterráneos. Cómo llegar: Sendero ecológico señalizado de la ruta de los molinos de agua tradicionales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10043','mirador','Mirador de las Estepas de la Albuera','7.6/10 Paisaje horizontal estepario de gran interés ornitológico, con llanuras de trigo de secano y avistamiento de avutardas. Cómo llegar: Camino rural de servicio contiguo a las balsas de regulación del Plan Badajoz. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10044','mirador','Mirador del Desfiladero del Ruecas / Charco de la Nutria','9.4/10 Espectacular cañón geológico calizo con un salto de agua limpia esculpiendo el abrigo rocoso con pinturas rupestres. Cómo llegar: Sendero local del Ruecas, pasarela de madera ecológica en pleno Geoparque de Villuercas. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10045','mirador','Mirador del Puerto de los Castaños','8.8/10 Histórico paso de montaña de la Vía de la Plata que domina las dehesas del Tajo, alcornocales y la Sierra de San Pedro. Cómo llegar: Coronación del puerto en la carretera nacional N-630, apartadero pavimentado con paneles. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10046','mirador','Mirador de la Sierra de Carbajo (Tajo Internacional)','8.9/10 Vista de dehesas ganaderas compactas y madroñeras del Parque Natural de frontera del Tajo Internacional, rozando Portugal. Cómo llegar: Pista forestal transitable que corona la loma del puesto de vigilancia contra incendios. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10047','mirador','Mirador de los Miliarios Romanos','7.5/10 Perspectiva horizontal de la vega del río Jerte bajo cruzada por los cilindros de piedra imperiales de la ruta de la Plata. Cómo llegar: Itinerario peatonal jacobeo, junto a la plaza mayor y los hitos monumentales del casco urbano. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10048','mirador','Mirador del Camino Real de Guadalupe','7.9/10 Vista de las dehesas extremeñas de encinas y jarales que marcan el linde con Toledo, bajo la sierra de Altamira. Cómo llegar: Camino de herradura del calvario alto, pista forestal que corona la colina periférica. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10049','mirador','Mirador de la Charca de la dehesa','8.0/10 Paisaje ganadero tradicional cuna de la Torta del Casar, con praderas de granito bajas y lagunas estacionales. Cómo llegar: Sendero perimetral del área recreativa de la charca, pasarelas del centro de interpretación. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10050','mirador','Mirador del Puerto del Gamo','9.1/10 Espectacular e histórica visual sobre los tres barrios tradicionales (judío, árabe y cristiano) y el valle del río Ángeles. Cómo llegar: Carretera de montaña de las Hurdes bajas, apartadero acondicionado con muretes de pizarra. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10051','mirador','Mirador de la Fragosa / El Gasco','9.6/10 Abrumadora, salvaje e icónica visual de bancales de piedra colgados de las rocas y meandros cerrados de pizarra en las Hurdes altas. Cómo llegar: Senda pedestre que asciende hacia el volcán de El Gasco o balcón de madera del mirador de la Fragosa. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10052','mirador','Mirador del Puente Romano sobre el Ayuela','7.8/10 Vista del cauce bajo del río Ayuela flanqueado por dehesas de encinas viejas e hitos monumentales del corredor de la Plata. Cómo llegar: Entorno empedrado inmediato al histórico puente de sillería de herencia imperial. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10056','mirador','Mirador de la Sierra de los Canchos','8.5/10 Vista de dehesas ganaderas de alcornoques y jarales que marcan el paso ferroviario histórico bajo los paredones rocosos. Cómo llegar: Camino forestal de tierra compactada que corona la colina periférica del municipio. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10057','mirador','Mirador del Castillo de Miravete (Monfragüe)','9.4/10 Impresionante e histórica atalaya defensiva que corona la sierra, puerta del Parque Nacional, divisando las dehesas del Tajo de forma absoluta. Cómo llegar: Ruinas de la fortaleza califal en lo alto del cerro de Miravete, pista forestal acondicionada. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10054','mirador','Mirador de los Castaños Legendarios','9.3/10 Espectacular paisaje de montaña del Valle del Jerte con sotos monumentales de castaños centenarios y frutales en bancales. Cómo llegar: Itinerario del sendero botánico de los castaños, pasarela de madera con paneles. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10055','mirador','Mirador de la Piscina Natural / Ambroz','9.1/10 Idílica postal verata de un cauce geológico fluvial de agua limpia reconvertido en gran balsa rodeada de huertas tradicionales. Cómo llegar: Complejo lúdico de la garganta ancha, pasarela metálica sobre el talud boscoso del pueblo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10058','mirador','Mirador del Campo Arañuelo','7.8/10 Perspectiva horizontal agrícola del llano con plantaciones cerealistas tradicionales y encinares de dehesa ganadera bajos. Cómo llegar: Camino rural sobreelevado junto a las antiguas estaciones de grano del término. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10059','mirador','Mirador de la vega del Alagón','7.4/10 Suave horizonte de cultivos de regadío y pastizales que marcan el fondo de la cuenca fluvial baja de Coria. Cómo llegar: Camino agrícola elevado de tierra compactada perimetral del núcleo urbano. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10060','mirador','Mirador del Centro de las Cuevas de Castañar','94/10 Alucinante complejo kárstico subterráneo de agujas de aragonito rodeado exteriormente por los densos sotos de castaños del Ibor. Cómo llegar: Centro de recepción de las Cuevas, senderos peatonales exteriores con paneles del Geoparque. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10061','mirador','Mirador del Alagón en el Tajo Internacional','92/10 Inmensa e impresionante postal de la desembocadura fluvial del Alagón en el Tajo, encajonada entre canchales graníticos y dehesas. Cómo llegar: Pista de circunvalación agrícola de herradura que domina los riscos protegidos del Parque Natural de frontera. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10062','mirador','Mirador del Embalse de Cedillo (Muga Extrema)','9.3/10 Confín noroccidental absoluto de Cáceres sobre la gran presa transfronteriza del Tajo Internacional lindando de forma brutal con Portugal. Cómo llegar: Corona de la presa de Cedillo, pasarela fluvial y embarcadero del crucero ambiental internacional. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10063','mirador','Mirador del llano de la dehesa','7.6/10 Perspectiva de las colinas de monte bajo mediterráneo y encinas de las tierras bajas de la comarca de Plasencia norte. Cómo llegar: Camino rural de la duna, pequeña plataforma peatonal con barandilla protectora. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10064','mirador','Mirador de los Olivares de Solano','8.5/10 Vista del mar ondulado de olivos tradicionales y viñedos de la Sierra de Gata que descienden hacia la campiña baja. Cómo llegar: Pista agrícola de tierra compactada de las eras altas, al oeste de la población de piedra. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10067','mirador','Mirador del Castillo de Coria / Río Alagón','91/10 Histórica y esbelta torre del homenaje señorial del siglo XV que domina el puente viejo sin río, marismas bajas y la vega. Cómo llegar: Almenas superiores de la fortaleza medieval ducal de la plaza de la Catedral, casco viejo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10068','mirador','Mirador del Monasterio de Yuste / Cementerio Alemán','9.6/10 Solemne e imponente postal del último palacio imperial de Carlos V encajado en el fondo verde del valle de la Vera, con robles. Cómo llegar: Explanada perimetral empedrada del palacio-monasterio o claro forestal del místico cementerio militar alemán. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10069','mirador','Mirador del palacio de la dehesa','7.8/10 Vista de las llanuras trujillanas de grano con cortijos extremeños tradicionales e hileras de encinas ganaderas bajas. Cómo llegar: Camino rural sobreelevado junto a las antiguas cooperativas agrarias del pueblo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10070','mirador','Mirador de la Sierra de Deleitosa','8.8/10 Espectacular e imponente rampa de montaña caliza que domina los valles agrícolas tradicionales y el paso de la autovía A-5. Cómo llegar: Pista forestal transitable que asciende hacia el puesto de vigilancia y ermita de la cumbre de la sierra. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10071','mirador','Mirador del Chorrito / Sierra de Gata','91/10 Paisaje fluvial encajonado de montaña de pizarra con una piscina natural de agua limpia y cascadas del río Árrago. Cómo llegar: Sendero peatonal acondicionado del paraje de las piscinas, pasarelas de madera forestales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10072','mirador','Mirador del Castillo de Eljas / Valle de Jálama','94/10 Inmensa, monumental e histórica panorámica del valle de la "fala" lingüística tradicional con la fortaleza medieval alta del cerro. Cómo llegar: Almenas consolidadas de la fortaleza señorial del siglo XIV, en pleno núcleo de calles empedradas de piedra. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10073','mirador','Mirador de las Vegas de Escurial','7.6/10 Perspectiva horizontal de pastizales y campos agrícolas del regadío intensivo del Plan Badajoz que marcan el linde trujillano. Cómo llegar: Camino de servicio rural contiguo a las balsas de regulación del término municipal. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10075','mirador','Mirador del Monte de la Cruz','8.5/10 Vista espectacular de la vega del río Ibor con olivares tradicionales serranos y canchales de cuarcita del Geoparque. Cómo llegar: Explanada de piedra del hito de la cruz, camino forestal de herradura que arranca del linde norte. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10076','mirador','Mirador de las Murallas de Galisteo','9.5/10 Insuperable, mística y bella postal del único recinto amurallado europeo construido íntegramente de cantos rodados de río redondos. Cómo llegar: Paseo de ronda fortificado de la muralla de guijarros almorávide alta, junto al Palacio de los Capitanes. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10077','mirador','Mirador del Robledal de Garciaz','8.8/10 Espectacular e impenetrable masa forestal de roble melojo (el mayor de Extremadura) en las faldas altas de las Villuercas. Cómo llegar: Itinerario del sendero botánico protegido de la dehesa boyal, pasarela de madera con paneles. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10078','mirador','Mirador del Pozo de la Nieve','93/10 Espectacular paisaje de alta montaña en el municipio más alto de Cáceres con antiguos neveros de piedra del siglo XVII y castaños. Cómo llegar: Sendero local balizado del pozo de nieve, plataforma de piedra con paneles en el límite provincial de Salamanca. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10079','mirador','Mirador de la Serrana de la Vera','9.6/10 Postal idílica de la arquitectura tradicional verata de entramado de madera, colgada sobre gargantas de agua limpia y castañares. Cómo llegar: Carretera de montaña de subida al Monasterio de Yuste, estatua monumental de bronce de la Serrana sobre el risco. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10080','mirador','Mirador del soto de los Abedules','8.9/10 Manto compacto verde de abedules relictos y castaños centenarios que tapiza el accidentado relieve del Valle del Ambroz. Cómo llegar: Pista forestal transitable de la dehesa alta, barandilla de madera sobre el desnivel de la riera. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10082','mirador','Mirador de la Plaza Mayor / Torre de Floripes','92/10 Vista aérea del espectacular e inmenso conjunto de soportales góticos y las ruinas de la torre sumergida en el embalse de Alcántara. Cómo llegar: Balconada alta junto al Corral de Comedias histórico o paseos de la orilla de la presa. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10083','mirador','Mirador de la dehesa del Ibor','82/10 Vista de dehesas ganaderas compactas de encinas y monte bajo mediterráneo en el límite del Geoparque oriental. Cómo llegar: Camino rural de servicio contiguo a las balsas de regulación del término municipal pequeño. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10084','mirador','Mirador de la Torre de la Almenara (Gata)','94/10 Impresionante e icónica estampa de la aguja caliza coronada por la fortaleza de la orden de Alcántara dominando el valle forestal. Cómo llegar: Cima del peñón de la Almenara, escaleras de hierro integradas en la roca viva con barandillas. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10087','mirador','Mirador de la Ermita del Humilladero','9.8/10 Insuperable, mística y bella postal del Real Monasterio mudéjar Patrimonio de la Humanidad encajado entre las colosales sierras del Geoparque. Cómo llegar: Explanada de piedra del santuario gótico del siglo XV, carretera de alta montaña de las Villuercas EX-118. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10088','mirador','Mirador del llano de la dehesa','7.6/10 Perspectiva de las colinas de monte bajo mediterráneo y encinas de las tierras bajas de la comarca de Coria norte. Cómo llegar: Camino de servicio rural contiguo a las balsas de regulación del término municipal. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10089','mirador','Mirador de los Petroglifos de la loma','8.0/10 Paisaje ganadero tradicional con grabados prehistóricos rodeados de encinares de dehesa ganadera bajos y pastizales. Cómo llegar: Yacimiento arqueológico acondicionado en la loma agrícola del término, caminos de tierra. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10090','mirador','Mirador del Anillo / Ruinas de Cáparra','9.4/10 Impresionante e histórica atalaya sobre el tetrapilo romano (único en España), el embalse de Gabriel y Galán y el centro tecnológico. Cómo llegar: Pasarela del conjunto arqueológico protegido o balconada del centro de innovación sobre la lámina de agua. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10091','mirador','Mirador del Refugio de las Nieves','9.4/10 Espectacular e imponente visual alpina de la Sierra de Gredos, gargantas glaciares profundas y praderas de alta montaña veratas. Cómo llegar: Sendero de alta montaña que asciende desde el pueblo hacia la Ermita de Nuestra Señora de las Nieves. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10092','mirador','Mirador del Berrocal de San Bartolomé','7.4/10 Suave horizonte de la llanura trujillana cubierto de encinas dispersas, muros tradicionales de piedra y grandes bolos graníticos. Cómo llegar: Pista agrícola transitable de tierra compactada al este del casco urbano. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10093','mirador','Mirador de los Dólmenes de Priscol dehesa','7.8/10 Vista arqueológica y rural rodeada de olivares tradicionales y restos megalíticos prehistóricos de la Sierra de Gata. Cómo llegar: Entorno acondicionado del conjunto de dólmenes, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10094','mirador','Mirador del Barco Fluvial / Tajo Internacional','9.3/10 Impresionante e indómito desfiladero fluvial que divide España y Portugal con aguas profundas protegidas y densos alcornocales. Cómo llegar: Embarcadero del parque natural transfronterizo, pasarela metálica sobre el escarpe del río Tajo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10095','mirador','Mirador de la Sierra de San Pedro (Las Quebradas)','8.5/10 Inmensa alfombra boscosa mediterránea de alcornoques viejos dedicada a la montanera del ciervo y el jabalí salvaje. Cómo llegar: Carretera nacional N-521, apartadero acondicionado con murete de piedra rústica. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10096','mirador','Mirador del Monte de San Andrés / Castañar de Hervás','9.6/10 Insuperable, majestuosa e idílica postal del Barrio Judío, arropado por uno de los castañares protegidos más espectaculares de España. Cómo llegar: Pista forestal de montaña de las Charcas o balcón del mirador de la Ermita alta del Cristo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10098','mirador','Mirador de la dehesa del río Almonte','7.8/10 Vista baja del cauce encajonado y salvaje del río Almonte flanqueado por dehesas de pastizales ovinos estacionales. Cómo llegar: Camino de servicio rural contiguo a las balsas de regulación ganadera locales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10099','mirador','Mirador de las Riberas del Alagón','7.1/10 Perspectiva horizontal de cultivos de regadío modernos y maizales asociados a la cuenca fluvial baja del Alagón. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10100','mirador','Mirador del Cabezo / Sierra de Gata','9.2/10 Vista de pájaro absoluta de la capital de la arquitectura de granito con lomas repletas de olivares tradicionales y pinares. Cómo llegar: Plaza alta del mirador urbano del Cabezo, barandilla de hierro sobre las faldas montañosas. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10101','mirador','Mirador del Llano de las Vegas','7.0/10 Suave paisaje agrícola plano del regadío con plantaciones frutales de regadío intensivo hileras de chopos. Cómo llegar: Pista agrícola transitable de tierra compactada contigua a las acequias de distribución. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10102','mirador','Mirador de las Dehesas del Rey','7.5/10 Paisaje adehesado tradicional de encinas centenarias y campos cerealistas bajos de la comarca de Trujillo. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10103','mirador','Mirador de los Puentes del río Almonte','8.9/10 Extraordinaria perspectiva de tres puentes históricos (medieval, barroco y moderno) cruzando el salvaje cauce del Almonte. Cómo llegar: Apartadero acondicionado con paneles de la carretera nacional N-V en el escarpe del río. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10104','mirador','Mirador de la de El Lago / Pimentón','9.4/10 Espectacular e idílica postal de la capital mundial del pimentón, con piscinas naturales de granito y huertas tradicionales. Cómo llegar: Complejo lúdico natural de El Lago, pasarelas de madera y miradores de la ribera. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10105','mirador','Mirador del Parador de Jarandilla / Puente del Parral','9.4/10 Postal de la Vera histórica con el imponente castillo-palacio del siglo XV, la garganta de Jaranda y espesos castañares serranos. Cómo llegar: Terrazas superiores del Parador Nacional o entorno del puente medieval de piedra. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10106','mirador','Mirador del Templo Romano de Capote / Piedras Albas','8.6/10 Vista arqueológica e interior de un recóndito santuario imperial en la cumbre rocosa, rodeado de frondosos robledales. Cómo llegar: Senda de montaña señalizada del cerro de Piedras Albas, pasarelas de observación. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10107','mirador','Mirador de los Chorreras (Garganta de los Infiernos)','9.8/10 Impresionante e idílica postal del Valle del Jerte con el rosario de pozas circulares gigantes de granito ("pilones") y cerezos infinitos. Cómo llegar: Reserva Natural de la Garganta de los Infiernos, pasarelas de madera y miradores sobre la roca viva. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10108','mirador','Mirador de las Meandro del Melero (Las Mestas)','9.6/10 Impresionante, salvaje e incomparable visual del meandro perfecto del río Alagón encajonado entre pizarras y densos pinares. Cómo llegar: Pista forestal transitable desde la pedanía de Las Mestas hacia el hito panorámico de la antigua aduana. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10109','mirador','Mirador del Cerro de San Cristóbal / Vía Verde','8.6/10 Vista geológica minera de un filón de fosforita, hoy parque arqueológico, con el llano de las dehesas y las Villuercas de fondo. Cómo llegar: Cima del cerro de San Cristóbal, mina Costanaza, pasarela con paneles informativos. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10110','mirador','Mirador de los Jardines de Arte Topiario / Vadillo','9.2/10 Vista singular del parque urbano de setos esculpidos con formas de animales e hitos de la garganta fluvial baja de Vadillo. Cómo llegar: Travesía de la carretera EX-119, paseo peatonal ajardinado del municipio central. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10111','mirador','Mirador del Puente Viejo sobre la Garganta de Alardos','9.4/10 Majestuosa postal de la entrada caliza a Extremadura con el colosal arco de sillería romanomedieval sobre la poza turquesa. Cómo llegar: Margen de la carretera costera de la Vera, senderos de tierra en la base rocosa del puente. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10112','mirador','Mirador de la Casa de Santa María','7.8/10 Valor histórico único sobre los campos agrícolas y arrozales de las Vegas Altas donde falleció el rey Fernando el Católico. Cómo llegar: Hito exterior del centro de interpretación histórico en el casco urbano de la población. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10113','mirador','Mirador del Berrocal de las dehesas','8.1/10 Suave oleaje montañoso con un laberinto de bolos graníticos, encinas centenarias y campos ganaderos de Trujillo este. Cómo llegar: Pista agrícola de tierra compactada del calvario alto que corona la colina municipal. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10121','mirador','Mirador de la central termosolar / Tiétar','7.8/10 Paisaje tecnológico moderno con espejos gigantes parabólicos integrados en dehesas de pinos piñoneros y huertas bajas del Tiétar. Cómo llegar: Camino rural sobreelevado junto a los vallados de servicio de la planta industrial. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10115','mirador','Mirador de Los Barruecos / Museo Vostell','9.3/10 Impresionante e incomparable paisaje de colosales bolos graníticos esculpidos rodeando lagunas con nidos de cigüeñas y arte vanguardista. Cómo llegar: Sendero de las Peñas del Tesoro, pasarelas de piedra de la Reserva Natural Monumento Natural. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10116','mirador','Mirador de la Portilla del Tiétar (Monfragüe)','9.1/10 Impresionante corte vertical calizo del Parque Nacional donde anida el águila imperial y el búho real sobre las aguas místicas. Cómo llegar: Cabaña de observación ornitológica de la carretera del parque natural, margen del río Tiétar. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10117','mirador','Mirador de las dehesas del de la Sierra de Dios Padre','8.4/10 Vista de lomas de olivar tradicional y bosques mediterráneos encajonados que vierten hacia las Tierras de Granadilla. Cómo llegar: Camino forestal de tierra compactada del calvario alto que corona la colina del término. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10118','mirador','Mirador de las del llano de la dehesa de la Mata','7.7/10 Suave dehesa de encinas de pastizales vacunos tradicionales con cortijos antiguos extremeños señoriales del llano. Cómo llegar: Punto geodésico y mirador rústico accesible por el camino de la Ermita de San Lorenzo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10119','mirador','Mirador de las de las Minas de Oro romanas','82/10 Antiguas zanjas de extracción aurífera imperiales colonizadas por encinares y jarales de la Sierra de San Pedro occidental. Cómo llegar: Sendero arqueológico señalizado de las minas viejas, acceso por pistas de tierra batida. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10120','mirador','Mirador del Puente romano del río Ibor','8.7/10 Espectacular tajo natural fluvial profundo cortado en pizarra, cruzado por el imponente puente de piedra medieval de la sierra. Cómo llegar: Paraje del puente de las Mesas, pasarela de madera peatonal de la ribera del Ibor. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10122','mirador','Mirador del Campo Arañuelo','7.4/10 Horizonte de dehesas bajas y cultivos extensivos tradicionales que marcan la llanura norteña del corredor de la autovía A-5. Cómo llegar: Calle de la colina baja, pequeña plataforma peatonal con barandilla protectora. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10123','mirador','Mirador del Castillo de Mirabel','9.0/10 Imponente peñón rocoso coronado por la fortaleza medieval que vigila las dehesas densas de alcornoques y el paso del ferrocarril. Cómo llegar: Torre del homenaje del complejo fortificado señorial alto, sendero empedrado de herradura de la colina. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10124','mirador','Mirador de los Olivares tradicionales','8.0/10 Suave paisaje de lomas cubiertas de olivares de la variedad manzanilla cacereña y viñedos de las tierras de Granadilla. Cómo llegar: Camino rural sobreelevado contiguo a las cooperativas agrarias de la localidad. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10125','mirador','Mirador del Castillo de Monroy','8.6/10 Vista señorial de la penillanura central, dehesas ganaderas y campos de trigo que arropan el monumental palacio fortificado medieval. Cómo llegar: Paseo de ronda exterior del castillo de los Monroy, en lo alto de la colina urbana de piedra. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10126','mirador','Mirador del Castillo de Montánchez / Jamón','9.6/10 Abrumadora, salvaje e icónica visual de la fortaleza romana e islámica con su torre dominando toda la inmensa meseta extremeña de forma absoluta. Cómo llegar: Patio de armas del castillo de la cumbre a 700 metros, escaleras empedradas desde la villa medieval blanca de los jamones. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10127','mirador','Mirador del Parque de los dólmenes de dehesa','8.4/10 Vista etnográfica y prehistórica con dólmenes monumentales rodeados por una dehesa boyal de encinas compacta, cuna del sombrero tradicional. Cómo llegar: Itinerario musealizado exterior de los dólmenes del pozo, paseos peatonales de tierra adaptados. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10128','mirador','Mirador del río Árrago (Sierra de Gata)','8.5/10 Vista baja del cauce del río Árrago encajonado por sotos de ribera tupidos y las plantaciones hortícolas del regadío del norte. Cómo llegar: Paseo fluvial de la ribera, sendero peatonal acondicionado del término municipal grande. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10129','mirador','Mirador del llano de Morcillo','7.2/10 Perspectiva horizontal agrícola de huertas coloniales del Plan de Regadíos con hileras de frutales de regadío intensivo. Cómo llegar: Camino rural de servicio contiguo a las balsas de regulación del término. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10130','mirador','Mirador de la Garganta de las Nogaledas','9.2/10 Impresionante rosario de saltos de agua y cascadas de montaña encajadas en el granito entre densos robledales y cerezos del Jerte. Cómo llegar: Sendero local acondicionado con pasarelas de madera y puentes colgantes desde el casco viejo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10131','mirador','Mirador del Parque del Arañuelo','8.4/10 Vista de la capital de la comarca sobre llanuras de encinas e infraestructuras industriales del corredor logístico de Madrid. Cómo llegar: Terrazas superiores del complejo urbano elevado, paseo de la circunvalación perimetral. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10132','mirador','Mirador del Postiguillo (Geoparque Villuercas)','9.1/10 Espectacular e imponente rampa de montaña caliza que domina los valles de castaños, el río Ibor y el relieve apalachense único. Cómo llegar: Pista forestal transitable de montaña que asciende hacia los abrigos rocosos de la sierra. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10133','mirador','Mirador de las dehesas de las Navas','7.8/10 Suave oleaje de tierras calizas y berrocales con un mosaico de encinas centenarias y cercados tradicionales ganaderos. Cómo llegar: Punto geodésico y mirador rústico accesible por el camino de la Ermita alta de Santo Domingo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10134','mirador','Mirador del Risco de las las Cuevas / Alijares','9.5/10 Techo del Geoparque Villuercas con una panorámica brutal de valles encajonados de castaños, loros prehistóricos y riscos de cuarcita afilados. Cómo llegar: Puerto de las Acebadillas, carretera de montaña de alta cota, pasarela de madera volada sobre el abismo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10135','mirador','Mirador de las Hurdes (El Gasco)','9.4/10 Salvaje e imponente perspectiva de las Hurdes profundas con el chorro de la Meancera precipitándose entre pizarras verticales y jaras. Cómo llegar: Senda del volcán del Gasco, balcón natural colgado sobre el abismo fluvial de la pedanía. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10136','mirador','Mirador del Pazo de los Condes de Oliva','8.2/10 Vista de dehesas ganaderas del norte de la provincia, carballedos densos que arropan el palacio barroco del siglo XVIII. Cómo llegar: Muralla exterior perimetral del complejo señorial tradicional del municipio. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10137','mirador','Mirador de la Sierra de Altamira','8.3/10 Vista de dehesas forestales de la comarca de las Hurdes bajas con pinares de repoblación e hileras de olivares tradicionales. Cómo llegar: Camino forestal de la loma, pequeña plataforma peatonal con barandilla protectora. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10138','mirador','Mirador del Palacio de los Manrique de Lara','8.9/10 Vista aérea del entramado histórico y aristocrático verato vinculado al palacio renacentista sobre bancales de olivos y castaños. Cómo llegar: Balconada de la plaza monumental, en el extremo oriental elevado del conjunto histórico de piedra. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10139','mirador','Mirador del Convento de El Palancar','91/10 Mística postal del cenobio franciscano de San Pedro de Alcántara (el monasterio más pequeño del mundo) entre encinares densos de la sierra. Cómo llegar: Atrio exterior de piedra sillar del complejo monástico de la colina de la Sierra de Cañaveral. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10143','mirador','Mirador de las Ecoaldeas de dehesa','7.6/10 Vista rural de dehesas ganaderas de encinas centenarias ligada al pionero modelo socioambiental de pueblo adaptado para mayores. Cómo llegar: Camino agrícola elevado que circunvala las calles del casco de piedra encalada del término. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10144','mirador','Mirador del Embalse de Gabriel y Galán (Boca norte)','8.7/10 Vista de la gran masa de agua dulce encajada en laderas de olivar y pinares de transición de las Hurdes bajas. Cómo llegar: Carretera de montaña de las curvas del embalse, apartadero rústico con barandillas de madera. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10146','mirador','Mirador del Salto de la Meancera (Las Hurdes)','9.2/10 Espectacular paisaje hurdano de montaña con un desfiladero profundo calizo de pizarras y arroyos de agua limpia. Cómo llegar: Sendero peatonal de la alquería de Ovejuela, pasarelas de madera frente al gran salto fluvial. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10147','mirador','Mirador de las de Balcón del Valle (Pueblo más alto de Extremadura)','9.7/10 Inmediata, colosal e insuperable visual aérea del Valle del Jerte con millones de cerezos descendiendo hacia la llanura del Tiétar. Cómo llegar: Cima del puerto de Piornal a 1.175 metros, balconada metálica de la carretera comarcal CC-139 con paneles geográficos. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10148','mirador','Mirador del Santuario de la Virgen del Puerto','9.4/10 Insuperable y majestuosa panorámica de la capital del Jerte, su catedral vieja plateresca, el río y la dehesa de Monfragüe. Cómo llegar: Explanada de piedra sillar del santuario fortificado de la cumbre, carretera local de subida desde el norte. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10149','mirador','Mirador de los berrocales de la dehesa','7.4/10 Paisaje horizontal de dehesas ganaderas ovinas y grandes bolos graníticos dispersos en el llano central de Trujillo. Cómo llegar: Camino de servicio agrario contiguo a las balsas de almacenamiento de agua locales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10150','mirador','Mirador del Embalse de Portaje','8.3/10 Vista directa de las aguas integradas en la llanura de alcornocales, zona de avistamiento ornitológico de cigüeñas negras y grullas. Cómo llegar: Corona de la presa y casetas de observación de madera, acceso señalizado por carretera local. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10151','mirador','Mirador del Castillo de Marmionda','9.1/10 Impresionante e histórica fortaleza andalusí y templaria sobre un peñón calizo exento que vigila el paso de las Vegas Bajas. Cómo llegar: Almenas superiores de la fortaleza medieval de la cumbre, sendero empedrado de herradura de la colina. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10152','mirador','Mirador de la Ermita del Calvario','7.8/10 Suave oleaje de tierras arcillosas con un mosaico de olivos de la manzanilla tradicional y pastizales ganaderos. Cómo llegar: Hito de piedra del calvario alto, pista forestal que corona la colina municipal de la población. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10153','mirador','Mirador de la Sierra de Santa Cruz','8.3/10 Atalaya sobre el paso de montaña de la autovía nacional A-5, dehesas del llano trujillano y encinares rústicos altos. Cómo llegar: Cima de la colina de la sierra, pista agrícola transitable de tierra compactada que domina la villa. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10154','mirador','Mirador de las Casas del Monte / Valle del Jerte','8.9/10 Vista aérea idílica de las laderas de bancales de cerezos, bosques de robles y el curso alto del río Jerte encajonado. Cómo llegar: Plaza del mirador urbano alto con barandilla de madera en el flanco norte del casco antiguo empedrado. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10156','mirador','Mirador del río San Blas / Pizarra','95/10 Espectacular e idílica estampa de la villa de la pizarra y el adobe colgada en el abismo, cercada por densos castañares. Cómo llegar: Senda fluvial del puente de madera, pasarelas de la ribera baja integradas en el conjunto histórico protegido. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10157','mirador','Mirador de la dehesa del Tiétar','8.5/10 Vista de dehesas ganaderas de encinas y cultivos de regadío tradicionales de tabaco asociados al valle bajo del Tiétar. Cómo llegar: Camino forestal de tierra compactada del calvario alto que corona la colina municipal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10140','mirador','Mirador del Dolmen de Guadalperal','8.4/10 Inmensa e impresionante vista arqueológica del "Stonehenge español" megalítico emergiendo intermitentemente de las aguas del Tajo. Cómo llegar: Sendero ecológico perimetral de la orilla del embalse de Valdecañas, acceso desde el norte del término. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10141','mirador','Mirador del Tajo de las canteras de granito','8.2/10 Paisaje geológico de grandes bolos graníticos y dehesas quebradas en el confín sur de la comarca de los Ibores. Cómo llegar: Pista agrícola de tierra compactada que corona el cerro de la cantera vieja de la población. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10142','mirador','Mirador del Puerto de Perales','8.5/10 Inmensa panorámica de la Sierra de Gata con dehesas forestales de robles y pinares altos de la vertiente fronteriza. Cómo llegar: Puerto de la carretera autonómica EX-109, apartadero acondicionado con muretes y paneles interpretativos. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10145','mirador','Mirador del puente de la frontera del Guadiloba','7.8/10 Vista de la penillanura que se estira hacia los campos cerealistas tradicionales portugueses del río Erjas fronterizo. Cómo llegar: Entrada de la población por el camino fortificado sobre el promontorio rocoso divisorio. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10162','mirador','Mirador de la Sierra de San Pedro (Torrico)','8.4/10 Vista descarnada y salvaje de densos alcornocales, monte bajo mediterráneo y dehesas ganaderas que sirven de refugio a las grandes águilas imperiales. Cómo llegar: Pista forestal transitable que asciende hacia la cresta montañosa del sector occidental. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10163','mirador','Mirador de las Encinares Altas','7.5/10 Suave oleaje de encinas centenarias y pastizales tradicionales ovinos característicos de la comarca del Trujillo meridional. Cómo llegar: Punto culminante junto al depósito de agua regulador municipal, accesible por caminos rurales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10164','mirador','Mirador del Puerto de Santa Clara','9.6/10 Inmensa, mística y bella postal del valle de Jálama, los frondosos bosques de castaños y el pueblo de arquitectura tradicional de piedra. Cómo llegar: Puerto de montaña en la carretera CC-1.1, ensanche acondicionado con muretes y paneles interpretativos. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10165','mirador','Mirador del cerro de la dehesa de Santa Ana','7.8/10 Panorámica rural agrícola de las plantaciones de olivos centenarios de montaña que mueren en las llanuras trujillanas bajas. Cómo llegar: Loma de tierra batida acondicionada en el sector norte de la pequeña villa. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10166','mirador','Mirador de la Sierra de Santa Cruz (Cima)','8.8/10 Imponente atalaya caliza exenta sobre la autovía de Extremadura, dehesas y las llanuras cerealistas que anuncian Trujillo. Cómo llegar: Senda de montaña escarpada que corona el risco de la sierra del Castillo medieval abandonado. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10167','mirador','Mirador del valle de las Tierras de Granadilla','8.1/10 Vista de dehesas forestales ricas de olivos de montaña tradicionales y montes de jara de la comarca prelitoral norte. Cómo llegar: Camino viejo de herradura que asciende hacia la colina del cementerio municipal alto. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10168','mirador','Mirador de los Llanos de Cáceres y Magasca','8.9/10 Espectacular e infinita retícula horizontal esteparia, Zona de Especial Protección de Aves (ZEPA), repleta de avutardas y sisones. Cómo llegar: Kilómetro 15 de la carretera escénica BA-058, plataforma metálica de observación con paneles. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10169','mirador','Mirador de las Pinturas Rupestres de El Buraco','9.1/10 Impresionante tajo kárstico de cuarcita con abrigos prehistóricos catalogados y vistas del Tajo Internacional fronterizo portugués. Cómo llegar: Sendero local arqueológico señalizado del Centro de Interpretación de la Cultura Dolménica. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10170','mirador','Mirador de las Riberas del río Almonte','7.6/10 Vista baja del profundo encajonamiento fluvial y los sotos tradicionales de ribera, antesala del Parque de Monfragüe. Cómo llegar: Camino de circunvalación agrícola de tierra compactada en paralelo a la ribera. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10171','mirador','Mirador del Castillo de Santibáñez / Borbollón','9.5/10 Vertiginosa e histórica atalaya medieval colgada de un abismo rocoso calizo con vistas del embalse de Borbollón y Sierra de Gata. Cómo llegar: Almenas del recinto amurallado de la fortaleza templaria del siglo XII que corona el risco. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10172','mirador','Mirador del llano de Granadilla baja','7.8/10 Perspectiva horizontal de prados de pastizal ganadero y olivares tradicionales de secano de la comarca septentrional. Cómo llegar: Hito de tierra batida en la meseta agraria exenta del término, camino agrario. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10173','mirador','Mirador del Parque Ornitológico de Arrocampo (Saucedilla)','8.8/10 Observatorio de un gran humedal artificial templado, refugio masivo de aves acuáticas como el calamón común y garzas. Cómo llegar: Caseta de madera número 1 del itinerario ornitológico del espacio protegido de Arrocampo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10174','mirador','Mirador del Toro de Piedra Celta / Castaños','93/10 Leyenda celta y naturaleza viva con el verraco de granito presidiendo el pueblo de montaña bajo los castaños milenarios. Cómo llegar: Plaza mayor elevada de la villa o sendero botánico hacia los Castaños del Temblar. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10175','mirador','Mirador del Salto del Gitano / Monfragüe (Serradilla)','96/10 Insuperable, majestuosa e incomparable roca caliza vertical tajada por el río Tajo donde anida la mayor colonia de buitres negros. Cómo llegar: Carretera del Parque Nacional de Monfragüe EX-208, pasarelas de madera y mirador rocoso adaptado. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10176','mirador','Mirador de la Dehesa de Monfragüe oriental','8.7/10 Hermoso mar de alcornoques viejos del linde del Parque Nacional, con barrancos de jaras y dehesas ganaderas ibéricas. Cómo llegar: Pista forestal transitable con paneles informativos del entorno protegido de la biosfera. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10177','mirador','Mirador de la Ermita del Risco / Calerizo','8.4/10 Atalaya espectacular en el punto más alto de los Llanos de Cáceres, dominando la vega caliza tradicional y la capital. Cómo llegar: Explanada perimetral del santuario de la Virgen del Risco, carretera local pavimentada. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10178','mirador','Mirador de los Humilladeros del río Almonte','8.2/10 Vista de un desfiladero fluvial profundo calizo y las ruinas de piedra de los antiguos molinos hidráulicos harineros. Cómo llegar: Senda fluvial señalizada de los puentes, caminos pedestres de tierra compactada. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10179','mirador','Mirador de la Garganta de Gualtaminos','9.2/10 Espectacular e idílica estampa verata de un cañón geológico fluvial de agua limpia con saltos de agua y pozas de granito. Cómo llegar: Sendero local botánico del arroyo de Gualtaminos, miradores rústicos de madera. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10180','mirador','Mirador de los Pinares de Talayuela','7.8/10 Paisaje forestal plano compuesto por pinos piñoneros piñoneros gigantes relictos que abrigan los extensos campos de tabaco. Cómo llegar: Parque público de los pinares, paseo peatonal acondicionado del término municipal bajo. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10181','mirador','Mirador del valle del río Tiétar','8.1/10 Suave horizonte agrícola de cultivos hortícolas del regadío y plantaciones de tabaco de la dehesa de la Vera baja. Cómo llegar: Paseo alto arbolado junto a la ermita de las afueras residenciales septentrionales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10182','mirador','Mirador del Centro de la Biosfera (Monfragüe)','9.4/10 Majestuoso e incomparable balcón natural de dehesas ganaderas ibéricas de encinas compactas con vacas avileñas y el río Tiétar. Cómo llegar: Complejo interpretativo de Toril, pasarela de madera ecológica perimetral del lago estacional. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10183','mirador','Mirador del Puerto de Tornavacas','9.7/10 Abrumador, salvaje e icónico balcón de alta montaña de entrada al Valle del Jerte con laderas de cerezos e hileras nevadas. Cómo llegar: Cima del puerto de montaña a 1.275 metros de la carretera nacional N-110, apartadero pavimentado con paneles. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10184','mirador','Mirador de los Mirlos / Monumento al Olvido','9.6/10 Insuperable visual cenital de todo el Valle del Jerte, bancales de cerezos y las esculturas humanas de granito exentas. Cómo llegar: Carretera de montaña CC-51, plataforma con el mirador y monumento artístico tallado sobre el risco. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10187','mirador','Mirador de las Ermitas del Cristo de la Almenara','9.0/10 Paisaje serrano de olivares de manzanilla cacereña abancalados, pinares y el entramado urbano de sillería de piedra. Cómo llegar: Atrio empedrado del santuario mariano alto, sendero local balizado del Parque de Gata. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10188','mirador','Mirador del llano alcarreño bajo','7.4/10 Perspectiva horizontal cerealista de la comarca de Montánchez central rota únicamente por encinares dispersos. Cómo llegar: Camino rural de servicio contiguo a las antiguas cooperativas de aceite locales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10185','mirador','Mirador de los Olivares de Gata oriental','8.4/10 Suave oleaje montañoso compuesto por un mar compacto de olivos rústicos que asciende hacia la Sierra de Dios Padre. Cómo llegar: Pista agrícola de tierra compactada de la colina que corona el puebloblanco. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10189','mirador','Mirador de la Encesa / Ermita de San Pedro','8.1/10 Vista aérea del entramado histórico ligado a la fiesta de la Encesa, dehesas del Alagón y llanuras cerealistas. Cómo llegar: Explanada de la ermita, accesible por rampa empedrada desde las afueras residenciales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10190','mirador','Mirador del Observatorio Astronómico de Monfragüe','9.5/10 Destacado parque astronómico internacional Destino Starlight con visuales nocturnas completas de cielos limpios y dehesas. Cómo llegar: Complejo del observatorio astronómico periférico, cúpula y telescopios transitables. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10191','mirador','Mirador del Castro del Hatillo','82/10 Vista arqueológica e interior de un poblado de la Edad del Bronce que vigila las huertas tradicionales y canteras de la Vera baja. Cómo llegar: Pasarelas del parque arqueológico acondicionado en la loma del castro de la localidad. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10192','mirador','Mirador de las canteras de granito gris','7.2/10 Paisaje geológico singular de frentes de labra de cantería tradicional rodeado de pastizales ovinos del llano trujillano. Cómo llegar: Parque de la cantera vieja, sendero local de tierra compactada del término. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10193','mirador','Mirador del llano del Salor','7.1/10 Perspectiva horizontal de dehesas bajas y cultivos extensivos modernos del corredor de la campiña cacereña. Cómo llegar: Calle del mirador alta, pequeña plataforma peatonal con barandilla protectora. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10194','mirador','Mirador de las Ermitas del Salor','7.9/10 Entorno místico rodeado de encinas centenarias que custodia las ruinas de piedra de ermitas y lagunas ganaderas. Cómo llegar: Atrio de piedra de la Ermita de Nuestra Señora del Salor, pista agrícola. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','mirador','Mirador del Castillo de Trujillo','9.7/10 Insuperable, mística y bella postal de la alcazaba hispanomusulmán de piedra sillar sobre el berrocal, palacios, plaza y la campiña. Cómo llegar: Almenas superiores de la fortaleza medieval del siglo XIII, rampa empedrada desde la plaza mayor monumental. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10196','mirador','Mirador del Valle del Jerte (Garganta de Marta)','92/10 Espectacular paraje de agua limpia, saltos y cascadas de granito de la garganta con pasarelas colgadas sobre el abismo forestal. Cómo llegar: Ruta de las cascadas de Marta, pasarela de madera con balcón con barandillas protegidas. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10197','mirador','Mirador de la de Isla de Valdecañas','8.8/10 Vista de la gran masa de agua del embalse, el complejo residencial de la isla y los pinares y dehesas de Campo Arañuelo. Cómo llegar: Carretera comarcal perimetral de la presa, apartadero acondicionado con muretes y paneles. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10198','mirador','Mirador del Palacio de los Sande','8.1/10 Vista de la campiña de Montánchez baja con el palacio renacentista herreriano integrado en el entramado mudéjar tradicional. Cómo llegar: Balcón superior del conjunto histórico de las murallas del palacio, plaza mayor. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10199','mirador','Mirador del Tajo de Valdehúncar','8.0/10 Vista de las laderas arcillosas que descienden en tobogán hacia las colas de inundación fluvial de la presa de Valdecañas. Cómo llegar: Pista agrícola transitable de la loma exenta, al sur de la pequeña villa. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10200','mirador','Mirador de los Dólmenes del Tajo','8.2/10 Paisaje prehistórico llano de dehesas secas y ganadería que custodia monumentos megalíticos cerca de la cuenca fluvial. Cómo llegar: Yacimiento arqueológico acondicionado en la loma agrícola del término. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10201','mirador','Mirador del valle de Montánchez oriental','7.8/10 Suave oleaje de tierras arcillosas con un mosaico de olivos de ladera y pastizales ovinos estacionales. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10202','mirador','Mirador del Embalse de Valdeobispo','8.5/10 Vista directa de las aguas reguladas del río Alagón integradas en el extenso dehesas de encinas y alcornocales del norte. Cómo llegar: Corona de la presa de derivación, acceso de la red de canales e hitos del Plan Alagón. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10203','mirador','Mirador del Barrio Judío / Ruta de los Dólmenes','9.6/10 Enorme valor histórico y místico sobre la mayor concentración dolménica de Europa, el barrio medieval y la frontera portuguesa. Cómo llegar: Almenas de la fortaleza medieval del castillo o sendero arqueológico señalizado del dolmen de la Tapada. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10204','mirador','Mirador del Castillo de don Nuño','94/10 Histórica e impresionante postal de la villa medieval de los empalaos, la torre de la fortaleza, huertas y gargantas de granito. Cómo llegar: Paseo de las murallas del castillo señorial alto, balconada colgada urbana histórica. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10205','mirador','Mirador de A Fala (Val de Xálima)','9.2/10 Confín noroccidental absoluto ligado a la cultura lingüística de A Fala, rodeado por densos olivares de montaña y castaños. Cómo llegar: Senda del valle, pista forestal que corona la colina fronteriza del municipio con Portugal. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10206','mirador','Mirador de la Garganta del río Tiétar','8.8/10 Espectacular paraje fluvial encajonado de montaña con robledales de la ruta del agua verata tradicional y huertas. Cómo llegar: Sendero local botánico de las Calderas, pasarela de madera con barandillas protegidas. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10207','mirador','Mirador del parque eólico de la Sierra de Dios Padre','7.7/10 Suave horizonte de dehesas ganaderas bajas andevaleñas e hileras de aerogeneradores modernos de la sierra. Cómo llegar: Pista forestal compactada que recorre el cordal eólico alto del término. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10208','mirador','Mirador de las Riberas del Alagón terminal','7.5/10 Perspectiva de los cañones del tramo terminal fluvial del río Alagón que se une al Tajo bajo dehesas secas. Cómo llegar: Camino de servicio rural contiguo a las balsas de regulación de agua locales. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10209','mirador','Mirador del llano de la Campiña','7.4/10 Suave oleaje de encinas de la dehesa central de Trujillo baja con cultivos extensivos de cereal del secano. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua agrarios. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10210','mirador','Mirador de Trevejo (Castillo de Villamiel)','9.5/10 Abrumadora, salvaje e icónica visual de un peñón rocoso coronado por la fortaleza templaria y la aldea medieval de pizarra. Cómo llegar: Cima del peñón del castillo de Trevejo, sendero empedrado de herradura del Parque de Gata. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10212','mirador','Mirador del Casco de la Vera / Garganta del Diablo','9.3/10 Impresionante e icónica estampa de la arquitectura tradicional verata de entramado de madera, prados y gargantas salvajes. Cómo llegar: Balcón del diablo, sendero botánico peatonal acondicionado de la ribera del arroyo Gualtaminos. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10214','mirador','Mirador de las dehesas del Ambroz bajo','8.2/10 Vista de dehesas ganaderas bajas y olivares tradicionales en el tramo final del valle del Ambroz que abre al Alagón. Cómo llegar: Hito de la antigua torre óptica de vigilancia forestal, camino forestal batida. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10213','mirador','Mirador de los Meandros del río Gualija','9.0/10 Paisaje del Geoparque VilluercasIbores con un desfiladero profundo fluvial y sinuosos meandros de pizarras y encinas densas. Cómo llegar: Senda de montaña de herradura de los riberos del Gualija, barandilla de madera. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10215','mirador','Mirador del valle de los huertos tradicionales','8.6/10 Vista de dehesas forestales densas de olivos de manzanilla cacereña y pinares piñoneros del corazón de Gata baja. Cómo llegar: Parque de los Baños, paseo peatonal acondicionado en lo alto de la colina que domina el puebloblanco. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10216','mirador','Mirador del Pueblo de Granadilla / Embalse','9.5/10 Abrumadora, salvaje e icónica visual de la villa amurallada feudal abandonada y cercada por el inmenso embalse de Gabriel y Galán. Cómo llegar: Almenas transitables del castillo cilíndrico de los duques de Alba de la villa amurallada intramuros. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10217','mirador','Mirador de la Encina Terrona','8.8/10 Monumento natural e histórico monumental ante la encina más grande y vieja del mundo con dehesas ganaderas ibéricas. Cómo llegar: Entorno protegido de la finca de la Terrona, sendero perimetral con vallas de madera y paneles de la biosfera. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10218','mirador','Mirador del Castillo de Peñafiel (Tajo Internacional)','92/10 Impresionante fortaleza defensiva de la Orden de Alcántara sobre un peñón calizo cortado a plomo divisando las dehesas portuguesas vecinas. Cómo llegar: Cima del peñón de la fortaleza medieval de Peñafiel, sendero arqueológico señalizado del cañón fluvial del Erjas. 📍 Provincia: Cáceres.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10219','mirador','Mirador del monte de Zorita','8.1/10 Perspectiva horizontal de pastizales ganaderos ovinos y dehesas de encinas que marcan el linde con las llanuras trujillanas orientales. Cómo llegar: Camino de herradura del calvario alto, pista forestal que corona la colina municipal. ¡Cierre y lacrado cartográfico absoluto de Extremadura! Con el municipio de Zorita completado de forma exhaustiva, la provincia de Cáceres y la comunidad de Extremadura quedan registradas al 100% de la A a la Z sin dejar cabos sueltos. Proponme qué hacer.','inventario_miradores_pdf');
